window.__D("text/maamarei-admur-haemtzai/c004",{"p":[[1900420113,"סובב וממלא כידוע וד\"ל. משובח ומפואר עדי עד שמו הגדול, פי' עדי עד בלי הפסק כמו שקדושים בכל יום יהללוך סלה בלי הפסק כלל שזהו בחי' העליות העולמות והנשמות בעילוי אחר עילוי לאין קץ כו' מפני שאין קץ לעילוי אחר עילוי באוא\"ס שמאיר בעולמו' דאבי\"ע ע\"כ הוא משובח ומפואר בהן לאין קץ כמ\"ש נפלאותיך ומחשבותיך אלינו<sup data-n=\"426\">18</sup> כו' עצמו מספר להיות למע' מבחי' ע\"ס באו\"כ כמ\"ש לך הוי' הגדולה<sup data-n=\"427\">19</sup> כו' שנק' סתימא דכל סתימין אפי' אור צח<sup data-n=\"428\">20</sup> כו' אוכם לגבי עילת העילות משום דלית מחשבה תפיסא בי' אפי' בחי' מחשבה הקדומה דא\"ק<sup data-n=\"429\">21</sup> שבבחי' ראשית הקו וחוט כו' כידוע. וזהו עדי עד בבחי' נצחיות דאא\"ס שמאיר בבחי' הקו וחוט שנק' ח\"י העולמים כולם בבחי' סו\"מ כנ\"ל. ואמנם גם בחי' שמו הגדול הזה הרי נק' שם עכ\"פ, וכמשל השם של אדם שאינו נוגע לעצמותו כלל רק שע\"י הוא נפנה לקוראו בלבד כו', וגם בבחי' שם דמלוכה דאנא אמלוך ה\"ז רק כמו שם המלך שמתפשט על מדינתו שאין נוגע לעצמותו כו' וד\"ל.\n<b>אך</b> באמת גם בבחי' מלוכה לא יתכן לקרות להארה דמל' דא\"ס המתפשטת להיות בבחי' סובב כו' (וכמ\"ש בע\"ח דבחי' מל' דא\"ס אין אנו רשאים לדבר<sup data-n=\"430\">22</sup> כו') לפי שהכל עדיין בבחי' אח\"פ ששם לא יתכן לומר ענין מלוכה בבחי' התנשאות על דבר נפרד זולתו מאחר שאין עוד מלבדו כו', ומה שעלה בעצמות אנא אמלוך גם זה אינו תופס מקום כלל לגבי עצמותו ממש כמ\"ש לך הוי' הממלכה שהוא בחי' מל' דא\"ס ג\"כ כידוע שפי' מלוכה הוא מקור כל בחי' מל' הבא בגילוי בהשתל' דאבי\"ע כמ\"ש מלכותך מלכות כל עולמים<sup data-n=\"431\">23</sup> (ונק' מלך מלכי המלכי' כת\"ר<sup data-n=\"432\">24</sup> מל' וד\"ל), ואין לדמות ערך בחי' מח' זו דאנא אמלוך לגבי עצמותו כערך טפה בים שהרי אינו רק מח' א' פרטי' שאינה במנין לגבי כח עצם המח' שמשם נובעים כל המח' וטפה בים נחשבת במנין עכ\"פ, והרי אמרו דלית מחשבה תפיסא בי' שום מח' גם בחי' מח' זו דאנא אמלוך שבעצמותו וגם בחי' מח' אחרת שלמע' מזו אינה תופסת מקום אצלה ולית לה תפיסא במהותו העצמי כלל, והוא גם בחי' מחשבה א' שצופה ומביט בסקירה א' כל מה שהוא סובב וממלא מראש עד סוף הכל כידוע, הרי גם בחי' זו<sup data-n=\"433\">25</sup>* שלמע' ממח' הנ\"ל דאנא אמלוך שממנו נמשך בחי' סובב כו' ג\"כ לית לה",[["426","18","<b>נפלאותיך ומחשבותיך אלינו</b>: תהלים מ, ו."],["427","19","<b>לך ה' הגדולה</b>: דברי הימים א כט, יא."],["428","20","<b>סתימא דכל סתימין אפי' אור צח</b>: תקוני זהר בהקדמה ד\"ה פתח אליהו. תיקון ע' (קלה, ב). ובתיקון ס\"ט (קטו, רע\"ב): אור קדמון אע\"ג דאיהו סתים וגניז כו'."],["429","21","<b>דלית מחשבה תפיסא בי' אפי'. . דא\"ק</b>: ראה לעיל ד\"ה שמח תשמח הראשון אות ט', וש\"נ."],["430","22","<b>בע\"ח דבחי' מל' דא\"ס אין אנו רשאים לדבר</b>: ראה לעיל שם ס\"י, וש\"נ."],["431","23","<b>מלכותך מלכות כל עולמים</b>: תהלים קמה, יג."],["432","24","<b>כתר מל'</b>: בכת\"י ב ליתא תיבות אלו, כ\"א: כידוע וד\"ל."],["433","25","<b>זו</b>: בכת\"י ב: מח' זו."]]],[1900420114,"תפיסא כו', וגם כי מה מאד עמקו מחשבותיך זו למע' מזו וכולם כלא חשיבי לגבי עצמותו ממש, וכ\"ש מח' א' הזאת שפוקד כל יצורי קדם שמבחי' סובב כו' וד\"ל.\n<b>אך</b> בחי' ראשית הטיית מהו\"ע דאחדות פשוטה להיות לו מח' זו דאנא אמלוך כו' להיות בבחי' סובב כו' היינו משום דנמלך בנשמתן של צדיקים שהן ישראל שעלו במח'<sup data-n=\"434\">26</sup> דהיינו במחשבת עצמותו ממש מאחר שבהן נמלך אם להיות לו רצון ומח' זו דאנא אמלוך הנ\"ל, והוא מפני ששרש ישראל הוא בבחי' עצמות הרצון והמח' ממנו ולא בבחי' התפשטות המח' כמו מח' דאנא אמלוך וע\"כ נמלך בנשמתן של צדיקים דוקא וד\"ל. וזהו הטעם באמת לענין אתערותא דלתתא דישראל דוקא שמעוררים בחי' אתדל\"ע בעצמותו ממש לחדש להיות חפץ במח' זו דאנא אמלוך כי מאחר שלך ה' הממלכה כלא חשיבא כנ\"ל. והנה עיקר אתדל\"ת דישראל הוא דוקא מצד מעשיהם בגשמי' כשנשמותיהם מלובשים בגופים חומרי' והן מוסרי' נפשם באחד בק\"ש באה\"ר ואהבת בכל נפשך כו' וע\"י קיום תומ\"צ דוקא כידוע, וזהו דבר פלא לכאורה מאחר שעיקר הענין הוא מצד בחי' שרש נשמותיהם שעלה במח' העצמי' שבעצמות ממש א\"כ מה צריך למס\"נ שלהם בגופי' דוקא וע\"י תומ\"צ בפועל ממש דוקא. אך הענין הוא, דמשום דמה שנמלך בנש\"צ כנ\"ל היינו באותן נשמות שיהיו בגופי' דוקא ויקיימו תומ\"צ במס\"נ, לפי שנעוץ תחילתן בסופן דוקא כי סוף מעשה שעלה במח' העצמי' כנ\"ל מפני שנתאוה עצמות אא\"ס להיות לו דירה בתחתוני' ע\"י נשמות ישראל שהן כלולים בבחי' העצמי' כשיבואו ויתלבשו בעוה\"ז בגופי' לקיים תומ\"צ, וזהו בראשית בשביל ישראל שנק' ראשית<sup data-n=\"435\">27</sup> כו', וזהו ענין דירה בתחתונים שהי' אצלו במח' תחלה, אשר ע\"כ נמלך בנש\"צ שעלה במח' מה שיעבדו עבודה תמה בעוה\"ז בהן נמלך דוקא. וע\"כ אנו מוצאים בכ\"מ שבחי' המעשה דתומ\"צ בישראל דוקא גדולה ביותר לעורר לבחי' הטיית עצמותו ומהותו ממש להיות חפץ במח' דאנא אמלוך להיות בבחי' סובב כו' הרבה יותר מהתעוררות נשמתם באהוי\"ר במס\"נ כמשארז\"ל היום לעשותם<sup data-n=\"436\">28</sup> וכה\"ג וד\"ל.\n<b>והנה</b> כל בחי' הנ\"ל בבחי' סו\"מ שתלוי באתדל\"ת דישראל דוקא אבל בלא אתדל\"ת אין אתדל\"ע כלל, אך אעפ\"כ לפעמים יוכל להיות שיהי' אתדל\"ע מאליו ומעצמו בלי אתדל\"ת כלל ואתדל\"ע זאת יוכל להיות במעלה ומדריגה יותר מאתדל\"ע שע\"י אתדל\"ת. וזהו שמח תשמח ריעים האהובים ע\"י בחי' השמחה שתשמח ריעי' האהובים שהן בחי' סו\"מ שנק' חו\"כ כנ\"ל. הענין",[["434","26","<b>דנמלך בנשמתן של צדיקים. . ישראל שעלו במח'</b>: ב\"ר פ\"ח, ז [וראה לעיל ח\"א ע' לז]. שם פ\"א, ד."],["435","27","<b>שנתאוה. . דירה בתחתונים. . בשביל ישראל שנק' ראשית</b>: תנחומא נשא טז. רש\"י ר\"פ בראשית."],["436","28","<b>היום לעשותם</b>: עירובין כב, א: היום לעשותן ולמחר לקבל שכרם."]]],[1900420115,"הוא להיות ידוע בטבע השמחה שהוא פורץ גדר הטבעי שהנהיג מקדם, כמו עד\"מ מלך שגדרי הטבעי שהוסד לפי כבוד מלכותו הוא יושב בהיכלו כולו אומר כבוד שאין איש בא להיכלו בלתי קריאה שיקראוהו ולא יזכו לראות פניו רק השרים הגדולים לפרקי', וגם זה דברי המלך מועטים המה כי אין זה לפי רוממות גדולתו להרבות דברים עמהם מאחר שאי[נם] מערכו כלל, אך לפעמי' כמו בשעת שמחת לב המלך במשתה וכה\"ג יפרוץ גדרי הטבעי המוסד מכבר בתמידות ההנהגה לפי כבודו הרמה ויצא לחוץ מהיכלו ויתגלה לעין כל ברחוב העיר וידבר עם הכל גם עם פחותים שבעבדים וירבה דברי' כהדיוט כו', לפי שהשמחה בכחה לפרוץ גדר הנהוג בתמידות ולשנותו לגמרי עד שזהו כמו שינוי ממהות למהות אחר כמו מעוצם הרוממות לעוצם השפלות וכן משנאה לאהבה ומדין לחסד מן ההיפוך להיפוך ממש, כידוע שבשעת השמחה יצוה המלך להוציא מבית הכלא גם המורדים ופושעי' בו ולנשאם ולרוממם ולהטיב להם כל טוב, וכ\"ז מפני שטבע השמחה לשנות ולפרוץ גדר הטבע הראשון לגמרי. ושרש הענין הוא לפי שהשמחה מגלה מבחי' פנימי' ועצמו' הנפש לבחי' המשכה ואור חדש שלמע' בערך מבחי' האור והחיות הקדום שנמשך מן הנפש, וזהו הנק' בחי' ההמשכה מן ההעלם לגילוי שבחי' ההעלם הוא בחי' העצמי' והפנימי' שבא לידי גילוי בשמחה דוקא שהנפש תשמח ביותר כו', וראי' לזה הוא מה שאנו רואים שכל סוד הנעלם בנפש כמו רצון סתום ונעלם ביותר ושכל סתום ונעלם ביותר ע\"י השמחה יבוא לידי גילוי בדיבור אשר לא יגלוהו לשום אדם אפי' לאוהבו אשר כנפשו כו', א\"כ מזה הוראה גמורה יש ששרש השמחה מגיע בעצם פנימי' הנפש ביותר עד שגם בחי' הסתימו' וההעלם שבנפש יוצא ע\"י לגילוי לחוץ כו' וד\"ל.\n<b>והנמשל</b> מכ\"ז יובן למע' בבחי' מהות ועצמות דאחדות פשוטה ממש כמו שהוא, שאינו בא לידי גילוי רק ע\"י בחי' השמחה דוקא וכמ\"ש ויספו ענוים בהוי' שמחה<sup data-n=\"437\">29</sup>, שע\"י השמחה שבעצמותו אזי יצא מהיכלו לגילוי בעולמות שלא כפי גדר הגדור ע\"פ סדר ההשתל' התמידי ע\"פ מאמר קו המדה, שהרי ידוע שלפי הגדר התמידי הרי בחי' עצמות אא\"ס קדוש ומובדל הוא לבדו ממש כו' ונק' סתימא דכל סתימין כו' ולית מחשבה תפיסא בי' (אפי' מח' דאנא אמלוך כו' ומה שלמע' הימנו כנ\"ל) מפני שאין ערוך אליו כלל וכלל, אך ע\"י בחי' השמחה יוצא אור חדש מבחי' אור עצמותו ממש מלמע' גם למטה מטה דהיינו מעוצם הרוממות שבעצמותו למטה מטה כו', כמשל המלך שבשמחתו מתגלה בחוץ וידבר עם הכל כו', כי השמחה פורץ גדר הקדום כנ\"ל, והוא מפני שע\"י יתגלה מבחי' פנימי' ועצמי' אא\"ס שבהעלם להיות מאיר אור עצם דוקא בבחי' סו\"מ כו', ומה שנק' תחלה סתימא דכל סתימין דלית מחשבה תפיסא בי' הכל בא לידי גילוי לפי ששרש השמחה מגיע בבחי' פנימי'",[["437","29","<b>ויספו ענוים בהוי' שמחה</b>: ישעי' כט, יט."]]],[1900420116,"ועצמי' אא\"ס ביותר עד שע\"י יגלה כל בחי' העלם וסוד ה' כמו רצון ותענוג העליון הנעלם וכל בחי' חכ' נעלמה כו' וד\"ל.\n<b>וזהו</b> שמח תשמח ריעי' האהובי' שע\"י השמחה שבעצמיות אא\"ס נמשך ג\"כ בחי' שמחה לשמח גם לבחי' ריעים האהובים שיתחברו ויהי' יחוד חו\"כ בתוס' אור, והוא יחוד דסו\"מ שיתחברו יחד שנק' ריעים האהובים, וזהו כאשר אין אתדל\"ת כלל לעורר אתדל\"ע להיות בבחי' סו\"מ כו' אז בחי' אתדל\"ע מעצמו ומאליו ע\"י בחי' השמחה ביתר שאת ויתר עז להאיר אור עצמות ממש למטה בבחי' סובב וממלא ובגילוי הרבה יותר מכפי גדר הקדום ע\"פ מאמר קו המדה כו' מטעם הנ\"ל בענין השמחה שפורץ גדר ומביאה כל סתום לגילוי כו' וד\"ל.\n<b>וזהו</b> שאמר עוד כשמחך יצירך בג\"ע מקדם, פי' בזה בא לחזק דברי' הראשוני' באמרו שמח תשמח כו' גם שאין אתדל\"ת ואומר עוד ששמחה מעצמות שלא ע\"י אתדל\"ת כבר הי' לעולמים כן שהיא כשמחך יצירך בג\"ע כו' ואומר ששמח תשמח לריעי' האהובים כנ\"ל כמו אותה השמחה שכבר הי' כשמחך יצירך כו' שהוא יצירת אדה\"ר בג\"ע מקדם מבחי' קדמונו של עולם<sup data-n=\"438\">30</sup>. ויש להבין מה שתולה שמחה זו בשמחה כשמחך יצירך בג\"ע מקדם. אך הנה ידוע שעיקר תכלית בריאת העולמו' בבחי' סו\"מ הוא בשביל בריאת האדם דוקא כמ\"ש לכבודי בראתיו<sup data-n=\"439\">31</sup> יצרתיו כו' כנ\"ל בענין במי נמלך בנש\"צ כו'. וזהו ענין השמחה כשמחך יצירך כו', דהנה אדה\"ר הי' יציר כפיו של הקב\"ה בג\"ע שנא' וייצר ה' אלקי' את האדם כו' ויניחהו בג\"ע כו', ולקח אחת מצלעותיו כו' ויביאה<sup data-n=\"440\">32</sup> אל האדם כו' ונעשה שושבין לאדם ועשה להם חופה והוא בחי' המשכת אור המקיף על החתן וכלה שיוכל לבא לידי יחוד וזיווג כו' כמ\"ש במ\"א<sup data-n=\"441\">33</sup> והי' משמח לאדם בשמחת חופתו, והיינו משמח חו\"כ לאדם ואשתו בחופה שעשה להם.\n<b>וזהו</b> כשמחך יצירך בג\"ע מקדם, שבודאי שמחה זאת ששמח לאדה\"ר הי' בבחי' אתדל\"ע מצ\"ע כי עיקר המכוון בהשתל' העולמו' בבחי' סו\"מ הי' רק בשביל האדם ע\"כ שמח בו ביותר ומשמחתו שמח אותו כו'. וזהו מקדם מקדמונו ש\"ע, פי' בחי' קדמון לכל הקדומי' שלמע' מבחי' ההשפעה דמל'",[["438","30","<b>קדמונו של עולם</b>: ע\"פ ב\"ר פל\"ח, ז."],["439","31","<b>לכבודי בראתיו</b>: ישעי' מג, ז."],["440","32","<b>וייצר. . ויניחהו. . ולקח. . ויביאה</b>: בראשית ב, ז. טו. כא-כב."],["441","33","<b>חופה. . המשכת אור המקיף. . כמ\"ש במ\"א</b>: ראה לעיל ח\"א ע' כג. לעיל ד\"ה שמח תשמח הראשון (סוף אות ו' ואות כב). להלן ד\"ה קול מצהלות אות כט ואות מ. ס' מאמרי אדהאמ\"צ דברים ח\"ד ע' א'תקיד. ובכ\"מ."]]],[1900420117,"דאא\"ס להיות בבחי' סובב כו' כנ\"ל בפי' יחיד חי העולמים כו', ומה גם שלא הי' עדיין מי שיעורר שמחה מלמטה כמ\"ש ואדם אין<sup data-n=\"442\">34</sup> כו' שהרי אח\"כ נאמ' ויניחהו בג\"ע לעבדה זו רמ\"ח מ\"ע<sup data-n=\"443\">35</sup> כו' שזהו ענין אתדל\"ת שמעורר אתדל\"ע אבל קודם לכן לא הי' אתדל\"ת כלל, רק מה ששמח לאדה\"ר הי' מצד אתדל\"ע הוא בחי' השמחה שמצד עצמותו שהוא למע' הרבה משמחה שנעשה ע\"י אתדל\"ת כידוע, לפי שהשמחה שמעצמו ומאליו הרי הוא בבחי' עצמיות אא\"ס כמו שהוא ממש שאין לזה ערך כלל, שהרי מבחי' השמחה שישמח במעשיו מצד בחי' ההשתל' הרי שרשם רק בבחי' המחשבה דאנא אמלוך כו' וד\"ל.\n<b>וזהו</b> שאנו מבקשים שמח תשמח ריעי' האהובים כשמחך יצירך בג\"ע מקדם דוקא. דהנה בבחי' קדמונו ש\"ע שלמע' מבחי' ההשתל' דסו\"מ כו' אין אתדל\"ת מגיע לשם כלל ושם נא' אם צדקת<sup data-n=\"444\">36</sup> מה תתן לו כו', שאין המצות מעוררים אתדל\"ע רק במה שבא האור בבחי' סו\"מ שהרי המצות הם בחי' המשכת רצונו בבחי' גילוי אור א\"ס בעולמות כו' (רק בחי' שמחה ש\"מ מגיע בעצמו' כמשי\"ת), רק בחי' השמחה שבעצמו' דוקא הוא המתגלה מבחי' פנימי' ועצמיות בבחי' אתדל\"ע שמצ\"ע שאין אתדל\"ת מגיע לשם כלל לפי שהשמחה טבעה לפרוץ גדר הנהוג להמשיך בחי' הארה והמשכה חדשה ממש שלמע' מע' מכל ההשתל'. וזהו מקדם מקדם להשתל'. וזהו ענין הבקשה כשמחך יצירך בג\"ע מקדם שלא ע\"י אתדל\"ת כלל לפיכך תשמח גם לריעי' האהובים שהן עכשיו בבחי' ההשתל' שהוא בחי' סו\"מ שנק' חו\"כ שיהי' בחי' יחודם ג\"כ בחי' שמחה עליונה זו שמעצמו שלא ע\"י אתדל\"ת אלא שמח תשמח אתה בעצמך לריעי' האהובים כמו ששמחת לאדה\"ר בג\"ע מקדם כמו שהי' לפני כל ההשתל' כנ\"ל וד\"ל.\n<b>והנה</b> מבואר למע' שהשמחה פורץ גדר כו', ויובן זה למע' שבגילוי אור שמחה העליונה שבעצמו' אזי נמשך למטה ג\"כ בתוס' אור לפרוץ גדר הקבוע בכל עולם יותר מכפי המדה המצומצמת לו ע\"פ מאמר קו המדה כנ\"ל, להיות ידוע שענין ההשתל' הוא בחי' ירידת האור האלקי במיעוט אחר מיעוט בצמצום אחר צמצום מעולם לעולם ומעילה לעילה, והוא לפי שכאשר צריך להיות התהוות השפע בעולם שלמטה הוצרך להיות בחי' צמצום ומיעוט באור העליון, וכך הוא ענין הצמצום מעולם לעולם שהן ריבוי רבבות מדריגות המשתלשלים בריבוי צמצומים והעלמות העלם אחר העלם, עד שבבוא ההארה והשפע למטה מטה מאד כמו בזה העולם השפל החומרי כבר נתמעט האור",[["442","34","<b>ואדם אין</b>: בראשית ב, ה."],["443","35","<b>לעבדה זו רמ\"ח מ\"ע</b>: בראשית ב, טו. ראה זח\"א כז, א. זח\"ב קסה, ב. ולעיל ח\"א ע' כב [וש\"נ לכ\"מ בדא\"ח]."],["444","36","<b>אם צדקת</b>: איוב לה, ז."]]],[1900420118,"האלקי בתכלית המיעוט והצמצום היותר אחרון לפי שעוה\"ז השפל הוא היותר אחרון בהשתל' מכל העולמו', וא\"כ לא מגיע האור והשפע בעוה\"ז השפל רק מעט מזעיר בצמצום ומיעוט היותר אחרון כידוע, וגם מה שמגיע האור האלקי למטה בעוה\"ז ע\"י בחי' אתדל\"ת מהעלאת מ\"ן ג\"כ לא מגיע כאן רק בבחי' מיעוט וצמצום היותר אחרון שהרי לפי ערך ההעלאה כך ערך ההמשכה כידוע דרוח אייתי רוח<sup data-n=\"445\">37</sup> ואמשיך רוח כו', ואם בחי' ההעלאה מעולם השפל שלנו הוא בחי' קטנות הערך ביותר שהרי העלאה זאת העלאה בבחי' הגשמי' בלבד ואין זה ערך לגבי העלאת הרוחני' שמעולם לעולם בעולמו' העליוני' הרוחני' כידוע, וא\"כ גם מה שראוי להיות בחי' אתדל\"ע ע\"י העלאת אתדל\"ת דעוה\"ז השפל ג\"כ אינו בא ונמשך מלמע' למטה רק בבחי' צמצום ומיעוט האור בתכלי', ומפני ריחוק ערך עולם שלנו בסדר ההשתל' שהוא היותר רחוק ומצומצם מאור פני מלך חיים ע\"כ גם בחי' הארה הזאת דאתדל\"ע שנמשכת לו ע\"י אתדל\"ת כנ\"ל הרי גם היא נמשכת ע\"י ריבוי צמצומי' והעלמות ולבושי' ומסכים רבים מאד כראוי להיות ע\"פ סדר ההשתל' לפי ריחוק ערך שפלות העוה\"ז שנתרחק מאור פני מלך חיים בצמצום היותר אחרון, וע\"כ בהשפעת גילוי האור מעצמו' האא\"ס עד שיגיע האור לעוה\"ז הרי הוא בא בסדר השתל' מעולם לעולם בריבוי רבבות צמצומים כנ\"ל עד שלא יגיע ממנו בעוה\"ז רק הארה מצומצמת בתכלית הצמצום וההסתר כנודע וד\"ל.\n<b>אך</b> ע\"י בחי' השמחה העליונה שבעצמו' אא\"ס כנ\"ל הרי נפרץ גדר המצומצם ע\"פ קו המדה להיות נמשך האור שלא ע\"פ בחי' השתל' שהוא ענין צמצום אחר צמצום כנ\"ל, לפי שעל ידי השמחה מאחר שהיא בחי' גילוי אור העצמי' שאינו בא ונמשך בגדר שפע משפיע ומקבל הרי מאיר ובא בכל העולמו' בשוה למטה כמו למע' ממש בשוה בלי שום הפרש כלל. כי הנה דוקא האור הנמשך בבחי' שפע למקבל צ\"ל בבחי' צמצום כפי צמצום כלי המקבל בלבד וכן משתלשל השפע מעולם לעולם בכ\"א לפי צמצומי' כנ\"ל עד למטה בעוה\"ז שבא בצמצום יותר מכולם, אבל האור שבא מבחי' העצמו' ממש שאינו בגדר שפע למקבל מאחר שנק' סדכ\"ס גם בעולם העליון ביותר ע\"פ סדר ההשתל' רק שנגלה מצד השמחה בלבד שפורץ גדר מטעם הנ\"ל, א\"כ אין הפרש בו כלל בין כשהוא מאיר למע' מעלה או למטה מטה ממש בשניהם מאיר בשוה, כי גם העליון אין לו ערך אליו כמו התחתון כו', וא\"כ ממילא מובן שגם בענין אתדל\"ת אין הפרש לגבי בחי' גילוי אור זה שמצד השמחה בין אתדל\"ת דעולם העליון ביותר ובין אתדל\"ת דעוה\"ז השפל מאחר שנמשך זה האור מבחי' קדמונו ש\"ע שאין אתדל\"ת מגיע לשם כלל כנ\"ל להיותו בבחי' העצמו' שמעלה ומטה שוין שם ממש מצד שהוא למע' מבחי' השפעה והמשכה שאין אתדל\"ת מגיע רק במה שמגיע האור בבחי' שפע עכ\"פ גם שהוא בבחי'",[["445","37","<b>דרוח אייתי רוח</b>: ראה זח\"ב קסב, ב. אוה\"ת חנוכה רפו, א."]]],[1900420119,"סובב כו' כנ\"ל (ומ\"ש בע\"ח דבחי' סוכ\"ע הכללי מקיף ג\"כ לד' עולמות בשוה הרי שוים שם ג\"כ מעלה ומטה כו', מ\"מ ה\"ז מצד בחי' השפעה רק שהוא בחי' סובב ומקיף גם שסובב בשוה ממש, משא\"כ האור שמצד שמחה עליונה שבעצמו' ממש אינו בגדר עלי' כלל גם מהיות מבחי' סו\"מ<sup data-n=\"446\">38</sup> להם מאחר שהוא בא מצד בחי' העצמו' ממש, משא\"כ<sup data-n=\"447\">39</sup>* גם בחי' סו\"מ בשוה לא יתכן לומר בו כלל מאחר שמושלל לגמרי גם מבחי' מעלה ומטה להיות שהוא למעלה מבחי' השפעה והמשכה לגמרי כנ\"ל וד\"ל). וזהו כשמחך יצירך בג\"ע מקדם שבא האור למטה כמו למע' ממש בשוה כו' וד\"ל.\n<b>ואמנם</b> הנה יש דרך אחרת שיהי' בחי' אתדל\"ע בבחי' שמחה עליונה בעצמו' ממש מצד אתדל\"ת דוקא ותהי' באותה מדריג' השמחה עליונה שמצד עצמותו בלבד, אך לא ע\"י בחי' מעשה התחתוני' מצד עצם המעשה שהרי בבחי' עצמותו נא' אם צדקת מה תתן לו כנ\"ל, אלא מצד בחי' שמחה של מעשה המצוה דוקא שמגיע למע' לעורר בחי' שמחה עליונה שמצד עצמותו כו' להיות יאר ה' פניו בשמחה רבה הנ\"ל ממש. אך הנה תחלה יש להקדים בשרש ענין שמחה של מצוה מה היא, בהיות ידוע במ\"ש עבדו את ה' בשמחה<sup data-n=\"448\">40</sup> כו' שהעיקר הוא השמחה בעבודה, אך אעפ\"כ יש להבין במה שמצינו כמה עונשין וקללות חמורות כ\"כ על העדר השמחה בעבודה, גם שהעבודה היא בשלימות ככל אשר צוה ה' בתכלית הכשרו' וגם עובד מאהוי\"ר וקבלת עול מלכות שמים בשלימות ובתכלית הכוונות הרצויות שבמצות ה' אך שלא עובד בשמחה וטוב לבב דוקא אזי היפך מברכה לקללה בקללות חמורות כ\"כ, כמו שמפורש בסיום כל הקללות שבמ\"ת שכ\"ז הוא תחת אשר לא עבדת<sup data-n=\"449\">41</sup> את ה' אלקיך בשמחה ובטוב לבב דוקא, וזה הדבר באמת פלא גדול מאד אשר תשיר שערות ראש כל איש עובד ה' בתומו בכל לבו שבאם לא יעבוד בשמחה יחולו כל הקללות העצומות והנוראות על ראשו תחת אשר הוא ראוי לכל הברכות על אודות שלימות עבודתו התמה כמ\"ש והברכה אשר תשמעון<sup data-n=\"450\">42</sup> כו' ולא כתיב אשר תשמחון במצותיו כו'.\n<b>אך</b> הנה הענין הוא משום שהשמחה עיקר גדול בעבודת ה' כ\"כ עד שהעבודה שבלא שמחה אין לה ערך כלל וכלל לגבי העבודה שבשמחה מלבד העדר הטוב שבלא שמחה אלא שנהפוך מברכה לקללה וכמ\"ש תחת אשר לא עבדת כו'. ויובן זה ע\"פ הנ\"ל בענין שמח תשמח כו', שיש אתדל\"ע שאינו רק",[["446","38","<b>סו\"מ</b>: סובב ומקיף. [ובמקומות אחרים במאמר זה פיענוח הר\"ת הוא: סובב וממלא]."],["447","39","<b>משא\"כ</b>: בכת\"י ב: וא\"כ."],["448","40","<b>עבדו את ה' בשמחה</b>: תהלים ק, ב."],["449","41","<b>שבמ\"ת </b>[שבמשנה תורה]<b>. . תחת אשר לא עבדת</b>: תבוא כח, מז."],["450","42","<b>והברכה אשר תשמעון</b>: ע\"פ דברים יא, כז."]]],[1900420120,"ע\"פ אתדל\"ת והוא ע\"י כשרון המעשה בתומ\"צ למטה דוקא כי רוח אייתי רוח כו', אך אין אתדל\"ת זאת מעוררת רק להיות אתדל\"ע כפי צמצום העלאה מלמטה באתדל\"ת, והוא אשר נמשך בצמצום מאוא\"ס בעולמו' להיות סו\"מ<sup data-n=\"451\">43</sup>* כו' ע\"פ מאמר קו המדה כנ\"ל שההארה מועטת היא מאד מב' טעמים, הא' מצד שאינה נמשכת רק כפי הצמצום דהעלאות המקבלי' שאין להם ערך כלל וכלל לגבי עצמות כנ\"ל (וע\"פ מח' הקדומה דאנא אמלוך<sup data-n=\"452\">44</sup> שרש כל העולמו' כלא חשיבי כו'), והב' מצד בחי' המשכת הארה הזאת שנמשכת ע\"פ סדר ההשתל' מעל\"ע ע\"פ מא' קו המדה שנמשך והולך במיעוט אחר מיעוט לפי\"ע ומדריגות כל עולם ועולם לפי מה שהוא בלבד, ולפי מספר רוב העולמות בצמצומי' רבים כן יתצמצם ויתמעט האור הזה בכל מיני צמצומי' הללו שבין כאו\"א, עד שבבוא האור למטה מטה ביותר שהוא עוה\"ז השפל שלנו היותר אחרון מכולם הרי אינו מגיע אלינו אור זה רק בתכלית הצמצום וההסתר במיעוט היותר אחרון כנ\"ל, וע\"כ ודאי שיכולים גם החיצוני' לקבל יניקה ותוס' אור וחיות מאור זה להיותו בתכלית ההעלם וההסתר כו'. וזהו ענין יניקת דיני' וגבורות קשות שמתאחזים באור האלקי הזה וממילא מסתעף מזה בחי' דינים וקטרוגים רבים וקשים למעלה על כנ\"י מאחר שנתוסף להם כח ועוז מלמע' עי\"ז כו'. והיינו סיבת ענין הנ\"ל שע\"י העבודה דמצות בלא שמחה מלבד העדר גילוי האור הנה מסתעף מזה קללות רבות וכמ\"ש תחת אשר לא עבדת בשמחה כו' וד\"ל. משא\"כ ע\"י העבודה בשמחה ובטוב לבב שהוא היפוך זה דכל הברכות נמשכות ממקור כל הברכות למעלה מכפי המדה הקצובה ע\"פ מאמר קו המדה כו'. והענין הוא להיות שע\"י השמחה ש\"מ מעוררי' למע' ג\"כ בחי' שמחה עליונה כי באתדל\"ת אתדל\"ע, אמנם גם שאתדל\"ת היא עולה בבחי' שמחה מצומצמת כפי ערך צמצום כלי המקבלי', מ\"מ מעוררי' למע' בחי' שמחה שמצד עצמו' שהוא בבחי' א\"ס ממש למע' ממקור כל ההשתל' דבחי' סובב וממלא כו', ע\"כ בחי' הארה זו שנמשך למע' היא באה בבחי' תוס' אור כ\"כ עד שמאיר למטה כמו למע' ממש בשוה מטעם שהארה זו באה מבחי' העצמו' שלמע' מבחי' מעלה ומטה לגמרי כנ\"ל וד\"ל.\n<b>ועדיין</b> אין זה מובן לכאו', דאם בגופה של מצוה נא' בה אם צדקת מה תתן כו' משום דאין אתדל\"ת מגיע לשם כלל האיך שמחה של מצוה מגיע שם לעורר שמחה שמצד עצמותו מאחר שהשמחה באה למע' מצד שמחה של מטה כו'. אך שרש הדברים הוא כמבואר למע' במי נמלך בנשמתן של צדיקים כו' שמח' ורצון זה דאנא אמלוך כדי להיות לו דירה בתחתונים ע\"י תומ\"צ בפו\"מ דוקא נמלך תחלה אם יהי' לו תענוג במח' ורצון זה כו', וכאשר נמשך תענוג במח' ורצון זה ה\"ז נמשך מבחי' עצמות התענוג ורצון הפשוט הכללי",[["451","43","<b>סו\"מ</b>: ראה ע\"ד פיענוח ר\"ת זו לעיל פיסקא: ?והנה כל הנ\"ל\"."],["452","44","<b>מח' הקדומה דאנא אמלוך</b>: נסמן לעיל פיסקא: וזהו יחיד."]]],[1900420121,"שנק' שעשועי המלך בעצמותו<sup data-n=\"453\">45</sup> כו' והיינו בחי' השמחה שבעצמותו כמ\"ש עו\"ז וחדו\"ה במקומ\"ו העצמי' דוקא כו', וזהו המלובש בבחי' שמחה ש\"מ דוקא. כי הנה הגם שאין ערוך כלל להעולמות לגבי עצמו' ובודאי א\"א לומר שבחי' השמחה באתדל\"ת מעורר שמחה שבעצמותו שבבחי' אא\"ס ממש, היינו דוקא סתם שמחה שהיא באה בערך השגת העולמו' באא\"ס בלבד, אבל שמחה ש\"מ שרשה למע' בבחי' שמחה ותענוג שבעצמותו דוקא, וע\"כ דקדק לומר בשמחה של מצוה דוקא כמ\"ש תחת אשר לא עבדת בשמחה כו' ולא סתם שמחה שמהתבוננו' והשגה באא\"ס כו'. והענין הוא כי המצוה עצמה שרשה בבחי' רצון העליון שנמשך ממקור כל הרצונות שנק' רצון העליון הפשוט כו', ושרש רצון הפשוט הזה הוא בחי' התענוג הפשוט הפרטי שנמשך מעצמות התענוג הפשוט הכללי שנק' שעשועי המלך בעצמותו, אבל בחי' שמחה של מצוה זאת עצמה מגיע דוקא בעצמות התענוג הפשוט הכללי, וכידוע בענין שמחה ש\"מ שאינה רק מפני שעשה את רצונו ולא מצד בחי' ההשגה והטעם בסוד וטעם אותו רצה\"ע הפרטי שבמצוה זו, וא\"כ ה\"ז מגיע בבחי' בעל הרצון ששם השמחה והתענוג שמצד עצמותו הפשוט שמשם נמשך מקור כל רצון שבמצוה. וזהו שגם שבמצוה עצמה נאמ' אם צדקת כו' מפני שאינה מגעת רק עד בחי' המשכת רצה\"ע שבמצוה זו, אבל שמחה של מצוה זאת מגעת בבחי' עצם התענוג הפשוט שבעצמותו ממש. וזהו שרש ענין הנ\"ל בשמחה של מצוה למטה מעוררי' למע' שמחה שמצד עצמותו ולא מצד המקבלים אלא מפני שמעוררי' שרש שמחה של מצוה כמו שהיא למע' שהיא בבחי' שמחה שבעצמותו כנ\"ל וד\"ל).\n<b>וזהו</b> תחת אשר לא עבדת את ה' בשמחה כו', שעי\"ז האור נמשך למטה בצמצומי' רבים כנ\"ל (והוא ע\"י בחי' צמצום ומסך שבין כל עולם ועולם הנק' פרסא, כמו בין המאציל לנאצי' שיש בחי' פרסא ובין האצי' לבריאה פרסא מפסקת וכן מבריאה ליצי' ומיצי' לעשי' כו' עד שבעוה\"ז האור בתכלית הצמצום כו'), שאע\"פ שע\"י המצות נמשך תוס' אור בכל העולמו' כידוע, אבל ע\"י המסכים שבין כל עולם ועולם מתמעט האור עד שבעוה\"ז הוא בא בתכלית ההסתר, ודוגמא לדבר כמו מצות שבת שלמע' היא בחי' גילוי אור אבא שהוא בי' אור החכ' דאצי' שנק' קדש העליון כמ\"ש כי קד\"ש הוא לכם<sup data-n=\"454\">46</sup>, ובירידת אור זה בהשתלשלות עולמו' בי\"ע הרי בעוה\"ז הוא בבחי' הסתר (מלבד ענין הנז' בע\"ח שהמצות הן רק עכשיו להוסיף אור באצי'<sup data-n=\"455\">47</sup> בלבד כו' מ\"מ בבחי'",[["453","45","<b>שעשועי המלך בעצמותו</b>: עמק המלך ש\"א. וראה ס' מאמרי אדה\"ז ענינים ע' תיא, ד\"ה בספר עמק המלך כו' שהשעשוע הי' בעצמותו [ובהנסמן בהמ\"מ לשם ע' תקלח סוף טור א]."],["454","46","<b>כי קדש היא לכם</b>: תשא לא, יד. וראה לעיל ד\"ה שמח תשמח הא', אות ט\"ל. וש\"נ."],["455","47","<b>בע\"ח שהמצות. . להוסיף אור באצי'</b>: ע\"ח שער מ\"ן ומ\"ד (של\"ט) דרוש י\"א כלל טז. וראה לעיל ח\"א ע' קנו. וש\"נ."]]],[1900420122,"התלבשות בהעלם מאיר מעולם ועד עולם רק שמתמעט האור מפני ריבוי המסכי' כנ\"ל וד\"ל). אבל ע\"י בחי' השמחה שמצד עצמותו ע\"י שמחה ש\"מ למטה הרי אור עצמותו בא בבחי' דילוג המדריגות שלא ע\"פ סדר ההשתל' כלל אז אור זה מאיר למטה כמו למע' ממש (כי אין מסך מבדיל שבין כל עולם ועולם מסתיר לגבי אור זה כלל מאחר שהוא בא מלמע' מן ההשתל' ע\"כ אין בו שינוי המהות כלל גם בעברו דרך המסכי' והעלמו' כו' (וגם בחי' מק\"פ שנק' צמצום הראשון שנא' ישת חשך סתרו<sup data-n=\"456\">48</sup> אינו מסתיר ומעלים אור זה כלל משום דקמי עצמותו ממש כחשיכה כאורה כו' מטעם הנ\"ל שאינו בגדר השפעה כו'), ומטעם זה כל הדיני' והגבורות קשות מתכללי'<sup data-n=\"457\">49</sup>* ונמתקים ע\"י שמחה של מצוה ונמשך ממקור הברכות ממקורא דכולא למע' מכפי המדה הקצובה ע\"פ אתדל\"ת במעשה המצות כו' וד\"ל.\n<b>וזהו</b> שמח תשמח ריעים האהובים שזהו בחי' שמחת חתן וכלה שלמע' מכל השמחות, שכל שמחה היא פרטית כמו מאור והשגה פרטי' או מרצון פרטי ותענוג פרטי המעורר לשמחה זו כו', אבל שמחת חתן וכלה שהוא העושה בחי' היחוד דמשפיע ומקבל שבהן יהי' שורה מבחי' שלימותא דכולא שיוכל להתייחד ולהוליד אור חדש כו', ה\"ז בחי' הארת אותו השמחה שמצד עצמותו ממש שמאיר בבחי' מקיף דחופה שעל החו\"כ כו', והוא מ\"ש שמ\"ח תשמ\"ח ריעי' האהובי' סובב וממלא משמחה שבעצמותך דוקא שאין אתדל\"ת מגיע לשם כלל (רק בחי' שמחה של מצוה בלבד כנ\"ל) שמח לדכורא ותשמח לנוק' שעי\"ז יהיו יכולי' להתייחד. רק שבהכרח שיבא כח זה מבחי' העצמות שלמע' מבחי' משפיע ומקבל כנ\"ל, וזהו כשמחך יצירך בג\"ע מקדם מקדמונו של עולם שהי' ג\"כ בחי' שמחה שבעצמו' דוקא והוא ששמח לאדה\"ר בג\"ע (עד\"מ מי שאינו שמח בעצמו אינו יכול לשמח לזולתו), ולהיות כי אדם דכר ונוק' ביחוד בהן שורה אחדות פשוטה ע\"כ משמחתו העצמי' דוקא שמח אדה\"ר כו'. ומ\"ש כשמח\"ך ל' יחיד כי שמחת הכלה נכללת בשמחת החתן מתחלה כמ\"ש ויקח א' מצלעותיו כו' וע\"כ אמרו אשה בעלה משמחה<sup data-n=\"458\">50</sup> כו'. וזהו חתימת הברכה בא\"י משמח חתן וכלה מבחי' שמחה עליונה שבעצמו' דוקא כנ\"ל (ובברכה האחרונה א' משמח חתן עם הכלה שזהו לעתיד שהכלה עיקר משום דנעוץ תחלתן בסופן דוקא כנ\"ל בענין ב' הברכות הללו באריכות<sup data-n=\"459\">51</sup>).",[["456","48","<b>ישת חושך סתרו</b>: תהלים יח, יב."],["457","49","<b>מתכללי'</b>: בכת\"י ב: מתבטלים."],["458","50","<b>ויקח א' מצלעותיו. . אשה בעלה משמחה</b>: בראשית ב, כא. ר\"ה ו, ב."],["459","51","<b>כנ\"ל בענין ב' הברכות הללו באריכות</b>: ראה בהמובא בהמ\"מ לעיל ח\"א ע' כד, ולעיל סוד\"ה שמח תשמח הראשון [ותיבת ?כנ\"ל\" אינו ברור לע\"ע אאיזה מאמר קאי]. ולהלן ד\"ה משמח חו\"כ."]]],[1900420123,"<h3>משמח חו\"כ</h3>\n<b>משמח</b> חתן וכלה<sup data-n=\"460\">1</sup>, ובברכה אחרונה אומר משמח חתן עם הכלה. ולהבין זה הנה ארז\"ל ביום חתונתו זה מ\"ת<sup data-n=\"461\">2</sup>, ויש להבין הלא בלאו הכי הקב\"ה נק' חתן מלשון נחות דרגא<sup data-n=\"462\">4</sup> ע\"ש בחי' השפעת והמשכת אורו בעולמות וכמ\"ש ואתה מחי' את כולם וכנ\"י נק' כלה<sup data-n=\"463\">3</sup> להיותה בחי' מקבל כידוע. ועוד י\"ל דכאן א' דכנ\"י נק' כלה ובמ\"א נא' להיפך שישראל נק' חתן והתורה נק' כלה כמארז\"ל אל תקרי מורשה<sup data-n=\"464\">5</sup> אלא מאורסה כו', אך הנה התו' נק' ברית כמ\"ש אלה דברי הברית אשר כרת משה<sup data-n=\"465\">6</sup> כו'.\n<b>והענין</b> הוא כי הנה כתי' עין לא ראתה זה עדן<sup data-n=\"466\">7</sup>, כי הנה ידוע שיש כמה מיני ג\"ע זה למע' מזה עד אין קץ ותכלית, כי יש בעילוי התענוג מדריגות רבות בעילוי אחר עילוי עד שהתחתון לגבי עליון הימנו אין לו ערך אליו כלל וצ\"ל בחי' הפסק דבר מה ביניהם שע\"י ישכח ויבוטל התענוג שבעדן התחתון, כידוע שיש בין געה\"ת לגעה\"ע נהר דינור מפסיק שבו טובלין הנשמות בעלייתן מגעה\"ת לגעה\"ע מדי שבת וחדש כו', דהיינו שע\"י בחי' טבילה זאת ישכח ויבוטל לגמרי התענוג האלקי שבגן עדן התחתון כדי שלא יבלבל לתענוג העליון הימנו הרבה אשר בגעה\"ע, כי זהו הכלל בכל עליות ממהות למהות בעילוי שאין בערך צ\"ל תחלה בחי' ביטול מהות הראשון לגמרי מכל וכל אז יוכל להתעלות בעליון (וכמשל רקבון הגרעין בארץ להבטל ממהות הראשון כדי שיתלבש בו כח הצומח כו', וכמ\"ש במ\"א בענין והאיש משתאה<sup data-n=\"467\">8</sup> לה מחריש כו'), וכמו מבחי' תענוג שבמדות לגבי תענוג שבחו\"ב שאין ערוך ביניהם וצ\"ל בחי' ביטול ושכחה על בחי' התענוג שבמדות כדי שלא יבלבל לבחי' התענוג שבשכל, כך אין ערוך תענוג האלקי שבנשמו' בגעה\"ת בבחי' יצי' ועשי' ששם הוא רק בבחי' המדות כמו אהבה בתענוגי' וכה\"ג לגבי בחי' העונג העליון האלקי שבחו\"ב בהשגת אלקו' בגעה\"ע, כידוע דגעה\"ע בעולם הבריאה דאימא מקננא בכורסיי'<sup data-n=\"468\">9</sup> כו' להיות נהנה מזיו כו' בבחי' השגה דחו\"ב",[["460","1","<b>משמח חתן וכלה</b>: מיוסד על ד\"ה זה, בס' מאמרי אדה\"ז על מארז\"ל ע' תצד [שם בכותרת ?על חתונה תקע\"ב\"]. ולהלן ד\"ה ?להבין מה שבברכה ראשונה\" הוא מאמר זה בהרחב הביאור.\nוראה עוד להלן בהוספות ברשימת הכתבי-יד."],["461","2","<b>ביום חתונתו זה מ\"ת</b>: שה\"ש ג, יא. תענית כו, ב."],["462","4","<b>חתן מלשון נחות דרגא. . ואתה מחי'</b>: יבמות סג, א. נחמי' ט, ו."],["463","3","<b>הקב\"ה נק' חתן. . וכנ\"י נק' כלה</b>: ראה להלן בתחילת המאמר שלאח\"ז, וש\"נ."],["464","5","<b>ובמ\"א נא' להיפך שישראל נק' חתן והתורה נק' כלה כמארז\"ל אל תקרי מורשה</b>: ראה להלן בתחילת המאמר שלאח\"ז וש\"נ."],["465","6","<b>אלה דברי הברית אשר כרת משה</b>: ע\"פ תבוא כח, סט: אלה דברי הברית אשר צוה ה' את משה לכרות את בנ\"י גו' אשר כרת אתם בחורב. וראה גם לעיל ח\"א ע' נ."],["466","7","<b>עין לא ראתה זה עדן</b>: ישעי' סד, ג. ברכות לד, ב."],["467","8","<b>וכמ\"ש במ\"א בענין והאיש משתאה</b>: חיי\"ש כד, כא. סידור צא, ג ואילך."],["468","9","<b>דאימא מקננא בכורסיי'</b>: תקוני זהר ת\"ו (כג, א). ע\"ח שער סדר אבי\"ע פ\"ג. שער דרושי אבי\"ע פי\"ג. תניא פל\"ט. ועוד."]]],[1900420124,"כו', וכמו למטה שהתפעלות התענוג באהוי\"ר אין לה ערך להתפעלות התענוג בחו\"ב עד שיבלבל כו', וע\"כ צריך לבטל התפעלות שבלב כדי שיבא לתענוג האלקי שבחו\"ב כו'. וזהו\"ע נהר דנור המבדיל ומפסיק בין געה\"ת לגעה\"ע (וגם בעמוד שבו עולי' ומתבטלי' ממהות התענוג שבגעה\"ת כמ\"ש בס' הבהיר<sup data-n=\"469\">10</sup>, וע\"כ כל העליות מעולם לעולם הוא ע\"י שיר דוקא שהוא ביטול מהות הראשון כמ\"ש במ\"א<sup data-n=\"470\">11</sup>). והנה עד\"ז מגעה\"ת לגעה\"ע יש עליות המדריגות בעילוי אחר עילוי בתענוג האלקי עד אין קץ ושיעור כלל. והטעם הוא לפי שבחי' התענוג האלקי הוא בבחי' א\"ס ממש דהיינו בחי' א\"ס בעא\"ע עד בחי' שעשועי המלך בעצמותו<sup data-n=\"471\">12</sup> ממש וכו' וכמ\"ש כי עמך מקור חיים<sup data-n=\"472\">13</sup> כו' מקור כל התענוגים העליונים, וכמו שאוא\"ס בתענוג האלקי הוא למע' מעלה עד אין קץ כך נמשך למטה מטה עד אין תכלית, והוא בחי' ירידת הארת התענוג למטה מטה ביותר כמו עד בחי' צמצום התענוג האלקי שבסוף מדריגות געה\"ת דעשי' שמתהווה מבחי' פסולת שלו שרש ומקור למציאות תענוג עוה\"ז שנפלו בשבירה כו' כידוע (ולזה שחק ר\"ע כשראה כרך גדול<sup data-n=\"473\">14</sup> דרומי מלא תענוגי עוה\"ז א' אם לעוברי רצונו כך כו', וזהו ג\"כ כמ\"ש מוטב דלידייני' כו' כמ\"ש במ\"א<sup data-n=\"474\">15</sup>). ובין כל מדריגה תחתונה לגבי העליונה יש בחי' מפסיק לבטל ולשכוח על הראשונה וכמ\"ש ילכו מחיל אל חיל<sup data-n=\"475\">16</sup> כו', שזהו כל עסק הנשמות אחר התפשטותן מחומר גופם בעוה\"ז שהן הולכי' מחיל אל חיל בעילוי אחר עילוי כנ\"ל, ולא שהן עסוקין בעילוי המדריגות בענין השגת אלקות מענין לענין שלמעלה הימנו בלבד, אלא הולכים מחיל אל חיל בעילוי תענוג נבדל בערך לגמרי מתענוג הראשון כנ\"ל וד\"ל.\n<b>וראי'</b> לזה הנה יש להוכיח כן גם מנשמות הצדיקי' הגבוהים יותר מכולם כמו נשמת משה רבן של כל הנביאים, שהרי ידוע שכל ימיו בחיים חיותו שהי' נשמתו בגופו בעוה\"ז ודאי ידע להשיג כל התו' כולה בפנימי' ח\"ע שבא במעלה ומדריגה עליונה שאין עוד למע' מזה וכמ\"ש ולא קם עוד נביא כמשה<sup data-n=\"476\">17</sup> אשר ידעו ה' פנים אל פנים, וא\"כ אחר התפשטות נשמתו מגופו שעלתה במקור חוצבה (באצי' שבבריאה או באצי' עצמה כו') א\"א לומר שלא ידע והשיג יותר מהשגתו הראשונה בעודנו בחיים חיותו שא\"כ מה הוא עושה ועוסק זה",[["469","10","<b>בעמוד. . שבגעה\"ת כמ\"ש בס' הבהיר</b>: ראה להלן ד\"ה להבין שבברכה ראשונה, ס\"ג. וש\"נ."],["470","11","<b>כל העליות. . ע\"י שיר. . כמ\"ש במ\"א</b>: נסמן להלן שם."],["471","12","<b>שעשועי המלך בעצמותו</b>: עמק המלך ש\"א. וראה לעיל במאמר הקודם (קרוב לסופו). וש\"נ."],["472","13","<b>כי עמך מקור חיים</b>: תהלים לו, יו\"ד."],["473","14","<b>שחק ר\"ע כשראה כרך גדול</b>: סוף מכות."],["474","15","<b>מוטב דלידייני' כו' כמ\"ש במ\"א</b>: חגיגה טו, ב. וראה לקו\"ת בשלח א, ד. ויקרא נב, ב. סה\"מ תקס\"ה ח\"ב ע' תערב [ובהמ\"מ שם]. ס' מאמרי אדהאמ\"צ דברים ח\"א ע' נט. ועוד."],["475","16","<b>ילכו מחיל אל חיל</b>: תהלים פד, ח. וראה בהמ\"מ בס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' מו."],["476","17","<b>ולא קם עוד נביא כמשה</b>: ע\"פ ברכה לד, יו\"ד."]]],[1900420125,"שנים רבות כו', אלא בהכרח לומר שמיד אחר עליות נשמתו למע' עסק בפנימיו' התו' במעלה ומדריגה יותר עליונה מהשגתו וידיעתו שבגופו בעוה\"ז והולך ועולה בכל יום ויום ממדרי' למדרי' יותר עליונה נבדל בערך ע\"ד הנ\"ל בגעה\"ת והעליון, וזהו עסקו בעליות רבות זה ימים ושנים רבות כי אין קץ ושיעור לעליות הללו בבחי' עומק רום להיותו בבחי' א\"ס ואין קץ למע' מעלה כנ\"ל. וכך כל הנשמות הצדיקי' כמו האבות אברהם יצחק ויעקב הולכי' מחיל אל חיל ממדרי' למדרי' מדי יום ויום עד רום המעלות. וזהו וקדושים בכל יום יהללוך סלה, פי' קדושי' הן נשמות הצדיקי' אחר פטירתן מגופם בעוה\"ז שנק' קדושי' הן אשר יהללוך סלה בלי הפסק שכל מקום שנאמר סלה אין לה הפסק<sup data-n=\"477\">18</sup>, דהיינו מפני שהולכי' ועולי' בכ\"י מחיל אל חיל בהלל ושבח נעלה בערך מן הראשון כנ\"ל, והיינו בכל יום יהללוך סלה כו' וד\"ל.\n<b>והנה</b> בחי' תענוג דא\"ס הנ\"ל הוא אשר בא ונמשך מלמע' מע' מבחי' שעשועי המלך בעצמותו למטה מטה בעוה\"ז הגשמי על ידי מעשה המצוות בעוה\"ז דוקא, כמ\"ש אשר קדשנו במצותיו פי' אשר הוא בחי' תענוג כמו באשרי<sup data-n=\"478\">19</sup> כידוע. דהנה כל מצוה ומצוה הרי הוא בחי' רצון העליון הפשוט שבאחדות פשוטה, וידוע שבכל רצון מלובש תענוג, וא\"כ בחי' תענוג המלובש ברצה\"ע שרש המצוה ה\"ז בחי' תענוג הפשוט שבעצמותו ממש שאין לו סוף למע' מעלה כנ\"ל באריכות. וזהו עין לא ראתה<sup data-n=\"479\">20</sup> אלקי' זולתך וזה עדן דוקא דהיינו בחי' תענוג העליון הפשוט שמלובש במצות שהוא בחי' עדן עילאה שבעצמו' דוקא ע\"כ נאמר בו עין לא ראתה אלקי' זולתך בעצמך דוקא, כי בחי' שעשועי המלך מצד עצמותו לא ידע והשיג עין כל, דאפי' אור צח<sup data-n=\"480\">21</sup> כו' אוכם הוא לגבי עילת העילות משום דלית מחשבה תפיסא בי' אפי' מח' דא\"ק כו', רק זולת\"ך מפני שהוא מצד עצמותו ממש שהוא בבחי' א\"ס ממש וד\"ל. אבל מ\"מ גם שעין לא ראתה בו עדיין יעשה למחכה לו, שלמחכה לו דוקא יעשה לו בחי' גילוי אור התענוג הפשוט הזה. והענין הוא דפי' מחכה כמו איוב חכה לו בדברי'<sup data-n=\"481\">22</sup> כו' לשון המתנה, ובזוהר א' פי' למחכה לו למאן דדייק במילין דחכמתא<sup data-n=\"482\">23</sup> כו'. וביאור הדבר הנה ענין דייק מילין דאוריי' דייק ממש כמו הלומד תו' בעיון גדול שמעמיק דעתו בכל כח שכלו לעמוד על איכות הרצון שבמצוה אם כך או כך, כמו שהוא לומד הלכות תפילין בעיון גדול שמעיין",[["477","18","<b>שכל מקום שנאמר סלה אין לה הפסק</b>: עירובין נה, א."],["478","19","<b>באשרי</b>: ויצא ל, יג."],["479","20","<b>עין לא ראתה</b>: ישעי' סד, ג."],["480","21","<b>דאפי' אור צח</b>: ראה תקוני זהר ת\"ע (קלה, ב)."],["481","22","<b>כמו איוב חכה לו בדברים</b>: איוב לב, ד: ואליהו חכה את איוב בדברים, וברש\"י ומצודות שם שהוא לשון המתנה. וראה גם המשך תרס\"ו ע' עח. ובכ\"מ."],["482","23","<b>ובזוהר. . למאן דדייק במילין דחכמתא</b>: זח\"א קל, ב."]]],[1900420126,"ומייגע א\"ע ביותר לידע ולהשיג איכות הרצון שבמצות תפילין באופן הכשר אם כך או כך, ויגיעה זו שהוא בעיון גדול ה\"ז היגיע' בכח החכ' דוקא שהרי בלא יגיע' בכח חכמתו לא יוכל לעמוד על אמיתי' טעם הרצון באיכות הרצון כלל, ונמצא שדייק במילין דחוכמתא דהיינו בטעם ושכל שברצון זה אם הוא כך או כך. והנה ידוע שבחי' החכ' והטעם לרצון הוא למטה מן הרצון עצמו (ונק' בחי' ח\"ס טעם כמוס למה יהי' הרצון כך כו'). ואמנם ענין היגיע' בטעם ושכל לרצון מאחר שלא נודע לו רק ע\"י יגיע' ודיוק בעיון היטיב מגיע הוא עי\"ז במקור החכ' והטעם שנא' בו והחכ' מאין תמצא<sup data-n=\"483\">24</sup> כו' שהוא בחי' רצון הפשוט שאינו מורכב בחכ' וטעם כלל ובו מלובש התענוג הפשוט שבלתי מורכב בחכ' כלל כו'. ונמצא שהמדייק ומייגע א\"ע במילי דחכ' שהוא בטעם הרצון אם כך או כך כו' כמו בחי' העלאת מ\"ן הוא שיומשך לו בחי' התענוג הפשוט שברצה\"פ שלמע' מן הטעם לגמרי (הנק' כתר שבכתר בכלל כו'). וזהו יעשה למחכה לו שמחכה לידע איכות הרצון ולא שכבר יודע, שידיעה שיודע בהשקפה ראשונה הרי הוא למטה מן עצם הרצון והתענוג שבו, אלא דוקא למחכה בהתחכמות בעיון ויגיעה רבה עד שיודע שבזה החיכוי דוקא מגיע למדריגת גילוי התעה\"פ שברצה\"פ, ע\"כ פי' בזוהר למחכה לו למאן דדייק דוקא במילין דאוריי' מילין דחוכמתא שהוא דוקא הגורם להיות לו גילוי התעה\"פ הנק' עדן אשר עין לא ראתה רק אלקי' זולתך כנ\"ל (וכידוע בפי' המחכה לו לשון המתנה שמצפה וממתין כמו חיכה לו בדברי' כו', וכך הוא הענין שאינו בא הדבר שחפץ להשיגו במעט זמן רק ע\"י עיכוב והעמדה עליו זמן רב שזה נק' מחכה כמו אם יתמהמה חכה לו<sup data-n=\"484\">25</sup> כנ\"ל וד\"ל).\n<b>אך</b> הנה בחי' גילוי אור התעה\"פ הזה שבעצמו' אא\"ס המלובש ברצה\"ע שבמצות הוא שיהי' לעתיד דוקא לאחר תחה\"מ שהמתים יקומו בטל העליון שהוא בחי' הארה בעלמא מאותו התעה\"פ הנ\"ל כמ\"ש כי טל אורות טליך בחי' טלא דבדולחא טלא דנטיף מעתיקא סתימאה כו' בחי' התענוג הפשוט הנ\"ל וכמ\"ש ועצמותך יחליף שעצמות המתים יחיו ויקומו מחיות אור העליון הזה מפני שזה האור הוא העליון ביותר שהוא בבחי' א\"ס ממש יוכל גם גוף ועצמות גשמיים לקום ולחיות ממנו כמ\"ש במ\"א<sup data-n=\"485\">26</sup> וד\"ל. וזהו שבברכה אחרונה נא' משמח חתן עם הכלה, דהיינו בברכה זו אנו או' מהרה ישמע בערי יהודא כו' שמדבר לעתיד דוקא שאז יהי' בחי' גילוי התענוג העליון הפשוט הנ\"ל, והוא ע\"י בחי' עיון התו' דישראל דוקא כנ\"ל בפי' מחכה לו למאן דדייק",[["483","24","<b>והחכ' מאין תמצא</b>: איוב כח, יב."],["484","25","<b>אם יתמהמה חכה לו</b>: חבקוק ב, ג."],["485","26","<b>כי טל אורות. . טלא דבדולחא טלא דנטיף מעתיקא סתימאה. . ועצמותיך יחליץ. . כמ\"ש במ\"א</b>: ישעי' כו, יט. ראה זח\"ב סא, ב. סב, ב. זח\"ג קכח, ב. קלה, ב. רפח, א. ס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' שנו ואילך וע' תרלז ואילך."]]],[1900420127,"מילי' דחכ' כו' ומאחר שישראל הן הממשיכי' לבחי' התענוג הזה הרי הם נק' חתן בחי' משפיע וממשיך, וה\"ז ממש כמו זיווג דכר ונוק' שמבחי' תעה\"פ העצמי שבטיפה שבמוח מוליד ולד כו', כך מבחי' התענוג העליון הפשוט שישראל ממשיכי' נולדו נשמות חדשות לעתיד. ואמנם אין תולדה רק מיחוד וזווג דו\"נ, ובחי' נוק' המקבל בחי' התעה\"פ שנמשך ע\"י ישראל היא התו' עצמה שנק' מאורסה לישראל כנ\"ל, שהרי בדיוק מילי דחכמתא הנ\"ל הרי נתלבש ונתגלה בחי' התעה\"פ באותן ההלכות שבתו' שנק' מילי דחכ', ואותיות הכל\"ה הוא אותיו' הלכ\"ה<sup data-n=\"486\">27</sup> שהיא בחי' כלי ממש לקבל בתוכה בחי' גילוי אור התעה\"פ שברצון שלמע' הרבה מבחי' החכ' וטעם שבהלכה זו כמ\"ש והחכ' מאין תמצא כו', וזהו שההלכות קודם לגילוי התענוג הזה בחי' דכר נק' בתולות כמ\"ש בתולות אחרי' כו' כמשארז\"ל ועלמות אלו הלכות<sup data-n=\"487\">28</sup> כו' (ומשניות וברייתות נק' נשים כמו ששים המה מלכות<sup data-n=\"488\">29</sup> כו' ושמונים פלגשים כו' ועלמות אין מספר כו').\n<b>וזהו</b> שהתו' נק' ברית כמ\"ש אלה דברי הברית<sup data-n=\"489\">30</sup> כו', כי התו' נק' כלה שמקבלת מבחי' אור תענוג העליון ע\"י ישראל במצות עיון התו' דוקא כמ\"ש יעשה למחכה לו כו', וכמו שהאשה אינה כורתת ברית אלא למי שעשאה כלי דוקא כמו כי בועלייך עושייך<sup data-n=\"490\">31</sup> כו', כך בחי' התו' שנק' כלה אינה כורתת ברית אלא למי שעשאה כלי בבחי' המשכת אור תענוג העליון מבחי' שעשועי המלך בעצמותו, והן ישראל הממשיכי' בה ע\"י מצות עיון התו' דוקא כנ\"ל. וזהו אלה דברי הברית כו' כי קודם שנמשך בתו' מבחי' תענוג העליון נק' בתולות ועלמות כנ\"ל, וז\"ש א\"ת מורשה אלא מאורסה כנ\"ל וד\"ל. אך אעפ\"כ אנו אומרים משמח חתן עם הכלה דעיקר שמחת החתן באה עם הכלה דוקא שבעבור הכלה משמח את החתן, כי הגם שישראל ממשיכי' בחי' התעה\"פ הנ\"ל בתו' שנק' כלה מ\"מ מאחר שהמשכה זאת באה מסיבת עיון התו' דוקא שהו\"ע הדיוק במילי דאוריי' א\"כ אם לא התו' לא הי' נמשך בחי' תענוג זה. ולפ\"ז גם ישראל אינן מקבלין שמחה זו ותענוג עליון זה כ\"א בשביל הכלה דוקא שהיא התו' דוקא, ולזה א' משמח חתן שהן ישראל עם הכלה כלומר בשביל הכלה דוקא (והטעם הוא מפני שנעוץ תחילתן בסופן דוקא וכל עיקר התעוררו' תעה\"פ שבעצמו' הוא בשביל סוף מעשה שהוא בחי' המקבל דהיינו בחי' חכ' שבתו' משום דבחכ' יסד ארץ וכמ\"ש אם לא בריתי<sup data-n=\"491\">32</sup> כו' חוקות שמים וארץ כו', וע\"כ ראשית גילוי אא\"ס הוא בחכ' דוקא כמ\"ש ה' קנני ראשית דרכו<sup data-n=\"492\">33</sup>",[["486","27","<b>ואותיות הכלה הוא אותיות הלכה</b>: ראה להלן במאמר שלאח\"ז סוף אות ט'. וש\"נ."],["487","28","<b>בתולות אחרי'. . ועלמות אלו הלכות</b>: תהלים מה, טז. וראה בהנסמן להלן בסמוך."],["488","29","<b>ששים המה מלכות</b>: שה\"ש ו, ח. ראה שהש\"ר עה\"פ. במדב\"ר פי\"ח, כא. זח\"ג רטז, א."],["489","30","<b>אלה דברי הברית</b>: ראה לעיל קרוב לתחילת המאמר. וש\"נ."],["490","31","<b>שהאשה אינה כורתת. . כי בועלייך עושייך</b>: סנהדרין כב, ב. ישעי' נד, ה."],["491","32","<b>דבחכ' יסד. . אם לא בריתי</b>: משלי ג, יט. ירמי' לג, כה."],["492","33","<b>ה' קנני ראשית דרכו</b>: משלי ח, כב."]]],[1900420128,"פי' ראשית דרכו והילוכו בבחי' התענוג שבעצמותו, וזהו בראשית בשביל התו' שנק' ראשית<sup data-n=\"493\">34</sup> בתי\"ו בחי' נוק' וראש הוא בחי' דכר כו', וע\"כ נק' הלכה כמו הליכות עולם הליכות אלי<sup data-n=\"494\">35</sup> כו' שבה הילוך גילוי אא\"ס דוקא מפני שנעוץ תחילתן בסופן וסוף מעשה עלה במחשבה תחילה וכמ\"ש אשת חיל עט\"ב נקבה תסובב גבר כו', וכמ\"ש במ\"א בענין ארץ קדמה<sup data-n=\"495\">36</sup> כו' וד\"ל).\n<b>והנה</b> יש עוד בחי' ומדריג' שנית בתו', והוא ענין קריאת התו' בדיבור וכמ\"ש ודברת בם (מלבד מצות עיון התו' הנ\"ל שזהו מ\"ש והגית בו כו' כנ\"ל), דהיינו שלא בעיון השכל בדקדוק עומק טעם ההלכות וטעמי המקראות להשיגם על בורי' אלא רק לקרות אותיות וצירופי' בלבד כמו לקרות תנ\"ך או לקרות ולשנות תושבע\"פ דברים כהווייתן, והוא מ\"ש בזוה' מל' פה תושבע\"פ קרינן לה<sup data-n=\"496\">37</sup>, ועי\"ז ממשיכי' בחי' גילוי אא\"ס למטה באותיו' התו', שהרי דבר ה' הוא אומר בדבורו ודבריו חיים וקיימים והקב\"ה יושב ושונה כנגדו כמו בשעת מ\"ת דכתיב וידבר אלקי' כו' שזהו מארז\"ל ביום חתונתו זה מ\"ת<sup data-n=\"497\">38</sup> כו'. ונמצא בחי' קריאה זו ה\"ז בחי' המשכה והשפעה דבחי' דכר והתו' בחי' מקבל הגילוי אור זה מעצמו' אא\"ס ב\"ה במה שקורא אותן וממשיכן באותיו' התו' הללו, וכמ\"ש קרוב ה' לכל קוראיו לכל אשר יקראוהו באמת ואין אמת אלא תו', והקריאה באמת היינו שקורא וממשיך עצמיו' אא\"ס שיהי' מתגלה בתוך אותיו' התו' שנק' אמת, והיינו באמת בתוך האמת כידוע. ונמצא שזהו כמו עד\"מ הקורא את המלך שיפנה אליו בעצמותו שהוא בדבור דוקא ולא בהגיון במח' כו' וכמארז\"ל הקורא בתו' קורא בשמותיו של הקב\"ה<sup data-n=\"498\">40</sup> וכו' וד\"ל.\n<b>וזהו\"ע</b> הברכה הקודמת משמח חתן וכלה ולא עם הכלה, לפי שאין שמחת החתן באה מן הכלה אלא אדרבה בחי' שמחת כלה מקבלת מן החתן, כי הרי הוא משפיע בה גילוי אא\"ס ע\"י הדבור שלו שמדבר וקורא וממשיך באותיו' התו' שנק' כלה (ושמחתו קודמת כמא' רב ששת חדאי נפשאי<sup data-n=\"499\">41</sup> לך",[["493","34","<b>בראשית בשביל התו' שנק' ראשית</b>: רש\"י ר\"פ בראשית."],["494","35","<b>הליכות עולם הליכות אלי</b>: חבקוק ג, ו. תהלים סח, כה."],["495","36","<b>אשת חיל עט\"ב נקבה תסובב גבר. . במ\"א בענין ארץ קדמה</b>: משלי יב, ד. ירמי' לא, כא. חגיגה יב, א. וראה סידור רפו, א. רפז, ב. ס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' קעב. רלא. שפא. שע\"ת ח\"א כז, א. תו\"ח בראשית ח, ג."],["496","37","<b>ודברת בם. . מל' פה תושבע\"פ קרינן לה</b>: ואתחנן ו, ז. תקוני זהר בהקדמה ד\"ה פתח אליהו."],["497","38","<b>והקב\"ה יושב ושונה כנגדו. . וידבר אלקי'. . ביום חתונתו זה מ\"ת</b>: תדא\"ר פי\"ח. יתרו כ, א. שה\"ש ג, יא. תענית כו, ב."],["498","40","<b>הקורא בתורה קורא בשמותיו של הקב\"ה</b>: ראה זח\"ב קכד, א. רמב\"ן עה\"ת בהקדמה. ועוד."],["499","41","<b>כמא' רב ששת חדאי נפשאי</b>: פסחים סח, ב."]]],[1900420129,"קראי תנאי כו', ומ\"ש בתורתו<sup data-n=\"500\">39</sup> יהגה בעיון קאי בבחי' כלה לגבי עצמו' אא\"ס שמתגלה בדיוק דאוריי', משא\"כ בחי' כלה זו מקבל מבחי' קריאת האדם וזהו ובתורת ה' חפצו<sup data-n=\"501\">42</sup> כו'), ובבחי' זו א' משמח חתן וכלה וי\"ו זה דוכלה הוא בחי' המשכה דקריאת התו' שהוא מן החתן אל הכלה וכמ\"ש לכל אשר יקראוהו באמת כנ\"ל וד\"ל.\n<b>וזהו</b> מ\"ש שערך כעדר העזים שגלשו מהר גלעד, פי' הר גלעד הוא כענין שנא' עד הגל הזה<sup data-n=\"502\">43</sup> שהוא ג\"ל ע\"ד כו' אם אני לא אעבור אליך כו'. כי הנה ידוע בשרש בחי' יעקב ולבן למע' שיעקב הוא בעל עולם האצי' דיו\"ד עקב הוא בחי' חכ' דאצי' שבחכ' אתברירו כו' והוא שרש התו' להבדיל בין טמא לטהור כו' כידוע, ובחי' לבן הוא בחי' לובן העליון שלמע' מן האצי', והוא בחי' התעה\"פ שבעצמו' כנ\"ל שלמע' הרבה מן החכ' כמ\"ש והחכ' מאין תמצא בבחי' הארה בעלמא בדרך דילוג גדול כו' כנ\"ל. וזהו\"ע ג\"ל ע\"ד שהוא בחי' הפרסא המפסקת בין המאציל עצמו לנאצלי' (וכמ\"ש והבדילה הפרוכת לכם<sup data-n=\"503\">44</sup> בין קדש ובין קה\"ק, שבחי' עצמו' המאציל הוא בבחי' תענוג ורצה\"פ שנק' כתר שבכתר בחי' גלגלתא בכלל שזהו שנק' בחי' קה\"ק, ויש בחי' פרסא שנק' פרוכת מבדלת בינו לבין הקדש שהוא בחי' ח\"ע בחי' חכ' שבכתר (והוא כמו בחי' קרומא דאוירא<sup data-n=\"504\">45</sup> כו'). והנה הגל הזה עשוי מאבנים שהן בחי' אותיו' בלתי מסודרים אלא כמו גל אבנים, וכידוע בס\"י שאותיו' נק' אבנים<sup data-n=\"505\">46</sup> וכשהן בסדר וצירוף יוכל להתגלו' ע\"י אור בגילוי ממש, אך כשבלתי מסודרי' זעג\"ז כמו משל הגל הוא בחי' הפסק גמור (וכדוגמת שינוי הצירופי' המבולבלי' בחלומות שמעין צירופי' שבהרהורי לבא ביום כמ\"ש במ\"א<sup data-n=\"506\">47</sup>).\n<b>והנה</b> מפני בחי' הגל וההפסק הזה שבין לובן העליון הנ\"ל ליעקב בעל עולם האצי' א\"א שיבא ויומשך שום אור ושפע מעצמו' המאציל באצי' וכמ\"ש לבן ליעקב אם אני לא אעבור אליך כו' רק בבחי' דילוג הערך מאד שהוא ע\"י בחי' שערות וצמצומי' גדולי' וכמשל הבקיעה שבוקע האור דרך מסך גם שארוג בעובי מאד מ\"מ בוקע קצת הארה ממנו, וכך גם מהפסק דגל אבנים",[["500","39","<b>קרוב ה'. . ואין אמת אלא תורה</b>: תהלים קמה, יח. ראה ברכות ה, רע\"ב. ירושלמי ר\"ה פ\"ג, ה\"ח. איכ\"ר פתיחתא ב. תקו\"ז תכ\"א (נ, סע\"א)."],["501","42","<b>בתורתו יהגה. . וזהו ובתורת ה' חפצו</b>: תהלים א, ב [ואוצ\"ל: וזהו בתורת]. וראה בארוכה לעיל ח\"א ע' יט. קעד. רסז. ובהמ\"מ שם. ס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' תרסב."],["502","43","<b>שערך כעדר העזים. . עד הגל הזה</b>: שה\"ש ד, א. ויצא לא, נב."],["503","44","<b>והבדילה הפרוכת לכם</b>: תרומה כו, לג."],["504","45","<b>קרומא דאוירא</b>: זח\"ג קכח, ב. וראה בהמ\"מ להלן בהמאמר שלאח\"ז, אות י\"ב."],["505","46","<b>בס\"י שאותיו' נק' אבנים</b>: ס' יצירה פ\"ד מי\"ב."],["506","47","<b>שינוי הצירופים המבולבלים בחלומות שמעין צירופים שבהרהורי לבא ביום כמ\"ש במ\"א</b>: ראה תו\"ח ויחי קב, ד. שמות נב, א. ס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' תשפז. דברים ח\"א ע' לא. נ\"ך ע' א [ובהמ\"מ שם]. ועוד."]]],[1900420130,"יוכל לעבור קצת שפע דרך חללים דקים שבגל אבנים, וזהו יעקב יבקע<sup data-n=\"507\">48</sup>, הנה לפרקים יוכל האור והשפע לבוא, וכמ\"ש שפנימי' החכ' דאצי' שנק' אור אבא מקבל מבחי' מזל ונוצר<sup data-n=\"508\">49</sup> כו', ולמע' יותר גם בחי' ח\"ס מאין תמצא בבחי' דילוג גדול מאד שהוא ע\"י בחי' בקיעת הקרומא כו' שנק' פרסא ופרוכת כנ\"ל, וכך הוא עד רום המעלו' וד\"ל.\n<b>ואמנם</b> גם זה הצמצום הגדול הנה הוא בא ונמשך ע\"פ מאמר קו המדה שמודד כל אור ושפע הבא בבחי' ההשתל' מעצמו' המאציל לנאצלי' כו', ובחי' מדידה נק' מאמר קו המדה שהוא נמשך ג\"כ מעצמות המאציל וכמ\"ש מי מדד בשעלו מים<sup data-n=\"509\">50</sup> שהוא בחי' גילוי אור בחכ' ויש מים עליוני' ח\"ע וחכ' תתאה כו' וד\"ל. אך הנה כ\"ז מה שאינו נמשך מבחי' לובן העליון רק ע\"י בחי' הצמצום במדה רק לפי אופן וסדר ההשתל' הקדומה שכבר קדם ברצון המאציל דהיינו שבבחי' וסדר ההשתל' התמידי הנמשך מן המאציל לנאצלים א\"א שיומשך משם רק בבחי' צמצומים בבחי' שערות וכה\"ג וכמ\"ש והחכ' מאין תמצא בבחי' דילוג וכו' וד\"ל, אך ע\"י בחי' ומדריג' העליונה שלמע' מבחי' סדר ההשתל' התמידי יוכל להיות השפעה והמשכה עליונה יותר שלא ע\"י בחי' צמצום דשערות שבא בשינוי המהות כו' אלא האור נמשך ובא בחכ' מבחי' עצמו' ומהות דלובן העליון כמו שהוא בעצם בלתי הלבשה והסתר בבחי' שערות המכסים ומסתירים כו', וזהו ע\"י ענין לימוד התו' דוקא, דהגם שידוע דאוריי' מח\"ע נפקת<sup data-n=\"510\">51</sup> ויש בחי' פרסא מפסקת שנק' ג\"ל ע\"ד כנ\"ל שא\"א להאיר בח\"ע כ\"א ע\"י בחי' שערות כנ\"ל, זהו בח\"ע מצד עצמה כמו שהיא למע', אבל בח\"ע שבתו' הנגלית לנו המלובשת בקשיות כשקורא בתו' זו דוקא הרי ממשיך וקורא לבחי' מהו\"ע המאציל שיתלבש בח\"ע שבאותיו' הללו בלי שום לבוש והסתר אלא כמו שהוא בעצם, כמו במ\"ת דכתי' וידבר אלקי' אנכי כו', וכן במצות עיון התו' דדייק במילי דאוריי' כנ\"ל שיעשה למחכה לו בחי' גילוי אור תעה\"פ כמו שהוא בלי העלם ולבוש כלל וכמ\"ש עין לא ראתה כו' אבל למחכה לו יעשה בחי' ראי' בעין בעדן זה כמ\"ש ולא יכנף עוד מוריך כו' והיו עיניך רואות את מוריך כו' וד\"ל.\n<b>וזהו</b> שערך כעדר העזים שגלשו מהר גלעד, פי' שערך הוא בחי' הלכות התו' שנק' נימין דמטרוניתא<sup data-n=\"511\">52</sup> כו' שע\"י לימוד ההלכות בדבור דוקא שנק' מל' פה תושבע\"פ קרינן לה כנ\"ל ה\"ז כמו עדר העזים שגלשו שנגלשו ונמרטו",[["507","48","<b>יעקב יבקע</b>: ראה בהנסמן להלן בסוף המאמר."],["508","49","<b>וכמ\"ש שפנימי' החכ' דאצי'. . מבחי' מזל ונוצר</b>: ע\"ח שער הכללים פ\"ה. ובכ\"מ."],["509","50","<b>מי מדד בשעלו מים</b>: ישעי' מ, יב."],["510","51","<b>דאוריי' מח\"ע נפקת</b>: זח\"ב סב, א. פה, א. קכא, א. ועוד."],["511","52","<b>הלכות התורה שנק' נימין דמטרוניתא</b>: ראה להלן המאמר שלאח\"ז ריש אות ט\"ו. וש\"נ."]]],[1900420131,"שערות שלהן והן מקורחין בלא שערות כו', ובחי' גלישה זו שגלשו הוא מהר גלעד דוקא למע' מבחי' הפרסא שמבדלת שנק' גל עד להיות כי משם בוקע האור שלא ע\"י צמצום המסך הזה אלא כמו שהוא בעצם התעה\"פ בלי לבוש ושינוי המהות כלל, ע\"כ הרי גלישה זו מן הצמצום דשערות הוא מהר הגלעד כמו שהוא בבחי' מריטה מן השערו' כו', ולהיות שכל ההלכות והמקראות הן נקראי' בדבור עד שנגלשו כל בחי' שערות כו' והיינו מאן דגליש למטרוניתא<sup data-n=\"512\">53</sup> כו'. ושרש גלישה זו הוא מחמת הר הגלעד שנמשך משם בלי צמצום דשערות כנ\"ל (והיינו שנשאר הר הגלעד קרח מפני היותו ממשיך הכל שלא ע\"י שערות כמשי\"ת בעז\"ה).\n<b>ולהבין</b> כ\"ז בתוס' ביאור הנה ילה\"ק עוד ענין א', והוא דכמו שיש בחי' פרסא מבדלת בין עצמו' המאציל לנאצלים כנ\"ל, כך יש בחי' פרסא מבדלת בין האצי' לבריאה שנק' ג\"כ ג\"ל ע\"ד, והוא ג\"כ עשוי מאבנים שהן צירופי אותיו' בהשתנות כגל אבנים כנ\"ל, וגם שם הו\"ע ההפסק בין לבן ליעקב בגל אבנים הזה, אך הוא להיפוך מהפסק גל אבנים שבין המאציל לנאצלים הרי בחי' לובן העליון למע' הרבה מבחי' יעקב שהוא באצי', אבל מאצי' לבריאה נהפוך הוא שבחי' לבן למטה מיעקב שיעקב הוא באצי' ולבן הוא בבחי' נוגה דבריאה וההפסק הוא שלא יעלה לבן דבריאה לאצי'. וזהו אם אני לא אעבור אליך ואם אתה לא תעבור אלי, שלא יתגלה בחי' יעקב דאצי' בנוגה דבריאה כו'. וביאור הדברי', הנה יש ב' בחי' לבן, הא' בחי' לבן דקדושה שהוא בחי' לובן העליון בחי' התעה\"פ שבעצמו' שלמע' הרבה מבחי' החכ' דאצי' בחי' יעקב, עד שיש בחי' פרסא בינו ליעקב מקור האצי' דהיינו שאין האור בא ונמשך מבחי' לובן העליון לחכ' רק דרך שערות בלבד כנ\"ל ולא שנמשך בדרך השתל' עו\"ע רק דרך הפסק הפרסא, וזהו אם אני לא אעבור אליך כו' ואם אתה לא תעבור אלי שבחי' יעקב דאצי' לא יעלה לשם כ\"א ע\"י בחי' הסתר וצמצום לבוש כמו לבוש הנשמות בג\"ע, והב' בחי' לבן דנוגה דבריאה שהוא בחי' התענוג שנפל למטה בבחי' פירוד מאלקו' והוא למטה מטה אחר צמצום גדול דמסך ופרגוד שבין אצי' לבריאה כו', ולבן זה הוא למטה מטה הרבה מיעקב שהוא בחי' חכ' דאצי' ואינו מקבל רק בבחי' ריחוק ודילוג גדול בבחי' שערות וצמצום שמאיר ע\"י הפסק הפרסא שנק' ג\"כ ג\"ל ע\"ד גל אבנים, וגם בזה לבן או' ליעקב אם אני לא אעבור אליך שאין רצוני לעלות ולהיות בבחי' ביטול לאלקות ואתה לא תעבור אלי שאינו חפץ בבחי' גילוי אור החכ' דאצי' לברר לנוגה דבריאה כו' וד\"ל.\n<b>והנה</b> כ\"ז הוא ע\"פ מאמר קו המדה שנמשך הקו הזה מעצמות המאציל להיות בחי' מסך המבדיל בין המאציל לנאצלי' וכן מאצי' לבריאה כדי שלא יומשך האור והשפע רק בצמצום ומדה, והיינו בחי' המדידה ששיער ומדד",[["512","53","<b>מאן דגליש למטרוניתא</b>: ראה זח\"א ריז, א."]]],[1900420132,"בעצמו איך שתהי' סדר ההנהגה וההמשכה וההשפעה מעצמותו בעולמות, אך כאשר מתעורר בחי' רב חסד וטוב מעצמו' המאציל בחי' תוס' הארה חדשה שלמע' מכפי הסדר הקבוע ע\"פ מאמר קו המדה הנ\"ל אזי נמשך בחי' הארה גדולה מעצמותו ממש שלא ע\"י בחי' צמצום ודילוג דבחי' שערות או הפסק הפרסא הנ\"ל. וזהו שגלשו מהר הגלעד וכמ\"ש בזוהר דגליש למטרוניתא כו', עד\"מ בגילוח שערות הראש הרי מתגלה עצם הגולגלת כמו שהיא אשר קודם הגילוח הזה היתה עצם הגולגלת מסותרת ונעלמת מעין הרואה מפני השערות שהיו מכסים עלי' ומסתירות ומעלימו' אותה כמו הלבוש שמכסה את הגוף כידוע שהשערות נק' בשם לבוש, וכך למע' בבחי' המל' שנק' מטרוניתא ובחי' כלה ובחי' הגלגלתא שבה הוא הנק' כתר מל', אך בחי' השערות שע\"ג הראש הוא בחי' צמצום ולבוש שרצון העצמי מלובש בה בשינוי המהות, ומאן דגליש למטרוניתא עד\"מ בגילוח השערו' שזהו בחי' גילוי עצם הרצון כמו שהוא בלי לבוש והעלם, והיינו ע\"י הקריאה בדבור תושבע\"פ מל' קרינן לה כנ\"ל, וע\"כ א' שערך דקאי בשערות דגלגלתא דנוק', ואמנם שרש גלישה זו מהר הגלעד שהוא בחי' כ\"ע שבחי' לובן העליון שלמע' מבחי' חכ' דאצי' וכמ\"ש כתר מל' דאיהו כ\"ע<sup data-n=\"513\">54</sup> כו' לפי שגם שם עובר האור שלא ע\"י בחי' שערות אלא נמשך מגילוי רצון ותענוג פשוט כמו שהוא בעצמותו בלי לבוש והעלם כלל כנ\"ל וד\"ל (והיינו כמו דגליש למטרוניתא שעצם הגולגלת מתגלה כו', כך למע' בבחי' גלגלתא דא\"א וע\"י או דא\"ק בחי' עצם הגולגלת מתגלה ואין בחי' השערות מכסים כלל כו' וד\"ל ולפי הנ\"ל בענין לבן שלמטה מיעקב שנמשך לו ע\"י שערות כו' פי' דגליש הוא להסיר בחי' השערות שיונקי' משם בחי' היכלות דנוג\"ה כמו וגלחה את ראשה כמ\"ש במ\"א<sup data-n=\"514\">55</sup>).\n<b>ובכ\"ז</b> יובן ג\"כ מ\"ש ועמדו רגליו<sup data-n=\"515\">56</sup> ביום ההוא על הר הזיתים ונבקע ההר כו' חצים אל הים הקדמוני כו'. דהנה ידוע דשמן זית הוא בבחי' חכ' והר הזיתים היינו המקום שבו צומחי' הזיתים שהוא בחי' מקור החכ' ומקור חוצבה הוא בחי' צומח שצומח אור החכ' מהר זה, והרי ההר עצמו בחי' דומם והצמיחה ממנו הוא רק בחי' צומח שבדומם. והענין הוא דבחי' הר זה הוא בחי' מדות שבכתר עצמו שלמע' מן החכ' הרבה כנ\"ל והחכ' מאין תמצא מבחי' אין דכתר רק בבחי' הארה המצומצמת בשינוי המהות דהיינו רק בחי' צומח שבדומם המדות שבכתר עצמו והיינו ע\"י הפסקת בחי' הפרסא שמפסיק בין כתר לחכ' כנ\"ל והחכ' מקבלת רק דרך דילוג בחי' הצומח דשערות ע\"י הפסקת הפרסא כו' וכנ\"ל בפי' הר הגלעד, וזהו ג\"כ ענין צמיחת הזיתים בהר הזיתים וד\"ל. אך כ\"ז הוא ע\"פ סדר השתל' דמאמר קו המדה שא\"א שיאיר אור מעליון לתחתון",[["513","54","<b>כתר מל' דאיהו כ\"ע</b>: ע\"פ תקוני זהר בהקדמה ד\"ה פתח אליהו."],["514","55","<b>וגלחה את ראשה כמ\"ש במ\"א</b>: תצא כא, יב. ס' מאמרי אדהאמ\"צ דברים ח\"ב ס\"ע תקלד ואילך."],["515","56","<b>ועמדו רגליו</b>: זכרי' יד, ד ואילך."]]],[1900420133,"שאין ערוך אליו רק מבחי' התחתונה שבו שהוא בחי' צומח שבדומם דהר הזיתים או ע\"י הפסקת גל אבנים שמאיר דרך בקיעה בבחי' שערות כנ\"ל (ודמיון לד\"ז ארץ מגדלת חכמים<sup data-n=\"516\">57</sup> גם שהארץ בחי' דומם אבל מזל הארץ מחכים את יושבי' שהגדל באקלים זה יהי' חכם מפני שכל אנשי האקלים זה חכמים בטבעם מצד טבע הארץ שמגדלת חכמים, ויש ארץ מגדלת טפשים או אנשי מדות כו'), אבל לעתיד בהגלות נגלות מבחי' עצמו' המאציל שלמע' מבחי' מאמר קו המדה המצמצם האור לבא במדה ע\"י העלם וצמצום כו', אז כתי' ונבקע ההר מחציו כו' שלא יהי' עוד בחי' צמיחת הזיתים שהוא בחי' גידול החכ' ממקור חוצבה כנ\"ל ע\"י בחי' כח הצומח שבדומם ההר מצ\"ע אלא יבקע ההר מחציו כו' בבחי' בקיעת אור עצמות הכתר שיאיר בחכ' שלא ע\"י בחי' פרסא מפסקת כלל, כנ\"ל בבחי' מצות לימוד התו' בדבור שקורא לבחי' עצמו' התעה\"פ ועצמו' הרצה\"פ הנק' רעוא דכל רעווין כמו שהוא בעצם דוקא כנ\"ל, כך ע\"י מצות עיון התו' שנא' בו יעשה למחכה לו למאן דדייק מילי' דאורייתא כו' כנ\"ל. וזהו יעקב אותיות יבקע כמ\"ש אז יבקע כשחר אורך<sup data-n=\"517\">58</sup> אז דוקא שהוא לעתיד בהגלות נגלות אור עצמו' המאציל שלא ע\"י בחי' פרסא ולבוש המעלים כלל, כמ\"כ מאצי' לבי\"ע לא יהי' בחי' הפסק כלל בגל אבנים אלא יתגלה אור האצי' בבי\"ע כמו שהוא בלי לבוש מסתיר כלל כנ\"ל. והא בהא תליא דמשום שבחי' כ\"ע שבבחי' עצמות המאציל יתגלה כמו שהוא ע\"כ ממילא גם למטה מטה מאצי' לבי\"ע יתגלה בחי' כתר מל' כמו שהוא בלי לבוש מסתיר כלל דכתר מל' איהו כ\"ע משום דנעוץ תחילתן בסופן וסוף מעשה עלה במחשבה תחילה כידוע. וזהו שארז\"ל עתידים צדיקי' שיאמרו לפניהם קדוש<sup data-n=\"518\">59</sup>, בחי' קדוש זהו בחי' הארת בחי' סובב הכללי הנק' מקיף הכללי שמקיף ד' עולמו' אבי\"ע בשוה ושם שוין אצי' ובריאה וכמ\"כ שוין מקור האצי' והאצי', וע\"כ לפניו נגלה כל העלם ומסך שנעשה ע\"פ מאמר קו המדה להאיר באצי' ובריאה שוה ממש וכמ\"כ במקור האצי' ובאצי' בשוה כו', וע\"כ גם לפני הצדיקי' שנבראו יש מאין מבחי' מל' דאצי' יאמרו קדוש שיש בחי' הארת סובב הנ\"ל בהן כמו במקור האצי' בשוה ממש כי בבחי' הוי\"ו דקדוש זהו שהוא בחי' המשכת המקיף הכללי שוה ומשוה מעלה ומטה כדמיון צורת הוי\"ו שאינו אלא קו שאין בו הפרש בין תחלתו לסופו כו' וד\"ל.\n<b>ואחר</b> כ\"ז יובן בתוס' ביאור ענין שני הברכות האחרונים דמשמח חו\"כ ומשמח חתן עם הכלה. דהנה הגם שמבואר למע' שבהגלות נגלות מבחי' עצמו' המאציל אז יבא האור והשפע שלא ע\"י לבוש והעלם כלל, והוא ע\"י מצות ת\"ת",[["516","57","<b>ארץ מגדלת חכמים</b>: ע\"פ זח\"א קכה, א. במדב\"ר פט\"ז, יב. וראה ס' מאמרי אדהאמ\"צ במדבר ח\"ד ע' א'תמט. וש\"נ בארוכה."],["517","58","<b>אז יבקע כשחר אורך</b>: ישעי' נח, ח."],["518","59","<b>עתידים צדיקים שיאמרו לפניהם קדוש</b>: ב\"ב עד, א."]]],[1900420134,"דוקא בעיון וקריאה כנ\"ל, ועז\"נ ביום חתונתו זה מ\"ת, והתו' נק' כלה בחי' מקבל האור והשפע כמ\"ש והחכ' מאין תמצא כנ\"ל באריכות. אמנם באמת לא ע\"י קריאה ועיון בלבד הוא שנעשה זה אלא ע\"י בחי' השמחה דוקא כמשל ביום חתונתו וביום שמחת לבו דוקא שנק' שמחת חתן ושמחת כלה כי ע\"י בחי' השמחה דוקא יוצא כל אור העצמות הסתום ונעלם לידי גילוי בלי העלם ולבוש כלל, כידוע שהשמחה מגלה כל צפון ונעלם שבבחי' העצמות, וכך במ\"ת נא' חכ' אדם תאיר פניו<sup data-n=\"519\">60</sup> בגילוי אורה ושמחה, וז\"ש כחתן יכהן פאר<sup data-n=\"520\">61</sup> כו', שאז לא יסתיר כלל מסך מבדיל כלל, עד\"מ כשהמלך בשמחה לא יאמר דבריו בהסתר והעלם אלא בגילוי כמו שהוא בעצם. וזהו שמח תשמח ריעים האהובי' שהן בחי' חו\"ב שנק' תרין ריעין<sup data-n=\"521\">62</sup> דלא מתפרשין כו' כאשר יבא בהן מבחי' השמחה שבעצמו' המאציל אזי משמח חו\"כ שעי\"ז יומשך האור והשפע מן החתן אל הכלה בלי העלם ולבוש כלל, וכנ\"ל בענין התו' שיעשה למחכה לו בלי לבוש כלל וכן במצות קריאה בדבור שנגלה האור כמו שהוא, וכ\"ז ע\"י שמחה דוקא וכמ\"ש רב ששת חדאי נפשאי לך קראי תנאי ורבא הוי אמר מילתא דבדיחותא<sup data-n=\"522\">63</sup> תחלה כו', כי מ\"ש עוז וחדוה במקומו הוא בשמחה של תו' דוקא שהתו' נק' עוז כמ\"ש ה' עוז<sup data-n=\"523\">64</sup> לעמו יתן כו'. ושרש הדברי' לפי שבחי' התענוג הפשוט הנ\"ל אינו מתגלה בחכ' שבתו' כ\"א ע\"י בחי' חדוה ושמחה שיעורר שמחה ותעה\"פ שבעצמו' שמאיר בלי לבוש כנ\"ל וד\"ל.\n<b>אך</b> גם בבחי' שמחה זו שמוציאה ומביאה מבחי' העלם עצמותו ממש לידי גילוי יש הפרש בין משמח חו\"כ ובין משמח חתן עם הכלה שהוא ההפרש אשר בין מצות עיון ומצות קריאה בדבור כנ\"ל, דמשמח חתן וכלה הוא בקריאה בדבור ומשמח חתן עם הכלה הוא במצות עיון דדייק במילי' דאוריי' שיעשה למחכה לו כנ\"ל. דהנה כתי' חכמות בחוץ תרונה ח\"ע וח\"ת חכ' בראש וחכ' בסוף<sup data-n=\"524\">65</sup>, וידוע דבחי' חכ' בראש עד\"מ עצם כח השכל באדם כמו לדייק במילי' דחוכמתא אם כך או כך והוא במצות עיון<sup data-n=\"525\">66</sup> התו' כנ\"ל, ולמע' ה\"ז בחי' חכ' בראש בחי' ח\"ע (בחי' ח\"ס או חכ' הקדומה דא\"ק כו'), ובחי' חכ' בסוף בחי' חכ' הגלוי' בדבור בלבד, והוא מצות הקריאה דתו' בדבור שנק' תושבע\"פ כו' כנ\"ל. ואמנם ידוע דנעוץ תחילתן בסופן שחכ' בראש עיקר גילוי' בדבור בחי'",[["519","60","<b>חכ' אדם תאיר פניו</b>: קהלת ח, א."],["520","61","<b>כחתן יכהן פאר</b>: ישעי' סא, יו\"ד."],["521","62","<b>חו\"ב שנק' תרין ריעין</b>: זח\"ג ד, א."],["522","63","<b>רב ששת חדאי נפשאי. . ורבא הוי אמר מילתא דבדיחותא</b>: פסחים סח, ב. פסחים קיז, א: דרבה כו', ובר\"ח שם ובכ\"מ גריס: ?דרבא\" [וראה תניא פ\"ז. ס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' תשמח. ח\"ד ע' א'תכט. א'תמג. ח\"ה ע' א'תשפד]."],["523","64","<b>עוז וחדוה במקומו. . שהתו' נק' עוז כמ\"ש ה' עוז</b>: דה\"א טז, כז [וראה גם לעיל ח\"א ע' כז]. תהלים כט, יא. ספרי ברכה לג, ב. ובכ\"מ."],["524","65","<b>חכמות בחוץ תרונה ח\"ע וח\"ת חכ' בראש וחכ' בסוף</b>: משלי א, כ. ראה זח\"א קמא, ב. כו, ב. ובכ\"מ."],["525","66","<b>לא ימוש. . בקריאה. . והגית. . מצות עיון</b>: יהושע א, ח. ראה הל' ת\"ת לאדה\"ז פ\"ב הי\"ב. ס' מאמרי אדה\"ז: תקס\"ה ח\"א ע' מה-ו. ח\"ב ע' תשד. על ענינים ? ס\"ע רכד. ס' מאמרי אדהאמ\"צ בראשית ע' תפד. תקכד. תקכז. ויקרא ח\"ב ע' תקצג. תשעד. דברים ח\"ד ע' א'שמא ואילך. שערי תשובה ח\"א ע' לט, ב. פירוש המלות לאדהאמ\"צ ה, ב (ספ\"ח). לקוטי ביאורים לאגה\"ת ע' מג."]]],[1900420135,"ח\"ת, ודרך כלל הוא ההפרש בין תושב\"כ שנק' ח\"ע לתושבע\"פ שנק' ח\"ת, ועל תושב\"כ נא' לא ימוש ספר התורה הזה מפיך בקריאה בדבור והגית בו יומם ולילה מצות עיון כי בתו' שבכתב דוקא להיות שרשה בח\"ע ונעוץ תחילתן בסופן ע\"כ בה דוקא מצות קריאה יותר מתושבע\"פ כידוע ועיקר שרשו הוא בחי' עיון והגית בו יומם כו' רק מפני שנעוץ תחב\"ס ע\"כ מצות קריאה עיקר, וע\"כ אפי' ע\"ה עולה לתו' כו' וד\"ל.\n<b>וזהו</b> ההפרש בין משמח חו\"כ למשמח חתן עם הכלה, דהנה מבואר למעלה שהשמחה מביאה מבחי' פנימי' ועצמי' לידי גילוי, וכמו שיש ב' מיני חכמות הנ\"ל כך יש ב' מיני שמחה, א' בחי' שמחה שמביאה לידי גילוי לבחי' ח\"ע, שהרי החכ' מאין תמצא בבחי' שערות בלבד ועל ידי השמחה תבא לידי גילוי ממקורה בלי לבוש והעלם כלל כנ\"ל, והב' בחי' שמחה שמביאה לידי גילוי בח\"ת בחי' חכ' שבדבור, עד\"מ כי כשאין המשפיע בשמחה לא ידבר בגילוי מחכמתו מאומה וע\"י השמחה מגלה בדבור הכל כו', כמו ענין שמחה שביין שא' אגברו חמרא אדרדקי כי היכא דלימרו כו'. ולפ\"ז הרי מובן ממילא שבחי' השמחה המביאה לידי גילוי בדבור בלבד הוא קטן בערך לגבי שמחה העצמיות שמביאה לידי גילוי חכ' בראש ממקור חוצבה בלי לבוש כו', וראי' לדבר זה ממה שאנו רואים בחוש שהממציא שכל חדש מעיקר ושרש החכ' יצהבו פניו בשמחה רבה לעצמו הרבה יותר משמחתו כשיגלה אותו שכל שהמציא מחדש בדבור לתלמידו, כמו ר\"א מצא תוספתא חדתא<sup data-n=\"526\">67</sup> צהבו פניו כו' וד\"ל, ואעפ\"כ אנו רואים שעיקר גילוי השמחה שבעצמותו במה שהמציא שכל החדש הוא כאשר בא לידי גילוי בדבור דוקא, אלא שהשמחה שבעצמותו הוא במקור החכ' והשמחה כשבאה בדבור הו\"ע שמחת לבו הבא בגילוי בלבד אבל הוא אותו השמחה עצמה ואם אין השכל הזה בא לידי גילוי בדבור לזולתו אין השמחה הזאת שלימה כמו שאין שלימות למשפיע בלתי מקבל שיקבל שפעו כו'. וכך יובן בב' מיני שמחה ב' מיני חכ' חכ' עילאה וחכ' תתאה, שבחי' שמחה דחכ' עילאה הוא בבחי' עיון התורה חכ' בראש שתבוא לידי גילוי ממקור חוצבה מאין בלי לבוש כו', ושמחה הב' במצות קריאת התורה בדבור כמו שאמר רב ששת חדאי נפשאי לך קראי לך תנאי, והא בהא תליא משום דנעוץ תחלתן בסופן שעיקר גילוי שמחה דחכ' הוא בא בגילוי הדבור דוקא ואם לאו אין שלימות כו'. וזהו ביום חתונתו וביום שמחת לבו, חתונתו שמחה",[["526","67","<b>ר\"א </b>[ר' אבהו]<b> מצא תוספתא חדתא</b>: ראה ירושלמי שבת פ\"ח ה\"א. ובהנסמן עוד להלן בהמאמר שלאחר זה, אות כ\"ז."]]],[1900420136,"עליונה שנתגלה חכ' עילאה ממקורה מאין ושמחת לבו בהגלות נגלות בדבור כמ\"ש וידבר אלקים כו', והיינו הטעם דבתורה שבכתב מצות קריאה עיקר שבה מתגלה בחי' טעם ותענוג ושמחה שבפנימיות חכ' עילאה שבה שעל ידי ההגיון כו' משום דנעוץ תחלתן בסופן דוקא כנ\"ל וד\"ל.\n<b>וזהו</b> ענין ב' הברכות הנ\"ל, דמשמח חתן וכלה הוא במצות קריאה בדבור שהחתן משפיע אל הכלה ובלעדי זה אין לו שלימות לעצמו כנ\"ל בבחי' שמחה הב' הבאה בדבור, והיינו משמח חתן ואח\"כ וכלה, וי\"ו זה דוכלה הוא שפע שמן החתן אל הכלה, כי חתן הוא בחי' חכ' עילאה שנמשך ומתגלה בחכ' תתאה כו', אבל מפני שנעוץ תחלתן בסופן הרי נעשה להחתן שלימות ע\"י שפע זאת שהמשיך בדבור דוקא, כי גם שקטנה היא בערך שמחתו העצמיות שהוא כאשר נמשך חכ' עילאה ממקורה כו' כנ\"ל, מ\"מ לזאת הי' כל עיקר שמחתו לעצמו כו'. וזהו שאחר כך אמר בברכה אחרונה משמח חתן עם הכלה וקאי בבחי' שמחה הא' שהוא שמחת חתן דוקא, דהיינו בבחי' עיון התורה כמו שצהבו פניו דר' אבוה כו' שזהו למחכה לו דדייק מילי' דאוריי' כנ\"ל, אבל אמר דשמחת חתן זה הוא רק עם הכלה כלומר בעבור הכלה משום דנעוץ תחלתן בסופן דוקא כנ\"ל. והיינו שהזכיר כאן ששון ושמחה, שהששון בחי' דכר ושמחה בחי' נוק', וקאי לעתיד דוקא כמ\"ש מהרה ישמע כו' שאז נאמר אשת חיל עטרת בעלה כו' (וכנ\"ל שהשמחה הזאת מצד התורה נלקחה, דגם ששמח בהמצא' שכל חדש הרי שכל זה בתורה מצאו והתורה נק' כלה כו' ומה שתלמיד מחדש כו', שעכשיו כנס\"י נק' כלה וקוב\"ה נק' חתן שהוא המשפיע כו' ולעתיד יהי' כנס\"י נק' חתן והתורה נק' כלה, אעפ\"כ משמח חתן עם הכלה שהוא בחי' שמחה שבעיון כשהוא מתגלה בדבור כו' מטעם הנ\"ל. וזהו ונבקע ההר חציו מזרחה בחי' חכ' עילאה וחציו ימ\"ה בחי' חכ' תתאה דהא בהא תליא (וכמ\"ש ביום ההוא יצאו מ\"ח<sup data-n=\"527\">68</sup> מירושלים חצים אל הים הקדמוני בחי' ח\"ע וחצים אל הים האחרון בחי' חכ' תתאה שמתחברים יחד למהוי אחד באחד, וזהו יהי\"ה ב\"פ י\"ה<sup data-n=\"528\">69</sup> כו' וד\"ל. וזהו אך יצא יצא יעקב<sup data-n=\"529\">70</sup> ב' יציאות וב' בקיעות דחכ' עילאה וח\"ת ע\"י בחי' שמחה כנ\"ל, וזהו חכמות בחוץ תרונה בחוץ דוקא על ידי בחי' השמחה והרינה כו' וד\"ל).",[["527","68","<b>ביום ההוא יצאו מ\"ח</b>: זכרי' יד, ח."],["528","69","<b>יהי' ב\"פ י\"ה</b>: לקו\"ת ושער הפסוקים להאריז\"ל זכרי' יד, ט. שער מאמרי חז\"ל בתחילתו."],["529","70","<b>אך יצא יצא יעקב</b>: תולדות כז, ל. וראה ע\"ח שער הארת המוחין (של\"ב) פ\"א. שם שער הכללים פ\"ח. פ\"י. לקו\"ת צו ח, ד. סידור רנז ד ואילך. ס' מאמרי אדהאמ\"צ במדבר ח\"ד ע' א'תקיג וע' א'תקמב. ובכ\"מ."]]],[1900420137,"<h3>להבין מה שבברכה כו' משמח חו\"כ</h3>\n<b></b><b>ב\"ה. תקפ\"ה (חתונת נכדי יהודא ליב שי' י\"ד חשון)</b>\n<b>להבין</b> מה שבברכה ראשונה<sup data-n=\"530\">1</sup> אומרים משמח חתן וכלה ובברכה אחרונה או' משמח חתן עם הכלה. הנה ארז\"ל ביום חתונתו זו מ\"ת<sup data-n=\"531\">2</sup> שהקב\"ה נק' חתן וכנ\"י נק' כלה<sup data-n=\"532\">3</sup> כידוע ע\"ש קבלת שפע הח\"ע דתומ\"צ שקיבלו במ\"ת שבזה נעשה יחוד קוב\"ה ושכינתי' למעלה שנק' חתן וכלה העליונים כו', ויש להבין מה הי' החידוש בזה הלא כבר מוימ\"ב הי' יח\"ע דחו\"כ למעלה שהוא יחוד בשם הוי' ואלקים שהוא בכלל ענין השפעת והמשכת אוא\"ס בעולמות בבחי' סובב וממלא בי' מאמרות שנעשה אז בחי' יחו\"ע דקודב\"ה ושכינתי' בכלל מסובב לממלא שזהו ענין חו\"כ למעלה בחי' משפיע ומקבל, וכידוע בענין כללות מע\"ב שנמשך ע\"י שם אלקים בחי' אותיות דבחי' המל' כמ\"ש ואתה מחי' את כולם<sup data-n=\"533\">4</sup> שהוא בחי' מקבל ממדות וחו\"ב דאצי' שבשם הוי' כידוע כמ\"ש בסוף ביום עשות הוי' אלקים ארץ כו' וכמארז\"ל בתחלה עלה במחשבה<sup data-n=\"534\">5</sup> לברוא במדה\"ד בש' אלקי' ואח\"כ שתף כו' (ואם בשביל ששפע זו על תנאי הי' אם יקיימו ישראל התומ\"צ כו' כמ\"ש אם לא בריתי כו' וכמ\"ש בראשית בשביל התורה<sup data-n=\"535\">6</sup> שנק' ראשית דח\"ע ובשביל ישראל שנק' ראשית שהוא בחי' יח\"ע דמשפיע ומקבל שהי' במ\"ת, עכ\"ז אין כל חדש בזה אחר שכבר הי' יח\"ע זה במע\"ב והי' נכלל בזה פנימית היח\"ע דקודב\"ה ושכינתי' שהן כנ\"י למעלה). ועוד יש להבין מה שלפעמים מצינו להיפך שכנ\"י נק' חתן והתורה נק' כלה",[["530","1","<b>להבין מה שבברכה ראשונה</b>: המאמר מיוסד על ד\"ה משמח חו\"כ בס' מאמרי אדה\"ז על מארז\"ל ע' תצד. ולעיל ד\"ה משמח חו\"כ שלפני-זה.\nוראה בהנסמן עוד להלן בהוספות ברשימת הכתבי-יד."],["531","2","<b>ביום חתונתו זו מ\"ת</b>: שה\"ש ג, יא. תענית כו, ב."],["532","3","<b>שהקב\"ה נק' חתן וכנ\"י נק' כלה</b>: ראה לעיל ח\"א ע' יח [ומציין שם — ”כמ\"ש במ\"א ע\"פ והוא כחתן יוצא מחופתו וע\"פ וכחתן יכהן פאר\"]. וע' נא [ע\"פ והוא כחתן]. ס' מאמרי אדהאמ\"צ דברים ח\"ג ע' תתנז [ע\"פ וכחתן יכהן]. ובלקו\"ת ברכה צד, א מציין בענין זה: בכמה דוכתי משמע ג\"כ דפי' ביום חתונתו היינו שישראל הם הכלה וכדפרש\"י ע\"פ ה' מסיני בא כו' כחתן היוצא להקביל פני כלה והוא מהמכילתא פ' יתרו וכ\"מ ג\"כ ברבות נשא פי\"ב ביום חתונתו זה סיני חיתונין היו כו' וע' זח\"ב נ\"ח א' פ\"ד א' כ\"ב א' ח\"ג סא, ב כו' גם ברבות ס\"פ ואתחנן איתא א\"ר ברכי' בעשר מקומות קרא הקב\"ה לישראל כלה. וראה עוד להלן בסמוך."],["533","4","<b>ואתה מחי' את כולם</b>: נחמי' ט, ו."],["534","5","<b>ביום עשות ה' אלקים. . בתחלה עלה במחשבה</b>: בראשית ב, ד. רש\"י ר\"פ בראשית. וראה ב\"ר פי\"ב, טו. לעיל ח\"א ע' רנח. וש\"נ."],["535","6","<b>אם יקיימו ישראל. . אם לא בריתי. . בראשית בשביל התורה</b>: שבת פח, א. ירמי' לג, כה. רש\"י ר\"פ בראשית."]]],[1900420138,"כמ\"ש מורשה א\"ת מורשה אלא מאורסה<sup data-n=\"536\">7</sup> כו' וכתי' כחתן יכהן פאר כו' והוא ע\"י ישראל שנאמ' ישראל אשר בך אתפאר<sup data-n=\"537\">8</sup> בפאר דתורה כו'.\n<b>אך</b> הנה ידוע שהתו' נק' ברית כמ\"ש אלה דברי הברית<sup data-n=\"538\">9</sup> כו' וכתי' אם לא בריתי כו', ויש להבין מהו ענין כריתת ברית דתורה עם ישראל שהוא למעלה הרבה יותר מכריתת ברית דאבות שהן המרכבה למעלה כו'. והנה יש להקדי' תחלה בשרש ענין העדן העליון שהוא העוה\"ב שנאמר בו עין לא ראתה אלקים זולתך יעשה למחכה לו כו'. דהנה א' אל תאמר זהו גן<sup data-n=\"539\">10</sup> זהו עדן כו', כי העדן הוא נברא מקדם והגן נברא בו אח\"כ כמ\"ש ויטע ה' אלקי' גן בעדן מקדם ונהר יוצא מעדן<sup data-n=\"540\">11</sup> להשקות את הגן כו'. והענין הוא כידוע שהעדן הוא בחי' עצם התענוג הפשוט שבעצמות א\"ס ב\"ה שנק' שעשועי המלך בעצמו והוא שיתגלה בעוה\"ב שע\"ז א' עין לא ראתה כו' אפי' משה והאבות כו', והגן הוא בחי' מקבל שמקבל הארה בעלמא מעצמות התענוג הנעלם הפשוט הזה ע\"י ריבוי צמצומים והעלמות בירידות המדריגות, והוא ע\"י הנהר שיוצא מעדן שמפסיק בין עדן לגן ונמשך להשקות את הגן כו' שיוכל לבא במקבלים בנשמות ומלאכים דגעה\"ע, כמו עץ נחמד למראה כו' ועה\"ח בתוך הגן<sup data-n=\"541\">12</sup> כו', ועליות הנשמות בכל חודש ושבת לקבל אפס קצה ההארה מבחי' עדן זה ויש בזה ריבוי מדריגות זו למעלה מזו בעליות המדריגות מעונג לעונג העליון יותר עד שיש כמה מיני ג\"ע זה למעלה מזה עד אין שיעור וקץ כלל כמ\"ש ילכו מחיל אל חיל כו', וכמו בעדן דעוה\"ב שא' ת\"ח אין להם מנוחה<sup data-n=\"542\">13</sup> שעולים בעילוי אחר עילוי בעליית המדריגות בעונג העליון עד אין שיעור למעלה מעלה בבחי' שעשועי המלך בעצמו שהוא בבחי' א\"ס ממש, וידוע שא\"א לעלות ממדריגה למדריגה עליונה הימנה אם לא בביטול המציאות לגמרי מכל וכל ממדריגה התחתונה עד שישכח<sup data-n=\"543\">14</sup> לגמרי בחי' העונג ההוא והי' כלא הי' ממש אז יוכל לבא ולעלות למדריגת העונג האלקי העליון ממנו הרבה לפי שאין ערוך כלל לתחתון לגבי עליון וכל דבר שעולה בעילוי שאינו בא בערך והדרגה ממהות למהות צ\"ל ביטול מהות הראשון לגמרי מכל וכל דוקא אז יוכל לעלות ולבא במהות העליון הנבדל ממנו בערך (ואפי' בדבר לימוד חכמה כשצריך לבא ולעלות",[["536","7","<b>שכנ\"י נק' חתן והתורה נק' כלה כמ\"ש מורשה. . מאורסה</b>: ברכה לג, ד. ברכות נז, א. וראה בהנסמן בארוכה בלקו\"ת ברכה צג, סע\"ד ואילך — בענין שלפעמים מצינו שישראל נק' חתן ותורה כלה ולפעמים מצינו להיפך שתורה נק' חתן וישראל כלה. ועיין עוד ע\"ד ב' אופנים אלו בס' מאמרים אדהאמ\"צ שמות ח\"א ע' א. ויקרא ח\"א ע' שלב. במדבר ח\"ב ע' שכז ואילך. ע' תרנט ואילך. ע' עתר ואילך. לעיל דרושי חתונה ח\"א ע' רמז וע' רסז."],["537","8","<b>כחתן יכהן פאר. . ישראל אשר בך אתפאר</b>: ישעי' סא, יו\"ד. מט, ג."],["538","9","<b>אלה דברי הברית</b>: תבוא כח, סט."],["539","10","<b>עין לא ראתה. . אל תאמר זהו גן</b>: ישעי' סד, ג. ברכות לד, ב."],["540","11","<b>ויטע ה' אלקים גן בעדן. . ונהר יוצא מעדן</b>: בראשית ב, ח. יו\"ד."],["541","12","<b>עץ נחמד. . ועה\"ח בתוך הגן</b>: בראשית שם ט."],["542","13","<b>ילכו מחיל אל חיל. . ת\"ח אין להם מנוחה</b>: תהלים פד, ח. סוף ברכות. וראה בהמ\"מ בס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' מו."],["543","14","<b>ר\"ז </b>[ר' זירא]<b> שהתענה. . שישכח</b>: ב\"מ פה, א. וראה גם לקו\"ש ח\"כ ר\"ע 319. חכ\"ד ס\"ע 26. ס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' מז. וש\"נ."]]],[1900420139,"להשגה העליונה יותר המובדלת בערך הרבה, כמו ר\"ז שהתענה כמה תעניתים שישכח לגמרי תלמוד בבלי כדי שיוכל לקבל תלמוד ירושלמי כו', וכל זמן שלא נתבטל ממהות השגה הראשונה בבחי' ביטול היש לגמרי לא יוכל לבא לעומק ההשגה העליונה ממנו, כענין מה פשפשת כו', כמו אשתומם כשעה חדא כו' שהוא שממון וביטול השגתו הראשונה לגמרי אז יוכל לבא לעליית השגה עמוקה ממנה לתרץ הקושיא, וכך הוא בעלי' לעומק השכל יותר כמ\"ש במ\"א ע\"פ והאיש משתאה<sup data-n=\"544\">15</sup> כו', וכמו רקבון הגרעין בארץ שמתבטל גסותו לגמרי אז יומשך בו כח הצומח להצמיחו מאין ליש בחידוש גמור שלא הי' זה כל זמן שלא נרקב כו' וכן בקליטת הזרע כידוע) וע\"כ אין התורה מתקיימת אלא במי שממית עצמו עלי' דוקא כמ\"ש אדם כי ימות באוהל<sup data-n=\"545\">16</sup> כו', וכן בענין עילוי הברכה ושפע בפרנסה וגדולה צ\"ל ע\"י בחי' ביטול כמו בנפשו יביא לחמו<sup data-n=\"546\">17</sup> וכה\"ג וד\"ל).\n[ב] <b>וע\"כ</b> מטעם זה מצינו שבכל עליי' מתחתון לעליון צ\"ל בחי' דבר מה מפסיק ומבדיל ביניהן שעל ידו יבא התחתון לביטול מציאותו לגמרי עד שישכח על מהותו ומדריגתו הראשונה לגמרי ואז יעלה למעלה במדריג' העליון, וכמו בעליות הנשמות מגעה\"ת לגעה\"ע<sup data-n=\"547\">18</sup> מצד שאין ערך ביניהם כלל יש דבר מפסיק ומבדיל ביניהם והוא בחי' נהר דינור דנגיד ונפיק מקדמוהי כו' שטובלים בו הנשמות בעלותם מגעה\"ת לגעה\"ע, וענין טבילה זאת היינו שע\"י טבילה זו ישכח ויבטל מהות התענוג האלקי הראשון שהי' לנשמה בגעה\"ת בהשגה הראשונה המצומצמת המאיר בה בג\"ע דעשי' כדי שלא יבלבל לבחי' התענוג העליון הגדול הרבה יותר בהשגה הנפלאה ונבדל בערך שבגעה\"ע דבריאה עד שהוא כערך הגשם לגבי הרוחני, כמו שצ\"ל ביטול ושכחה בנשמה בעלותה לג\"ע דעשי' מכל גשם דתענוג גופני שנדבק בה בעוה\"ז בלבושים שלה בהיותה בגוף עד שלא ישאר אף רושם בעלמא גם מחיזו דהאי עלמא, וא\"ל לא תוכל לקבל זיו עונג האלקי שבגעה\"ת, כגשם הגוף שמבלבל לרוחני' האלקי דנשמה עד שתופשט לגמרי ממנו, והוא ג\"כ נה\"ד שלפני הג\"ע בצאתו מגיהנם גם אחר בירור כל הרע שבתאוות הרעות כו', כך לפ\"ע זה יש בחי' נהר דינור עליון יותר שמפסיק בין געה\"ת לגעה\"ע שטובלים",[["544","15","<b>מה פשפשת. . אשתומם כשעה חדא. . במ\"א ע\"פ והאיש משתאה</b>: זח\"א א, ב. דניאל ד, טז [וחולין כא, א]. חיי\"ש כד, כא. סידור צא, ג ואילך."],["545","16","<b>אין התורה. . אדם כי ימות באוהל</b>: ראה גיטין נז, ב. זח\"ב קנח, ב. חוקת יט, יד."],["546","17","<b>בנפשו יביא לחמו</b>: בתפילת ר\"ה ויוהכ\"פ."],["547","18","<b>נהר דינור דנגיד ונפיק. . מגעה\"ת לגעה\"ע</b>: ע\"פ דניאל ז, יו\"ד. ראה זח\"א רא, א. זח\"ב ריא, ב. ועוד [וראה ס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תתכא-ב. דברים ח\"א ע' נט. וש\"נ לכ\"מ בדא\"ח]."]]],[1900420140,"בו הנשמות קודם בואם לפני ה' בגעה\"ע (ונעשה מזיעתן של חיות הקודש כידוע<sup data-n=\"548\">19</sup>). ודוגמתו יש בזה העולם כיסורים שממרקין עד שניתק ונתבטל מגשמיות תענוגי גופו כדי שיוכל לקבל עונג האלקי בתפלה ותורה בעילוי יותר הרבה מכמו שהי', וכן בתפלה עצמה הולך ועולה בעילוי אחר עילוי במדריגה גבוה ועמוקה יותר הכל ע\"י ביטול והזזה ממקומו ומהותו הראשון דוקא ע\"י מרירות ושפלות עצומה ביותר וכה\"ג עד שנעשה כאין ממש ובלעדי זה לא יוכל לעלות לעולם ולא נק' מהלך אלא עומד כו', כי זהו הכלל בכל מקום בכל ענין עליות מלמטה למעלה מתחתון לעליון הימנו שהוא העלי' ממהות למהות בעילוי שאינו בערך צ\"ל ביטול מהות הראשון לגמרי מכל וכל דוקא אז יוכל להתעלות בעליון הימנו (ואין ביטול המהות הראשון רק ע\"י בחי' גבורות דאש כנהר דינור הנ\"ל, ודוגמת נה\"ד התחתון שלפני געה\"ת (שהוא מתאסף מזיעתן של חיות כו') זהו כמו יסורים ומרירות ופיזור הנפש בטרדות הפרנסה עד שמתבטל מכל מהותו ומדריגתו כו' אח\"כ יעלה למעלה יותר, והוא ענין השפלות האמיתי' בלב נשבר קודם התפלה כנ\"ל), שזהו כמו דמיון רקבון הגרעין בארץ שנרקב הגסות וגשמיות ואז יוכל כח הרוחני שבחיטה לקבל מכח הצומח שתצמח מאין הרבה יותר כו' כמ\"ש במ\"א<sup data-n=\"549\">20</sup>, ואין זה רקבון הגשמיות לבד אלא זה בא מרקבון בכח הרוחניות שכלה כחה ונפסד צורתה עד שנכלל ונתבטל באין דכח הצומח כו', כך הוא בחי' רקבון דנפש האלקית במרירות ושפלות עצומה עד שנתבטל צורתה כו'). וכך יובן בעליות הנשמות מגעה\"ת לגעה\"ע שצ\"ל בנשמה ביטול מהות הראשון לגמרי ע\"י נה\"ד העליון שטובלת בו וא\"ל לא תוכל לקבל העונג העליון בעלותה מידי חודש ושבת להיותו נבדל בערך ממנו הרבה יותר כנ\"ל.\n[ג] <b>ויובן</b> דבר זה ע\"ד דוגמא מערך העונג שבמעשה לגבי העונג שבמדות, דודאי עונג זה שמתענג באיזה פעולה ומלאכה או כלי נאה אין לו ערך כלל לגבי עונג הרוחני ועליון ממנו שמתענג במדות שבלבו כמו אהבה בתענוגים שמתענג בהתפעלות האהבה הרוחני' שבלב או בניצוח ותפארת כו' שהוא עליון יותר וצ\"ל ביטול לגמרי בתענוג גשמי הראשון שבעשי' כשבא לכלל תענוג זה הרוחני כו', וכמו\"כ ערך תענוג שבמדות שבלב לגבי התענוג העליון הרוחני יותר שבהשגת שכל וחכמה ודעת כשמשיג חכמה ושכל נפלא שמתענג בו ברוחני' דקות השכל בעונג רוחני מאד, עד שתענוג שבמדות שבלב נק' גשמי לגביו וצ\"ל ביטול ושכחה לגמרי על תענוג הראשון שבלב",[["548","19","<b>ונעשה מזיעתן של חיות הקודש כידוע</b>: ראה חגיגה יג, סע\"ב."],["549","20","<b>כמו דמיון רקבון הגרעין. . כמ\"ש במ\"א</b>: ראה אגה\"ק ס\"ח (קיג, א). ס' מאמרי אדה\"ז עה\"ת ח\"א ע' כח. ח\"ב ע' תקצו. סה\"מ תקס\"ח ח\"א ע' קלו. סה\"מ ”אתהלך לאזניא\" ע' צו. קמח. תו\"א קיד, ד. לקו\"ת שה\"ש טז, א. ס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תקצח [ובהמ\"מ שם]."]]],[1900420141,"במדות כשבא לכלל התענוג שבשכל שלא יבלבל אותו כמו שהגשם מבלבל הרוחני כו', וכמו שאדם רואה בעצמו בעבודה שבלב ומוח בתפלה שכאשר בא לבחי' התפעלות התענוג שבהשגה אלקית העמוק' בהכרח שצ\"ל לביטול ושכחה לגמרי להפשיט א\"ע מהתפעלות תענוג מורגש שבלבו באהוי\"ר שלא יבלבל לתענוג עליון הרוחני שבשכל והשגה אלקי' כו'.\n<b>ועד\"ז</b> יובן ג' חלוקי מדריגות דג\"ע בג' עולמות דבי\"ע, דג\"ע דעשי' הוא העונג האלקי לנשמות דעשי' כערך העונג שמלובש במעשה לבד כנ\"ל, ועונג העליון יותר ממנו הוא עונג האלקי דיצירה בג\"ע דיצי' ששם מאיר אור האלקי דמל' במדות, כשרפים וחיות הקודש כו' שהתפעלותם בתענוג שבאוי\"ר שהוא רוחני יותר מעונג שבעשי', וכך ערך התענוג שבמדות דיצירה לגבי העונג העליון ממנו הרבה יותר והוא התענוג שבנשמות דבריאה בגעה\"ע בהשגות דחו\"ב בעומק ודקות גדול שאין התענוג שבמדות אוי\"ר ערוך לזה התענוג כלל כנ\"ל וצ\"ל בחי' ביטול ושכחה לגמרי על מהות התענוג הראשון שבמדות דג\"ע דיצירה כשעולים לג\"ע דבריאה כו' כנ\"ל, וכמ\"ש דאימא עילאה מקננא בכורסייא<sup data-n=\"550\">21</sup> שהוא בינה דאצי' שמלובש בבינה דמל' דאצילות מקננא בעולם הבריאה שנק' כורסייא כידוע, וז\"א שהוא בחי' מדות דאצי' ביצירה, ומל' בעשי' כו', שהן ג' מדריגות בנשמות דבי\"ע בג' מיני ג\"ע ובין כ\"א יש מסך ודבר מפסיק שמתבטלים שם בעלותם לעליון ממנו (וכמ\"ש בס' הבהיר שיש עמוד בגעה\"ת<sup data-n=\"551\">22</sup> שמתבטלי' שם לגמרי מכל וכל שהיו מתענגים בגעה\"ת ואז עולים בעמוד זה לגעה\"ע) וכמו למטה שצ\"ל לביטול התפעלו' שבלב כשבא לתענוג הרוחני שבהשגות דחו\"ב כנ\"ל) (ומה שצריך לב' דברים לנה\"ד ולעמוד זה כו', הענין הוא דבנה\"ד מתפשטים מגשמיות דתענוג ושכל הראשון ואז בעמוד זה יכולים לעלות לעליון שהוא ביטול שני שנעלה הרבה מביטול הראשון, עד\"מ העומד לפני שר קטן שגם שמתבטל מפניו, כשצריך לבא לפני שר העליון ממנו צריך שיבא לכלל ביטול המציאות יותר עד שביטול הראשון כיש יחשב, וא\"כ צ\"ל לב' מיני ביטול א' הפשטת יש ממהותו הראשון והב' ביטול יותר כשבא לגבי העליון, כמו העומד לפני פתח המלך שביטול זה אינו רק הפשטת גסותו וכשבא להיכל המלך שהולך ועולה במדריגות ליכנס פנימה אז מתבטל ביטול שני הרבה יותר כו') (וע\"כ כל עליות העולמות והמלאכים הוא ע\"י השיר ורינה דוקא כידוע לפי שהשיר ורינה הוא בחי' ההעלאה בביטול מהות מעמדו",[["550","21","<b>דאימא מקננא בכורסייא</b>: תקוני זהר ת\"ו (כג, א). ע\"ח שער סדר אבי\"ע (שמ\"ז) פ\"ג. שער דרושי אבי\"ע פי\"ג. תניא פל\"ט. ועוד."],["551","22","<b>בס' הבהיר שיש עמוד בגעה\"ת</b>: ראה זח\"א ריט, א. זח\"ב ריא, א. ומובא בכ\"מ בשם ס' הבהיר — ראה סה\"מ תקס\"ד ע' קג. תקס\"ה ע' שצט. תקס\"ח ח\"א ע' שפ. ח\"ב ע' תקנד. תו\"ח בראשית לד, ב. חיי\"ש קמ, ב. שמות ט, א. ועוד. [וליתא בס' הבהיר שלפנינו]. וראה ס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' תמ."]]],[1900420142,"הראשון שעי\"ז יעלה למעלה ליכלל במקורו, כמו המלאכים שעולין בשיר כענין שא' כל בעלי שיר יוצאים בשיר<sup data-n=\"552\">23</sup> כו' וכשבא מקרוב מתבטל ביטול שני כנ\"ל בעומד מקרוב להיכל המלך כמו בעמדם תרפנה כנפיהם<sup data-n=\"553\">24</sup> בביטול פנימי\nוהנה עד\"ז שעולים מגעה\"ת לגעה\"ע בביטול המהות מיש לאין, כך הוא עליות רבות בריבוי המדריגות זו למעלה מזו מעילה לעילה בעילוי אחר עילוי ברום המעלות עד אין קץ ושיעור כלל, והכל הוא בבחי' התענוג האלקי העליון שיש בו ריבוי מדריגות בבחי' א\"ס ממש גם למעלה מן האצי' (כמיכאל כהנא רבא מקריב<sup data-n=\"554\">25</sup> נשמות דבריאה במזבח דאצילות לאשתאבא בגופא דמלכא כו', וכך יש מלאכי' שנק' בהמות וחיות במרכבה דאצילות ונשמות דאצי' עד נשמות דפנימית או\"א וע\"י וא\"ק שעולים ליכלל בעילוי אחר עילוי בעצמות א\"ס שלפני הקו\"ח עד אין שיעור למעלה בעולם הא\"ס עצמו שנק' שעשועי המלך בעצמו כמ\"ש ילכו מחיל אל חיל כו' אפי' בעוה\"ב שנק' עדן כו'), דכמו שאא\"ס נמשך למטה עד אין תכלית בירידת המשכת העונג העליון למטה באצי' עד מל' דעשי' בג\"ע דעשי' שנתצמצם אור העונג האלקי כ\"כ בריבוי צמצומים מאד עד שיכול לקבל גם נשמה ומלאך דעשי' בסוף כל המדריגות דעולם העשי', כשיר מלאך דנפש הגלגלים ושיר נשמה אלקית שבגוף גשמי כו' שמתענג על הוי' בעונג אלקי ממש בכל שבת ועת הכושר כו', (עד שמפסולת התענוג האלקי שבג\"ע דעשי' נפל למטה ונעשה מקור להתהוות תענוגי' גשמיים חומרי' דעוה\"ז השפל שנפל בשבה\"כ בע' שרים שמשפיעים כל מיני תענוג גשמי בתאוות חומריות כו' (וכמו ששחק ר\"ע על כרך גדול של רומי<sup data-n=\"555\">26</sup> שהי' מלא תענוגי עוה\"ז וא' אם לעוברי רצונו כך כו' כפסולת החיצוני' דתענוג עוה\"ז שנפל למטה כ\"כ לעושי רצונו ששרשו בפנימי' מקור כל התענוגי' העליונים דאבי\"ע כמ\"ש כי עמך מקור חיים מקור כל התענוגים העליונים עאכו\"כ כו', וע\"כ א' גבי אחר מוטב דלידייני'<sup data-n=\"556\">27</sup> כו'), וכמו\"כ עילוי המדריגות בתענוג העליון למעלה עד אין שיעור ממש, ובין כל מדריגה מתחתון לעליון בהכרח שיש מחיצה מפסיק שעל ידו יבא התחתון לביטול",[["552","23","<b>כל בעלי שיר יוצאים בשיר</b>: שבת נא, ב. וראה (בשם הה\"מ ממעזריטש): לקו\"ת ברכה צח, א. סידור ערה, ד. ס' מאמרי אדה\"ז על מארז\"ל ע' קכ. ועד\"ז בסה\"מ תקס\"ח ח\"א ע' תקנג. ובהנסמן בהמ\"מ שם לתחילת המאמר [בח\"ב ע' תתנה טור ב]. ועוד."],["553","24","<b>בעמדם תרפנה כנפיהם</b>: יחזקאל א, כד-כה."],["554","25","<b>כמיכאל כה\"ר מקריב</b>: ראה חגיגה יב, ב (בגירסת העין יעקב). ובהנסמן עוד בארוכה בהמ\"מ בס' מאמרי אדהאמ\"צ ויקרא ח\"א ס\"ע א ואילך."],["555","26","<b>ששחק ר\"ע על כרך גדול של רומי</b>: סוף מכות."],["556","27","<b>כי עמך מקו\"ח. . מוטב דלידייני'</b>: תהלים לו, יו\"ד. חגיגה טו, ב [וראה בהנסמן ע\"ז לעיל בד\"ה משמח חו\"כ, קרוב לתחילתו]."]]],[1900420143,"המציאות ממהותו הראשון לגמרי מכל וכל וא\"ל לא יוכל לעלות לעליון כנ\"ל, וכידוע שיש מסך מפסיק בין עשי' ליצירה ובין יצירה לבריאה ומבריאה לאצי' ובכל ע\"ש עולים מלאכים שבעשי' ליצירה ומיצירה לבריאה ומבריאה לאצי' באמצעות הביטול דוקא, כידוע בענין ג\"פ הבו<sup data-n=\"557\">28</sup> כו' שהן ג' מיני מלאכים דבי\"ע עד בהדרת קודש גם במלאכים דאצי' למעלה עד אין שיעור כנ\"ל וד\"ל.\n[ד] <b>ובזה</b> יובן ענין עסק עבודת הנשמות אחרי הסתלקותם מעוה\"ז, דודאי א\"א לומר שהן יושבין בג\"ע ונהנין מזיו כו' תמיד במדריגה א' כמלאכים שהרי הנשמות נק' מהלכי' ולא עומדי'<sup data-n=\"558\">29</sup>, וק\"ו הוא ממה שאנו רואים בנשמות שבגופי' שנק' מהלכים שהולכים בעילוי אחר עילוי במדרג' בכל יום ויום בעבודתם בתפלה ותומ\"צ כמ\"ש באברהם הלוך ונסוע מדרגא לדרגא כו' כמ\"ש בזהר<sup data-n=\"559\">30</sup>, כ\"ש אחרי הסתלקות הנשמות במקורם במל' דאצי' שצרורים בצרור החיים העליוני' שבודאי הולכים ועולים בעילוי המדריגות בתמידות בלי שיעור כלל כמ\"ש ילכו מחיל אל חיל כו', וענין העליות הללו הוא שמשיגים בעצמות אוא\"ס בהשגות עמוקות ונפלאות זו למעלה מזו ובבחי' ביטול מהשגה הראשונה לגמרי כשעולה למעלה בעומק ההשגה האלקי' יותר וכך עולה בלי שיעור. ויובן זה ממה שאו' משובח ומפואר עדי עד כו' וכן או' וקדושי' בכל יום יהללוך סלה וכל סלה נצח<sup data-n=\"560\">31</sup> כו' הוא בלי שיעור והפסק כלל, וכל שמגיעים למעלה יותר הוא ית' יותר נפלא ונעלם מהשגתם כענין מה פשפשת<sup data-n=\"561\">32</sup> כו' לפי שאין שיעור לעליות המדריגות להשיג באמיתי' עצמות אור א\"ס וע\"כ ת\"ח אין להם מנוחה בעליות הללו אפי' בעוה\"ב, וממילא מובן שאין קץ ושיעור לעילוי מדריגות התענוג העליון זו למעלה מזו שהולכים ועולים מעונג לעונג בשעשועי' העליונים בעילוי תענוג נבדל בערך מתענוג הראשון לגמרי, כמו עליי' הנשמה מתענוג שבג\"ע דעשי' לתענוג העליון דג\"ע דבריאה ויצירה כנ\"ל וד\"ל. וראי' לדבר זה הנה יש להכריח כן מנשמות הגבוהות יותר מכולם כמו נשמת משה רבן של כל הנביאים שלא קם עוד נביא כמשה<sup data-n=\"562\">33</sup> שידעו ה' פא\"פ כו' ובכל יום ויום בכל ימי חיותו שהי' נשמתו בגופו ודאי הי' הולך ועולה בעילוי המדריגה בהשגות ותענוג העליון בפנימי' העונג דח\"ע דתורה עד המדריגה העליונה יותר שהן נש\"ב כו' שלא הי' כמוהו בנביאים וצדיקים הגדולים שאחריו, וא\"כ ודאי כ\"ש וק\"ו הוא שאחרי התפשטות נשמתו מגופו",[["557","28","<b>כידוע בענין ג\"פ הבו</b>: תהלים כט, א-ב. ראה פע\"ח שער השבת (שי\"ח) פ\"ח. ס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תתפא. וש\"נ."],["558","29","<b>הנשמות נק' מהלכי' ולא עומדי'</b>: ראה תו\"א ל, סע\"א ואילך. ובכ\"מ."],["559","30","<b>באברהם הלוך ונסוע מדרגא לדרגא כו' כמ\"ש בזהר</b>: לך לך יב, ט. זח\"א פד, א."],["560","31","<b>וכל סלה נצח</b>: עירובין נה, א."],["561","32","<b>מה פשפשת</b>: זח\"א בתחילתו."],["562","33","<b>שלא קם עוד נביא כמשה</b>: ע\"פ ברכה לד, יו\"ד."]]],[1900420144,"ועלה למעלה בשרשו בפנימית ח\"ע דאצי' מקור חוצבו הראשון א\"א לומר שבעלותו שם לא השיג יותר מהשגתו וידיעתו הראשונה שידע והשיג וראה בהיות נשמתו בגופו בעוה\"ז שהלך ועלה במדריגות כמה שנים רבות כו', אלא ודאי בהכרח לומר שמיד שעלה במקור חוצבו עוסק בפנימית הח\"ע להתענג על ה' בעילוי המדריגה יותר עליונה הרבה מהשגתו ועלייתו שהי' לו בגופו בערך נבדל הרבה יותר מהבדלת הערך מעלי' שמגעה\"ת לגעה\"ע כנ\"ל, וא\"כ זה שנים רבות מפטירתו מעוה\"ז הרי הולך ועולה נשמתו בכל יום ממדריגה למדריגה בעונג והשגה אלקית באין שיעור וקץ לעליות הללו, והכל בפנימי' התענוג דעצמות אוא\"ס בבחי' שעשועי המלך בעצמו דוקא בבחי' עומק רום להיותו בבחי' א\"ס למעלה כנ\"ל בענין יהללוך סלה בלי הפסק כלל. וכך הוא בכל נשמות הצדיקים הגדולים כמוהו כמו נשמת האבות אברהם יצחק ויעקב שהולכים ועולים מחיל אל חיל ממדריגה למדריג' עליונה יותר בערך נבדל מעלייתם בחייהם בעוה\"ז כנ\"ל בנשמת משה. וזהו וקדושים שהן נשמות שצרורים בצרור החיים למעלה באצי' ולמעלה יהללוך סלה בכל יום בעילוי יותר (וגם שנשמות משה ואהרן והאבות ומשיח יושבים בהיכלות דג\"ע דבריאה, זהו בחי' נפש שלהם ועולה גם היא ברוח באצי' ורוח בנשמה עד בחי' יחידה שלהם עולה בעצמות א\"ס עד אין שיעור למעלה כו' וכל היחו\"ע שבעליות שלהם יתגלו למטה בתחה\"מ שיבאו בגופים קדושים למטה בעונג מורגש כו' כמ\"ש במ\"א<sup data-n=\"563\">34</sup> וד\"ל).\n[ה] <b>והנה</b> מעתה י\"ל שרש ענין העוה\"ב שהוא העדן שנאמר בו עין לא ראתה אלקים זולתך לבד כו' דאע\"פ דברא גן בעדן מקדם, זהו רק הארה בעלמא שמתפשטת מעדן עילאה לנשמות ע\"י נהר שיוצא מעדן ע\"י דבר מפסיק כו' שעל ידו יתבטלו במציאות כנ\"ל, אבל בעוה\"ב כתי' ולא יכנף עוד מוריך<sup data-n=\"564\">35</sup> כו' שיתגלה מעצמות התענוג הפשוט שהוא בחי' שעשועי המלך בעצמותו ממש כמו שהוא בעצם הרוממות שהנשמות הולכים ועולין לשם ולא ישיגוהו, כנ\"ל דכל מה שעולין יותר יותר נפלא מהם ובאים יותר לביטול ההשגה לפי שאין שיעור לרוממות דא\"ס בעילוי התענוג והחכמה כו' (כמ\"ש במ\"א בפי' עדי עד ענין עד כאן ולא עד בכלל<sup data-n=\"565\">36</sup> כלומר כל מה שתשיג לא הגעת לחצי השגה להשיג לאמיתי' עצמותו כו' וע\"כ עלייתם בלי שיעור ולעולם לא יגיעו לאמיתתו ממש כו') (וכמא' דאפי' אור צח<sup data-n=\"566\">37</sup> כו' אוכם הוא לגבי עה\"ע כו' משום שנק' סתימא דכל סתימין דלית מחשבה תפיסא בי' כלל גם",[["563","34","<b>וכל היחו\"ע שבעליות שלהם. . בתחה\"מ. . בעונג מורגש כו' כמ\"ש במ\"א</b>: ראה דרך חיים שער התפילה נא, ג-ד. ועוד. וראה גם לעיל ח\"א ע' כ ובהמ\"מ שם."],["564","35","<b>ולא יכנף עוד מוריך</b>: ישעי' ל, כ."],["565","36","<b>כמ\"ש במ\"א בפי' עדי עד. . ולא עד בכלל</b>: ראה תו\"ח פקודי תרנח, א."],["566","37","<b>דאפי' אור צח</b>: תקוני זהר ת\"ע (קלה, ב)."]]],[1900420145,"בריבוי העליות עד אין שיעור גם בעליות נשמות הגבוהות כמשה ואבות שיהללוך סלה כנ\"ל). וזהו עין לא ראתה גם עתה בעליות נשמות הצדיקים הגדולים כמשה ואבות רק אלקים זולתך לבד דלא ידע לי' בר איהו בלחודוהי<sup data-n=\"567\">38</sup> כו', ויתגלה כמו שהוא באמיתי' עצמותו ממש בעוה\"ב שנק' עדן העצמי למחכה לו דוקא (כמשי\"ת), והוא ע\"י מעשה המצות בעוה\"ז דוקא שמזה יבא גילוי אור העצמות דשעשועי' העליוני' שהוא העדן לנשמות שעסקו במצות בעוה\"ז כמ\"ש כל ישראל יש להם חלק לעוה\"ב<sup data-n=\"568\">39</sup> מפני שכולם צדיקים במצות בפו\"מ דוקא, והטעם הוא כידוע שבכל מצוה ומצוה יש בה התלבשות מאור פנימי' רצה\"ע שבו מלובש מפנימית התענוג הפשוט שבשעשועי המלך בעצמו ממש, כמ\"ש לכל תכלה ראיתי קץ<sup data-n=\"569\">40</sup> פי' תכלה ענין התענוג הנפלא שתכלה הנפש אליו כו' ואמנם יש קץ וגבול לכל עונג שברצון וחכמה רק ברצון דמצות רחבה מצותך מאד שהתענוג הפשוט ועצמי שבה מתרחב מעצמות השעשועי' שבפנימי' ועצמי' דא\"ס בלי קץ וגבול כלל מה שלא הי' ביכולת הנשמות הגבוהות להשיגו גם שיעלו עד אין שיעור אחר הסתלקותם כנ\"ל רק באמצעות המצות יורד אור העצמות שבהן למטה ומתגלה לכל נשמה ונשמה בבחי' עונג מורגש בעוה\"ב לכאו\"א כפי מדרגתו בבחי' גילוי או\"פ בכלי כמ\"ש להנחיל אוהבי יש, ומאחר שנתגלה למטה כמו שהוא למעלה ממש יופסקו העליות דנשמות למעלה, וכמ\"ש הנה אלקינו זה<sup data-n=\"570\">41</sup> ממש (ומ\"ש דת\"ח אין להם מנוחה אפי' בעוה\"ב<sup data-n=\"571\">42</sup> אע\"פ שאז נק' מנוחה לחיי העולמים מטעם הנ\"ל, היינו לפי שגם העוה\"ב אינו רק קצת הארה מאמיתי' אור העצמות דשעשועי המלך כו' שהרי א' ביו\"ד נברא העוה\"ב שאינו רק יו\"ד דשם ס\"ג שבטהירו עילאה<sup data-n=\"572\">43</sup> כו', וכמ\"ש במ\"א במ\"ש וקווי ה' יחליפו כח יעלו אבר כנשרים שיעשה כנפיים<sup data-n=\"573\">44</sup> לנשמות הצדיקים ככנפי נשרים וטסים למעלה ע\"פ המים עליונים כו' שזהו למעלה מחיי העוה\"ב דעדן שהוא רק יו\"ד דחכמה דתורה שנק' מים עליונים כו', שהעוה\"ב אף שנק' יום שכולו שבת בחי' מנוחה העצמי' כו' זהו רק לגבי שמיטה זו דו' אלפין שנין, וידוע שיש ז' שמטות ויובלות עד נ' אלפים יובלות<sup data-n=\"574\">45</sup>",[["567","38","<b>דלא ידע לי' בר איהו בלחודוהי</b>: זח\"ג רפח, א. וראה שם קמ, ב. קכט, ב. קנט, א."],["568","39","<b>כל ישראל יש להם חלק לעוה\"ב</b>: סנהדרין צ, א."],["569","40","<b>לכל תכלה ראיתי קץ</b>: תהלים קיט, צו."],["570","41","<b>להנחיל אוהבי יש. . הנה אלקינו זה</b>: משלי ח, כא. ישעי' כה, ט. וראה סוף מס' עוקצין וסוף מס' תענית."],["571","42","<b>דת\"ח אין להם מנוחה אפי' בעוה\"ב</b>: ראה לעיל פיסקא ”אך הנה ידוע\" (קרוב לתחילת המאמר). וש\"נ."],["572","43","<b>יו\"ד דשם ס\"ג שבטה\"ע</b>: ראה גם ס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תשכה. במדבר ח\"ה ע' א'תשנג (וע\"ש ע' א'תשמח), ובהמ\"מ שם."],["573","44","<b>וכמ\"ש במ\"א במ\"ש וקווי ה' יחליפו כח. . שיעשה כנפיים</b>: ישעי' מ, לא. סנהדרין צב, ב. ס' מאמרי אדהאמ\"צ בראשית ע' עז ואילך, קמט ואילך. תו\"ח בראשית ד, ג."],["574","45","<b>וידוע שיש ז' שמטות ויובלו' עד נ' אלפים יובלות</b>: ראה סה\"מ תקס\"ב ח\"ב ע' תסב (ובהמ\"מ שם). סה\"מ תקס\"ט ע' פג (מס' התמונה). ס' מאמרי אדהאמ\"צ דברים ח\"א ע' רסח (ובהמ\"מ). עט\"ר סז, ב. ד\"ה אל תצר מכ\"ק אדהאמ\"צ (כפ\"ח תשל\"ו) ע' 52 (בהמ\"מ). אוה\"ת ר\"ה ס\"ע א'רפח (ע\"ש בשם הבחיי פ' בהר). סה\"מ תרע\"ח ריש ע' דש (מס' התמונה, ע\"ש)."]]],[1900420146,"כו', וע\"כ א' שאין להם מנוחה אפי' בעוה\"ב כמ\"ש ילכו מחיל כו' (ולפ\"ז זהו יהללוך סלה בנצחי' דא\"ס שאין לו שיעור למעלה בעליות הנשמות הגבוהות כמשה והאבות גם עכשיו וא\"כ לא יובן מ\"ש עין לא ראתה כו' דקאי גם בנשמות הקדושים כמשה ואבות, אלא הנכון כדלעיל וד\"ל).\n<b>וז\"ש</b> בעדן עין לא ראתה כו' לפי שהוא בחי' גילוי התענוג הפשוט שבמצות שזהו עצמות השעשועי' העליוני' שלא ידע והשיג עין כל אפי' משה ומשיח דכל רז לא אניס לי' ונק' פלא יועץ כו' וכתי' בי' ישכיל עבדי<sup data-n=\"575\">46</sup> במקור הח\"ע וגבה מאד למעלה גם ממשה ואבות, מ\"מ גם הוא לא ראה לעדן הזה שהוא גילוי אמיתי' מהו\"ע ית', שהרי גם אור צח כו' שנק' פלא א' עושה פלא<sup data-n=\"576\">47</sup> פלאות חכ'<sup data-n=\"577\">48</sup> כו' ואוכם הוא לגבי עה\"ע עצמו דלמחת\"ב כלל, לפי שהמצות הן עצם הרצון והתענוג הפשוט שלמעלה גם מטעם ושכל כמוס לרצון כי אין טעם כלל לרצון<sup data-n=\"578\">49</sup> אפי' טעם כמוס ונק' כתר שבכתר (והעוה\"ב ג\"כ אינו רק גילוי אור זה הפשוט בצמצום לנשמות כענין ש\"י עולמות ות' עלמין דכסופין דנהרין לצדיקיי'<sup data-n=\"579\">50</sup> כו'), רק אלקי' זולתך לבד לפי שהוא אור עצמותו ממש שהוא בחי' א\"ס ממש וד\"ל.\n[ו] <b>ועכ\"ז</b> א' יעשה למחכה לו, דגם שעין לא ראתה לעדן זה עדיין רק זולתך בעצמך דוקא כנ\"ל, מ\"מ יעשה עדן זה לבא בגילוי גמור למחכה לו דוקא. והפי' הפשוט הוא שיעשה וימשיך לבחי' אור התענוג הפשוט הזה למי שמחכה לו שמצפה וממתין אליו, כמו אם יתמהמה חכה לו ימתין ויצפה שענינו שיקוה לו שיבא אליו, כמ\"ש הנה אלקינו זה קוינו לו כו' וכמו נפשנו חכתה וכן וקווי ה' כו' וכה\"ג. אך בזהר מפרש למחכה לו למאן דדייק<sup data-n=\"580\">51</sup> מילין דחכמתא כו' שהוא מילין דאורייתא מדייק אותם בעיון גדול, וגם זה יתכן לפי פי' הפשוט דמחכה זו לשון עיכוב והמתנה שממתין ומצפה לדבר כנ\"ל, אך",[["575","46","<b>דכל רז לא אניס לי'. . פלא יועץ. . ישכיל עבדי</b>: ע\"פ דניאל ד, ז. ישעי' ט, ה. נב, יג [וראה תרגום יונתן וילקוט שמעוני עה\"פ שם]."],["576","47","<b>עושה פלא</b>: בשלח טו, יא, ותהלים עז, טו."],["577","48","<b>פלאות חכ'</b>: ראה גם ס' מאמרי אדהאמ\"צ: בראשית ע' שנ. תלט. שמות ח\"א ע' לד. ח\"ב ע' תנב. תקפד. דברים ח\"ב ע' תקפט. ח\"ג ע' תשפה-ו. א'קמב. נ\"ך ע' קנו."],["578","49","<b>כי אין טעם כלל לרצון</b>: יונת אלם פ\"ב [כן מציין בהערת כ\"ק אדמו\"ר שליט\"א בסה\"מ קונטרסים ח\"ג ע' לד]."],["579","50","<b>כענין ש\"י עולמות ות' עלמין דכסופין דנהרין לצדיקיי'</b>: סוף מס' עוקצין. זח\"א קכג, ב. זח\"ג קכח, ב. רפח, א. וראה קהלת יעקב מע' ”ת' עלמין דכסופא\"."],["580","51","<b>אם יתמהמה חכה לו. . הנה אלקינו. . נפשנו חכתה. . למחכה לו למאן דדייק</b>: חבקוק ב, ג. ישעי' כה, ט. תהלים לג, כ. ישעי' סד, ג. זח\"א קל, ב. וראה גם המשך תרס\"ו ע' עח."]]],[1900420147,"כונת הזהר במחכה זה שמפרשו על הדיוק במילין דחכ' דאורייתא שזהו כמו איוב חכה לו בדברים שהוא ג\"כ ענין המתנה ועיכוב והעמדה שעומד וממתין ושותק עד שיכלה דברו, להיות שעיקר ענין העיון וההגיון בתורה הוא רק ענין עיכוב והעמדה והמתנה על הדבר עד שבא להשגת אמיתתו, כמו שאנו רואים בחוש בכל מי שלומד תורה בעיון גדול שהוא מעיין בכל כח שכלו ובינתו להבין ולהשיג אמיתית הדין של הלכה באיזה דבר מד\"ת שיבא דבר זה ע\"י יגיעה רבה במוחו שמייגע כלי מוחו מאד בעיון גדול עד שיעמוד על אמיתי' הדבר, ולא שיודע ומשיג הדבר בהשקפה ראשונה אדרבה שבהשקפה ראשונה ושני' עד כמה פעמים לא יכול להבין ולהשיג וקשה לו הדבר ביותר עד שנותן כל כח השכל וההשגה בעיון עמוק ביגיעה רבה שנק' יגיעת המוח זמן רב, שזהו ענין ההעמדה ועיכוב שעומד ומתעכב במוחו בהשתוממו' זמן רב על עומק הדבר איך הוא אמיתתו שלא נודע לו כלל, וכל שמעמיק יותר יותר יפלא הדבר ממנו לאמיתתו ויעמוד ויתעכב עליו עוד ה\"ז נק' יגיעה ונק' עמל תורה כידוע, זהו הנק' דיוק שמדייק במילין דחכ' כלומר שיוקשה לו וידייק מאד בו לעיין בו הרבה בעיכוב והעמדה על הדבר זמן רב עד שיבא על אמיתתו שזהו מעלה יתירה שיגיע לעומק אמיתית הדבר הרבה יותר מכמו שהי' מבינו בהשקפה ראשונה אע\"פ שכלי שכלו חריף ויכול להבין מיד לא יבא לעומק האמיתי ממקור החכמה כ\"א ע\"י יגיעה בעיון רב דוקא שע\"ז א' יגעתי ולא מצאתי אל תאמין (שע\"י החכמה דבחי' או\"י הבאה מלמעלה למטה שלא ע\"י עיון ויגיעה כמ\"ש והחכמה מאין תמצא<sup data-n=\"581\">52</sup> יש שיעור ומדה עד כמה יכול להשיג וכלה כחו להשיג בעמוק ממנו הרבה רק כפי ערך הכח שלו שבמקורו בכח המשכיל שלו לבד, אבל ע\"י יגיעה שדוחק ומייגע כלי המוח (קרום התחתון שחופה על המוח) מלמטה למעלה שיעמוד על הדבר ויוקשה לו הרבה זמן עי\"ז הוא שיבא להעמקת הדבר לעמוד על עומק אחר עומק למעלה מכח שכלו בכח המשכיל עד אין שיעור למעלה, שזה בחי' כח דאו\"ח שעולה למעלה ממקור החכמה בכח המשכיל להשכיל בעומק עד אין שיעור ומדה כלל, כמ\"ש במ\"א בענין הפלפול<sup data-n=\"582\">53</sup> שעולה למעלה מכח החכמה שמאין תמצא, והוא בחי' כתר שבכתר שלמעלה מאין דכתר דחכמה כמו שהוא במקורה במדה כו', וזהו רק ע\"י בחי' עוצם הביטול ועומק ההשתוממו' במוח שנעשה ביגיעת המוח כשבא לעיון גדול והעמקה יתירה, שזהו בחי' העלאת מ\"ן מלמטה למעלה להיות בבחי' אין ממש להמשיך תוס' כח רב במקור השכל שנק' משכיל כו', וזהו פי' הכאת הסלע במטה משה כו', והוא מה שתלמוד בבלי נק'",[["581","52","<b>יגעתי ולא מצאתי אל תאמין. . והחכ' מאין תמצא</b>: מגילה ו, ב. איוב כח, יב."],["582","53","<b>במ\"א בענין הפלפול</b>: ראה ס' מאמרי אדה\"ז עה\"ת ח\"א ע' רכה. סה\"מ תקס\"ז ע' קלה. ס' מאמרי אדהאמ\"צ: בראשית ע' קנ. וע' עדר. ויקרא ח\"א ע' קיב. במדבר ח\"ד ע' א'תכג. דברים ח\"ד ע' א'תעד. שערי אורה כד, א. עטרת ראש מט, סע\"א ואילך. וראה גם המשך תרס\"ו ע' פו."]]],[1900420148,"מחשכים<sup data-n=\"583\">54</sup> כו' שמחושך יהי' אור שכל שמקשה קושיות והעלמות יותר ויותר יאיר האור מן ההעלם והעומק אחר עומק, כמו במשיח שא' ישכיל עבדי כו' בהעלם אחר העלם דרזא דרזין דסודות התורה יתגלו לו ונק' חכם חרשים<sup data-n=\"584\">55</sup> כו', והוא מצד ההעלאה דבחי' או\"ח בבירורים דשם ב\"ן כמו העיון של יגיעת השכל בתורה שנק' עמל תורה וז\"ש אשרי מי שעמלו בתורה<sup data-n=\"585\">56</sup> כו' וד\"ל.\n<b>וזהו</b> למחכה לו למאן דדייק מילין דחכ' דאורייתא שנק' עמל תורה<sup data-n=\"586\">57</sup>, כמו עמל מלאכה בשדה שטורח הרבה ואינו מוצא כרצונו זמן רב עד שיצא הדבר כתיקונו שאז יראה הצלחה רבה בטוב מלאכתו כו' עד שיכול לבא להון ועושר גדול יותר ממדתו הרבה כו' כמ\"ש עובד אדמתו ישבע לחם<sup data-n=\"587\">58</sup> בלי גבול, וכך הוא בעיון הטוב ביגיעה רבה בד\"ת בכל כח שכלו לטרוח ולייגע עצמו הרבה לעמוד על הדבר זמן רב עד שישיג אמיתתו יבא לעומק האמיתי בעומק אחר עומק וכל העלם יגלה לו להיותו מגיע בהעלאה דיגיעה זו למעלה מעלה להוסיף כח יתירה במקור השכל שהוא בחי' התענוג הפשוט העצמי שלמעלה ממקור השכל, דמה שהחכמה מאין תמצא אינו בא רק מבחי' אור הרצון ותענוג שמתצמצם ונמשך בכח המשכיל להוליד ולהשכיל כל שכל מן ההעלם לגילוי במדה ושיעור כו' כנ\"ל וד\"ל. וזהו שהעדן שהוא התענוג הפשוט העצמי שנק' שעשועי המלך בעצמו מקור כל התענוגים שנמשכים במדה וצמצום בחכ' ומדות וגם ברצון כו', יעשה למחכה לו דוקא שהוא מאן דמדייק במילין דחכ' דתו', דאע\"פ שחכמה דתורה עצמו מאין דכתר תמצא בקו המדה כמ\"ש והחכמה מאין כו', אבל יגיעה זאת שמדייק ומקשה א\"ע על הדבר מאד שזהו העלאה לעורר לעצמות העדן להוסיף כח רב להשיג בהעלם דהעלם דסדכ\"ס דלית מחת\"ב כלל שעין לא ראתה אפי' חכ' הקדומה, וגם משיח שא' בו ישכיל עבדי כו' זה בא לו ע\"י היגיעה דתושבע\"פ בדיוק ופלפול הנק' עמל תורה כנ\"ל וד\"ל.\n[ז] <b>אך</b> עדיין אין זה מובן דא\"כ אין העדן דעוה\"ב רק לנשמות שעסקו בפלפול ודיוק דחכמה דתורה שנק' עמל תורה שז\"ש למחכה לו כנ\"ל, ובאמת הרי א' דכל ישראל יש להם עוה\"ב<sup data-n=\"588\">59</sup> מצד קיום המצות בפו\"מ לבד גם ע\"ה ופשוטי הערך שלא ידעו בפלפול ועיון דתורה כלל. ועוד י\"ל מ\"ש דעין לא ראתה דמשמע אפי' משיח שנאמר בו ישכיל כו', והלא נאמר בו הקים עול",[["583","54","<b>מה שתלמוד בבלי נק' מחשכים</b>: סנהד' כד, א."],["584","55","<b>ונק' חכם חרשים</b>: ישעי' ג, ג."],["585","56","<b>אשרי מי שעמלו בתורה</b>: ברכות יז, א: אשרי מי שגדל בתורה ועמלו בתורה כו'. וראה גם סה\"מ תקס\"ב ח\"ב ס\"ע תקמז."],["586","57","<b>שנק' עמל תורה</b>: סנהד' צט, ב."],["587","58","<b>עובד אדמתו ישבע לחם</b>: משלי יב, יא. כח, יט."],["588","59","<b>דכל ישראל יש להם עוה\"ב</b>: סנהד' צ, א."]]],[1900420149,"עולה של תורה<sup data-n=\"589\">60</sup> שנק' עמל תו' והוא שלימות הבירור שבח\"ת דתושבע\"פ דוקא כנ\"ל. ועוד דלמה עין לא ראתה גם צדיקים הגדולים מכולם כמשה שעסק בעמל תורה שעיקר תושבע\"פ נמסר למשה כמ\"ש תורה ציוה לנו משה דוקא כידוע בענין וגם דלה דלה לנו<sup data-n=\"590\">61</sup> כו' וכל חכמי ישראל בכל דור עוסקים בעיון ועמל תורה בחידושי הלכות עד אין שיעור והכל ממשה עד דכל מה שתלמיד ותיק עתיד לחדש<sup data-n=\"591\">62</sup> ניתן למשה כו'. ועוד י\"ל דהלא ידוע ומבואר למעלה דעיקר העוה\"ב שהוא העדן אינו בא רק מן המצות מעשיות שהוא עצם הרצון ועצם התענוג הפשוט שנק' שעשועי' העצמיי' שהוא למעלה הרבה גם מבחי' טעם הכמוס לרצה\"ע הפשוט דאין טעם לרצון כלל כנ\"ל, וא\"כ גם מי שמדייק במילין דחכמה ביגיעה רבה העלאה זו לא יגיע כלל לבחי' עצמות התענוג והרצון הפשוט שבמצות עצמן, ולמה א' למחכה לו בדיוק דחכמה יתגלה לו העדן דעוה\"ב כו', הלא גם בכל יגיעה רבה ויתירה במילין דחכמה דתורה לא יגיע רק לעומק אחר עומק דהעלם החכמה לבד וכמו משיח שא' בו ישכיל עבדי כו' דכל רז לא אניס לי' כו' וכה\"ג אבל לא יגיע לעצמות התענוג הפשוט שבעוה\"ב שלמעלה גם ממקור הנעלם הראשון דח\"ע דתורה, ואע\"פ שא' בתורה ואהי' אצלו אמון שעשועים<sup data-n=\"592\">63</sup> כו', אין לזה ערך לגבי בחי' שעשועי' העצמיי' שבעצמות א\"ס ממש שלמעלה משעשועי' ותענוג דחכמה דתורה הרבה שלא יגיע לזה רק ע\"י מעשה המצוה בפו\"מ דוקא ששרשם בבחי' כתר שבכתר שלמעלה הרבה מאין דחכמה דתורה כנ\"ל (שהוא תר\"ך עמודי אור<sup data-n=\"593\">64</sup> כו', ומ\"ש להנחיל אוהבי יש ואוצרותיהם אמלא זהו בחצי כתר שלמטה שהוא ש\"י בהשגת י\"ש דחכמה ב\"פ קנה<sup data-n=\"594\">65</sup> שנק' פרס ענין פרוסה כו' שהן ב' אוצרות דח\"ע וח\"ת כו').\n<b>אך</b> הנה שרש הענין הוא דאע\"פ שבאמת עיקר העוה\"ב זהו בחי' שעשועי' דרצון ותענוג העצמי' דא\"ס שבמצות שלמעלה מעונג ושעשועי' שבחכמה הקדומה דתורה לפי שאין טעם לרצון כלל אפי' טעם כמוס מאד כנ\"ל, עכ\"ז א' בעדן יעשה למחכה לו דוקא למי שמדייק במילין דחכמה דתורה דוקא כנ\"ל. ויש להקדים לזה ב' דברים. א' שבעוה\"ב עצמו יש ב' מדריגות, הא' גילוי שעשועי' העצמי' שבעצם פנימית הרצון והתענוג שבמעשה המצות מצד המעשה דמצוה עצמה בפו\"מ שלמעלה הרבה מבחי' טעם הכמוס שבה בח\"ע",[["589","60","<b>הקים עול עולה של תורה</b>: ראה במדב\"ר פמ\"ח, כא. מדרש שמואל פכ\"ט. תדא\"ר רפ\"ב."],["590","61","<b>תורה ציוה. . כידוע בענין וגם דלה דלה לנו</b>: ברכה לג, ד. שמות ב, יט. וראה גם שערי אורה נד, ב: ניתנה התורה על ידו כמ\"ש וגם דלה דלה לנו דלה מים דאורייתא."],["591","62","<b>דכל מה שתלמיד ותיק עתיד לחדש</b>: ראה מגילה יט, ב. ירושלמי פאה פ\"ב ה\"ד. ובהנסמן עוד בלקו\"ש חי\"ט ע' 252."],["592","63","<b>ואהי' אצלו אמון שעשועים</b>: משלי ח, ל."],["593","64","<b>תר\"ך עמודי אור</b>: ראה פרדס שער מהות והנהגה (ש\"ח) פ\"ג. ובכ\"מ."],["594","65","<b>להנחיל אוהבי יש. . ב\"פ קנה</b>: משלי ח, כא. לעיל ח\"א ע' רכח [וש\"נ לכהאריז\"ל ולעוד כ\"מ בדא\"ח]."]]],[1900420150,"דתורה הקדומה כו' שנק' כתר שבכתר, והב' למעלה גם מגילוי שעשועי' עצמי' הללו שבעצמו' הרצון דמצות והוא בבחי' מקיף והעלם דתענוג ושעשועי' שאמר ונעשה רצונו במצות הללו שלמעלה משכר המצות שבעוה\"ב שלא יוכל לבא בגילוי התענוג ושעשועי' גם בעוה\"ב (שחפשי מן המצות כמ\"ש יצא חנם בלא מצות<sup data-n=\"595\">66</sup>, והוא מ\"ש דת\"ח אין להם מנוחה אפי' בעוה\"ב (כמשי\"ת), וכמ\"ש במ\"א באריכות בדרוש דיאר ה' פניו<sup data-n=\"596\">67</sup> לעוה\"ב וישא ה' פניו למעלה מחיי העוה\"ב שז\"ש וקווי ה' כו' שיהיו שטין ע\"פ המים כו' בעליות עד אין שיעור למעלה כו'). וענין הב' הוא כמ\"ש למחכה לו מאן דדייק כו' שיש בזה ב' דברים, א' ענין ההעלאה דבחי' או\"ח למעלה ע\"י בחי' הביטול והשממון שביגיעה רבה זו בכלות כחו בכל עומק עיון השכל עד שנעשה בחי' אין ממש כנ\"ל, והב' בחי' ההמשכה שנעשה עי\"ז מההעלם דח\"ס בהעלם אחר העלם שבא מלמעלה ממקור כח השכל דוקא שעי\"ז יוכל לתקן דבר מה בחכמתו, כמו מי שחכמתו עמדה לו לתקן דבר המקולקל או להרויח הון רב בפרנסה ומלאכה, שזהו שנק' תורתו אומנתו כו' שע\"ז א' והחכמה תחי' בעלי' דחכ' כו' (כמ\"ש במ\"א בדרוש דתורה ציוה<sup data-n=\"597\">68</sup> לנו כו'), כמו בתושבע\"פ שבח\"ת דוקא אתברירו בין טמא וטהור לתכלית האמת שמתקן דבר המקולקל שנפל בחושך דק\"נ להסתיר האור כו' ונהפך כל העלם דחושך לאור, שע\"י הפלפול יכוין לידע אמיתי' האור דרצה\"ע שבמצוה כמו שהיא בכל פרטי' לא יוסיף ולא יגרע שלא הי' נודע לו כלל בתושב\"כ, כידוע במ\"ש אשת חיל עטרת בעלה שבינה יתירה<sup data-n=\"598\">69</sup> ניתנה באשה תושבע\"פ מבאיש תושב\"כ להגיע לאמיתי' גילוי עצם נקודת רצה\"ע שהוא בחי' המעשה דמצוה שנק' כשב\"כ כנ\"ל שמזה יבא גילוי אור העוה\"ב כו'. א\"כ מוכרח לומר שמגיע בעמל תורה דמשנה וגמרא בבעל הרצה\"ע הפנימי הנ\"ל, והוא בבחי' מקיף דשעשועי' ותענוג הפשוט שברצה\"ע דמצוה למעלה שהוא מדריגה הב' דעוה\"ב שלא יכול לבא בגילוי לנשמות גם בעוה\"ב שבא מן המצות עצמן כנ\"ל וד\"ל.\n[ח] <b>ובזה</b> יתורץ הכל, דגם שבאמת עיקר העוה\"ב הוא רק גילוי התענוג ורצון הפשוט שלמעלה מטעם כמוס דח\"ע דתורה כנ\"ל, זהו קבלת שכר",[["595","66","<b>יצא חנם בלא מצות</b>: ראה ספרי בהעלותך יא, ה. תו\"א משפטים עו, א. ג. סה\"מ תקס\"ה ע' רנט. רפה. רצג [שם הלשון: ובשביעית יצא לחפשי חנם כמארז\"ל ע\"פ זכרנו את הדגה אשר נאכל במצרים חנם, חנם בלא מצות, כמ\"כ הכא שנאמר חנם הוא חנם בלא מצות כו']. ס' מאמרי אדהאמ\"צ שמות ח\"א ע' קלד. ויקרא ח\"א ע' קצט. במדבר ח\"א ע' רנט. דברים ע' א'שפד. ולעיל ד\"ה שמח תשמח (הראשון) סכ\"ט."],["596","67","<b>במ\"א באריכות בדרוש דיאר ה' פניו</b>: ס' מאמרי אדהאמ\"צ במדבר ח\"א ע' רנד ואילך."],["597","68","<b>והחכ' תחי' בעלי' דחכ'. . במ\"א בדרוש דתורה ציוה</b>: קהלת ז, יב. דרוש ”תורה צוה\" — אולי הכוונה לס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' עתר (שהוא מיוסד על ד\"ה תורה צוה — ע\"ש ס\"ע תרנח). דרוש זה הובא גם להלן אות ח' וסוף אות יו\"ד וכן נזכר בס' מאמרי אדהאמ\"צ דברים ח\"ד ע' א'רה, א'שנד, א'תיז [אמנם קרוב לומר שבכל מקומות אלו, גם בהמאמר שלפנינו, כוונתו למאמר תורה צוה שלא הגיע לידינו]."],["598","69","<b>אשת חיל עט\"ב שבינה יתירה</b>: ע\"פ משלי יב, ד. נדה מה, ב."]]],[1900420151,"דמצות מצד עצם המעשה דוקא שהוא לכל ישראל גם לע\"ה שלא עסקו בפלפול ועיון כלל כנ\"ל והוא למעלה מטעמי המצות בהעלם וסוד ה' שיתגלו לימות המשיח, אך מ\"ש למחכה לו למאן דדייק כו' שזהו בת\"ח דוקא הרי יש בזה ב' מדריגות, א' שיגיע בהעלאה זו לעומק ההעלם דח\"ע שיתגלה למשיח שא' בו ישכיל עבדי כו', והב' מה שמתקן דבר בח\"ת דתושבע\"פ לכוין אמיתית גילוי רצה\"ע איך לעשות רצונו הפשוט שבמצוה שבזה מגיע לעצמות בעל הרצון העליון שבמצות שלמעלה מחיי העוה\"ב כנ\"ל, והוא מדריגה הב' דעוה\"ב שת\"ח דוקא אין להם מנוחה בעילוי אחר עילוי עד אין שיעור כו', וגם מ\"ש במשיח ישכיל בבירור השלם שבתושבע\"פ ז\"ש יעשה למחכה לו שיגיע עי\"ז למעלה מחיי העוה\"ב, וגם כל מי ששונה הלכות בכל יום יגיע לזה כמ\"ש שכל השונה הלכות בכ\"י<sup data-n=\"599\">70</sup> מובטח לו שהוא בן העוה\"ב שנאמר הליכות עולם לו לפי שיש בכלל מאתיים מנה כו', כי התענוג ורצון הפשוט שבמצות אינו רק חלק א' מעצמות השעשועי' דבעה\"ר בעצמו שנק' מקיף דשעשועי' העליוני', וכידוע בענין כתר תורה שבמ\"ת שהי' ע\"י שא' נעשה ונשמע כו' (ולפ\"ז גם בע\"ה בביטול הרצון לעשות רצון קונו יגיע לעצמות בעה\"ר שלמעלה מגילוי או\"פ דתענוג ושעשועי' שבמצות שבבחי' או\"י וכן ע\"י תשובה כו' (כמ\"ש שם<sup data-n=\"600\">71</sup>), וזהו שבימות המשיח א' ולא ילמדו<sup data-n=\"601\">72</sup> כו' כולם ידעו אותי אף הע\"ה, לפי שגם סודות ורזין דאורייתא שבהעלם דח\"ע יתגלה לכולם בשוה מטעם זה, ועכ\"ז מי ששונה הלכות בעוה\"ז ע\"ז א' למחכה לו בעדן העליון יותר מהעוה\"ב כמ\"ש ת\"ח אין להם כו', לפי שיגיעה זו שבעיון הלימוד ההלכות יש בו עוד ענין אחד שלמעלה מביטול ושממון דמוח החכמה לידע אמיתי' הרצון בעצם שלמעלה מידיעת הטעם לרצון, כמו כשלומד הלכות תפילין בעיון גדול בטעם הדין אין הכוונה לידע ולהשיג הטעם והסברא מצד עצמה רק כדי שיכוין וידע לאמיתית הרצה\"ע שבה אם כך או כך דהיינו איך יהי' אופן המעשה דמצות תפילין להכשירו בתכלי' באופן שלא יטה ימין ושמאל מאמיתי' רצה\"ע שבמצוה זו בכל פרטי', שאין זה רק מחמת הביטול האמיתי' באימה ויראה גדולה שלא יעשה נגד רצה\"ע רק לקיים גזירתו כמו שהוא לאמיתתו דוקא א\"כ עיקר העסק העיון הזה בא רק מיראה וביטול עצום שהוא מגיע לעצמות בעהר\"צ (יותר מביטול דע\"ה שמבטל רצונו רק לענין מעשה לעשות רצון קונו ות\"ח אימה יתירה יש בהם לכוין לאמיתי' רצה\"ע ע\"י יגיעה עצומה בעיון והעמדה על הדבר זמן רב שזהו מיצוי הנפש וכלותה לכוין הרצון באמיתתו לבד, וזהו למחכה לו ממש, וחיכוי זה הוא בכל נקודת כח נפשו שמצפה לעמוד על רצונו האמיתי כמו נפשי חכתה כו' כמו העני שנושא נפשו ומצפה בעיניו",[["599","70","<b>שכל השונה הלכות בכ\"י</b>: סוף ברכות."],["600","71","<b>כמ\"ש שם</b>: ראה בהנסמן לעיל פיסקא: והחכ' תחי'. וראה ס' מאמרי אדהאמ\"צ במדבר ח\"ב ס\"ע תרעא ואילך, תרפב ואילך."],["601","72","<b>ולא ילמדו</b>: ירמי' לא, לג."]]],[1900420152,"לפיקוח נפשו מן העשיר כו', ע\"כ יגיע בזה החיכוי למהו\"ע א\"ס ב\"ה ממש שלמעלה גם מעצם הרצה\"ע שבמצות וכ\"ש מטעם הכמוס שבה, ואע\"פ שעיון זה הוא בטעם הדבר לבד, אבל עיקר החיכוי הוא רק לידע אמיתית הרצון שא\"א לו להשיגו כ\"א ע\"י דיוק זה במילין דחכמה שהוא בטעם הרצון אם כך או כך, וע\"כ גם מי ששונה הלכות בטעמיהן שכבר הובררו בעיון יהי' בן עוה\"ב בגילוי התענוג הפשוט שבמצות לפי שבהלכות מאיר מעצמות בעה\"ר בסוף מעשה דוקא (כמשי\"ת).\n<b>(ולפי</b> כל הנ\"ל יובן גם ענין עסק הנשמות הגבוהות כמשה ואבות שילכו מחיל כו' ויהללוך סלה זהו ע\"י שעסקו בעמל תורה ואבות בעובדות שלהם כענין מדריגה הב' דעוה\"ב הנ\"ל, אך בתחה\"מ ירדו נשמות האלה ממקום שעלו שם ברום המעלות ויבאו בגופים טהורים ע\"י טלא דנטיף כו' מבחי' פנימי' ע\"י אחר שיהי' שלימות הבירור דרפ\"ח ע\"י משיח דוקא בתושבע\"פ דעי\"ז דוקא יוכל להיות תחה\"מ אח\"כ שנק' טהרה שגופים ועצמו' גשמי' יקבלו מאור פנימי' ע\"י שהוא בחי' התענוג הפשוט דאא\"ס שירד למטה כ\"כ להיות בבחי' חיות מורגש, והוא העוה\"ב שבו יהי' גילוי אור התענוג הפשוט שבמצות בחיות מורגש כמ\"ש ונחי' לפניו<sup data-n=\"602\">73</sup> ממש, וזה יהי' מיד אחר תחה\"מ שיקומו גם האבות וכל צדיקים הגדולים (וכמ\"ש שיעשה סעודה לצדיקים<sup data-n=\"603\">74</sup> כו', ועלי' הב' הוא מ\"ש וקווי ה' יחליפו כח כו' שיהי' שטים ע\"פ המים עליוני' דתורה ומצות שז\"ש יעשה למחכה לו ממש), (ולפ\"ז עדיין לא יובן מ\"ש בעדן עין לא ראתה כו' דודאי משה ואבות ומשיח שעסקו בעמל תורה ראו לעדן זה כו' וכמ\"ש יהללוך סלה כו' גם עכשיו, אמנם באמת אע\"פ שעולים והולכים כו' למעלה מתענוג הפשוט שבמצות אין בזה רק עלי' וביטול במציאות לבד כמו בשיר ושבח שזהו בשמיעה מרחוק ולא בבחי' ראי' מקרוב לעדן זה רק בעוה\"ב ותחה\"מ שיראו בעין ממש וד\"ל).\n[ט] <b>ואחר</b> כל הנ\"ל יובן ענין מה שבברכה דשמח תשמח אמר משמח חתן וכלה בתחלה לחתן ואח\"כ לכלה, ובברכה האחרונה דאשר ברא כו' מסיים חתן עם הכלה דמשמע בשביל הכלה שכל שמחת חתן מקבל משמחת הכלה דהכלה עיקר כו'. דהנה ידוע בע\"ח בסדר ההשתלשלות דע\"ס שיש ב' אופנים, א' ע\"ס דאו\"י מלמעלה למטה כח\"ב חג\"ת כו', והב' ע\"ס דאו\"ח<sup data-n=\"604\">75</sup> מלמטה למעלה שאז בחי' המל' בחי' כתר וכתר הוא מל' כו' כמ\"ש דא\"ח עט\"ב כו' וכן",[["602","73","<b>ונחי' לפניו</b>: הושע ו, ב."],["603","74","<b>שיעשה סעודה לצדיקים</b>: ראה פסחים קיט, ב. ב\"ב עד, ב. עה, ב. וראה ס' מאמרי אדהאמ\"צ במדבר ח\"א ע' רנה ובהמ\"מ שם."],["604","75","<b>בע\"ח. . ע\"ס דאו\"י. . ע\"ס דאו\"ח</b>: ע\"ח שער מ\"ן ומ\"ד פי\"ד — הובא בלקו\"ת שה\"ש כ, רע\"ב. ועיין בהנסמן שם עוד. וראה ס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' שסט."]]],[1900420153,"א' הנני בורא חדשו'<sup data-n=\"605\">76</sup> כו' נקבה תסובב גבר כו'. ויובן זה ע\"פ כל הנ\"ל בענין עדן דעין לא ראתה כו' להיות שבתחלת ההשתלשלות הי' בבחי' או\"י, דתחלה עלה ברצונו הפשוט להאציל כו', והוא בחי' התענוג הפשוט שלמעלה מן החכמה שהוא בחי' חפץ חסד כו', ונמשך מכתר דרצון ותענוג בחכמה ומחכמה לבינה ומבינה למדות עד בחי' המל' שם אלקי' הוא האחרון במע\"ב, וז\"ש בראשית דחכמה ברא אלקים בחי' בינה ומל' כו' כמ\"ש מגיד מראשית אחרית כו', וז\"ש ביום עשות ה' אלקים<sup data-n=\"606\">77</sup> כו' שהוא יחוד דהוי' ואלקים ביחו\"ע דכח\"ב ומדות ומל' בבחי' או\"י מלמעלה למטה, ואע\"פ שהי' יחוד זה בחיצוני' בשביל בנין העולמות לבד, אמנם גם יחוד פנימי שהי' בזה כמ\"ש בשביל התורה שנק' ראשית וישראל<sup data-n=\"607\">78</sup> שנק' ראשית שהן בחי' חו\"כ משפיע ומקבל, כמו שהי' במ\"ת דתנאי הי' כו' כנ\"ל ג\"כ הי' עד\"ז בבחי' יחו\"ע דמ\"ה וב\"ן קודב\"ה ושכינתי' דבחי' או\"י שהוא יחוד הוי' אלקים סובב וממלא, וזה הי' קבלת התורה שהקב\"ה נק' חתן וכנ\"י נק' כלה בחי' מקבל שקיבלו אור התענוג ורצה\"ע שבתורה כמ\"ש ביום חתונתו<sup data-n=\"608\">79</sup> כו' וד\"ל.\n<b>וזהו</b> ענין החתימה בברכה דשמח תשמח משמח חתן וכלה בתחלה לחתן שהוא התורה ואח\"כ להכלה שהן כנ\"י שהוא בחי' המל' למעלה בחי' ב\"ן שמקבל משם מ\"ה, וזהו כמו שהי' אדה\"ר בג\"ע קודם חטא עה\"ד שהי' בדוגמא דיחו\"ע דזו\"נ חו\"ב דאצילות שנק' ריעים האהובים כו'. וזהו כשמחך יצירך בג\"ע מקדם, שתחלה שמחת חתן ונכלל בזה שמחת כלה שהיא חוה שנבנית מצלעותיו וכמ\"ש דאשה בעלה משמחה כו' דאל אישך תשוקתך<sup data-n=\"609\">80</sup> והוא ימשל בך, וכן בענין תושב\"כ ותושבע\"פ שהיא חו\"ב בינה מקבל מחכמה, וכך גם ברום המעלות דנובלות חכמה של מעלה<sup data-n=\"610\">81</sup> תורה ונובלות בינה של מעלה שכינה כו' וד\"ל.\n<b>אבל</b> בברכה האחרונה דאשר ברא כו' מדבר כמו שיהי' לע\"ל בעוה\"ב שתעלה בחי' המל' בחי' ב\"ן למעלה משם מ\"ה אחר הבירור דעה\"ד שהוא בחי' או\"ח מלמטה למעלה דא\"ח עט\"ב כו' שע\"ז אמר בעדן עין לא ראתה רק למחכה לו דוקא שהוא מאן דדייק מילין דחכ' שהוא בחי' הבירורים דח\"ת דתושבע\"פ לתקן דבר המקולקל שנפל בשבה\"כ כו', שיש בזה ב' דברים, א' שיגיעה זו לבא לביטול בתכלית נמשך מהעלם דסדכ\"ס שלמעלה ממקור החכמה דתורה",[["605","76","<b>הנני בורא חדשו'</b>: ע\"פ ירמי' לא, כא: כי ברא ה' חדשה בארץ נקבה תסובב גבר."],["606","77","<b>מגיד מראשית אחרית. . ביום עשות ה' אלקים</b>: ישעי' מו, יו\"ד. בראשית ב, ד."],["607","78","<b>בשביל התורה. . וישראל</b>: רש\"י ר\"פ בראשית."],["608","79","<b>ביום חתונתו</b>: שה\"ש ג, יא."],["609","80","<b>דאשה בעלה משמחה. . דאל אישך תשוקתך</b>: ר\"ה ו, ב. בראשית ג, טז."],["610","81","<b>דנובלות חכמה של מעלה</b>: ב\"ר פי\"ז, ה."]]],[1900420154,"הקדומה כו', והב' שיומשך משם ענין התיקון שיוכל לתקן דבר המקולקל, והוא שיגיע לנקודת אמיתי' הרצה\"ע שבמצות שהוא בבעה\"ר עצמו שנק' מקיף דשעשועי' העצמי' שלמעלה גם משעשועי' ותענוג הפשוט שבמצות מצד המעשה עצמה הנק' כשב\"כ וכ\"ש למעלה מטעם הכמוס שבה כו' כנ\"ל. ונמצא שע\"י ישראל בעיון ודיוק החכמה דתורה בלימוד הלכות כנ\"ל (וגם בע\"ה בביטול הרצון לעשות רצון קונו כנ\"ל) עי\"ז נמשך בחי' גילוי אור התענוג ושעשועי' העצמי' שבמצות בעוה\"ב, ומאחר שישראל הן בחי' הממשיכים כשנק' א\"ח בבירור דעה\"ד כו' הרי הם נק' בחי' חתן משפיע וממשיך לגילוי אור התענוג ושעשועי' מן ההעלם דמקיף דתענוג ושעשועי המלך בעצמו כו' שז\"ש יעשה בגילוי מן ההעלם למחכה לו דוקא. וזה הי' ג\"כ במ\"ת ע\"י שא' נעשה ונשמע שעי\"ז נמשך בחי' גילוי אור התענוג הפנימי בחכ' ורצון דתומ\"צ כו' בי' הדברות בבחי' או\"י מלמעלה למטה כו'. וזהו שבברכה זו דאשר ברא שמדבר לע\"ל כמ\"ש מהרה ישמע כו' [אמר] משמח חתן עם הכלה בשביל הכלה שהן כנ\"י דהיינו הלכה אותיות הכלה<sup data-n=\"611\">82</sup> שהוא אותיות דתושבע\"פ מל' קרינן לה שעולה למעלה מבחי' שם מ\"ה דחכ' דתורה כו' מטעם הנ\"ל שבחי' המל' ע\"י שלימות הבירורים דדייק ביגיעה לידע אמיתית הרצון ממשיך מהעלם דבעה\"ר להיות גילוי התענוג והרצון דמצות שהוא מקיף דשעשועי' שבא לגילוי וכמ\"ש אני תורתך שעשעתי<sup data-n=\"612\">83</sup> כו'. ובזה יתורץ הקושיא הנ\"ל בחידוש זה דיחוד חו\"כ שלא הי' כמוהו במע\"ב וגם במ\"ת רק ע\"י נעשה ונשמע שאז לא הי' רק בבחי' או\"י ולע\"ל יהי' א\"ח עט\"ב וד\"ל.\n[י] <b>אך</b> עדיין י\"ל מה שלפעמי' נק' התורה כלה מאורסה וישראל נק' חתן משפיע כמ\"ש ישראל אשר בך אתפאר<sup data-n=\"613\">84</sup> בפאר ות\"ת דתורה והוא מטעם הנ\"ל דבדיוק מילין דחכמה דתושבע\"פ ממשיכים לגילוי הרצה\"ע שבתו\"מ כו', א\"כ למה נק' הלכה כלה אחר שהוא בחי' משפיע ואיך אמר משמח חתן עם הכלה כו' דעכ\"פ נק' בשם כלה בחי' מקבל. אמנם הענין הוא, דגם שישראל ממשיכים לגילוי התענוג הפשוט ע\"י הדיוק במילין דחכמה כנ\"ל, מ\"מ בחי' הנוק' שנק' מקבל שהוא כלי קיבול לקבל בתוכו גילוי אור התענוג הפשוט משעשועים העצמי' שנמשך ע\"י ישראל זהו התורה עצמה שנק' מאורסה לישראל, והוא שנק' כלה המקבל, והן ההלכות שבתושבע\"פ שזהו אותיות הכלה כו', והיינו בדיוק מילין דחכמה עצמו דאע\"פ שעי\"ז גורם המשכת התענוג ושעשועים דמקיפים לגילוי מ\"מ מי הוא בחי' הכלי המקבל לגילוי אור התענוג הפשוט הנה הוא בא ומתלבש ומתגלה באותן הלכות שבתורה שנק'",[["611","82","<b>הלכה אותיות הכלה</b>: פע\"ח שער הנהגת הלימוד (שי\"ז) ד\"ה גם העוסק בתורה. וראה גם ס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' קיא. לעיל ח\"א ע' שטו. וש\"נ."],["612","83","<b>אני תורתך שעשעתי</b>: תהלים קיט, ע."],["613","84","<b>ישראל אשר בך אתפאר</b>: ישעי' מט, ג."]]],[1900420155,"מילין דחכ' שהן בחי' כלי ממש לקבל בתוכם לגילוי אור התענוג ורצה\"ע שבמצות שהוא למעלה הרבה מטעם הכמוס, דגם שהחכמה מאין דכתר תמצא שאינו אלא טעם לרצה\"ע, אבל ע\"י היגיעה רבה בביטול ושממון לידע איכות הרצה\"ע נעש' היא עצמה בחי' כלי קיבול לקבל גילוי אור התענוג הפשוט שלמעלה מן הטעם הכמוס וגם ממקיפי' דשעשועי' כו', וזהו שקודם שמקבלים ההלכות לגילוי אור התענוג הזה נק' בתולות ועלמות כמ\"ש ועלמות אין מספר שהן הלכות (ומשניות וברייתות נק' ס' מלכות ופ' פלגשים<sup data-n=\"614\">85</sup> כו' שמקבלים מתושב\"כ), אבל אחר שקיבלו ההלכות ע\"י העיון בדיוק במילין דחכמה ממקיפים דשעשועי' העצמיי' הנ\"ל נק' כלה והוא הלכה אותיות הכלה וישראל נק' חתן שהן הממשיכים לגילוי אור התענוג הפשוט הזה ממקורו בחכמה שבתורה בהלכות שנק' בתולות ע\"י העיון ודיוק שמדייקי' במילין דחכ' (ועכ\"ז א' משמח חתן עם הכלה בשביל הכלה שהיא התורה שנק' מאורסה לישראל כמשי\"ת), וזהו שהתורה נק' ברית כמ\"ש אלה דברי הברית כנ\"ל, כי התורה נק' כלה מאורסה לישראל בחי' מקבל לאור התענוג דשעשועי המלך בעצמו הנ\"ל ע\"י ישראל הממשיכים בה בעיון ודיוק במילין דחכ', וכמו שאין האשה כורתת ברית<sup data-n=\"615\">86</sup> אלא למי שעשאה כלי דוקא כך התורה נק' ברית שאינה כורתת ברית רק לישראל שעשאה כלי קיבול בהמשכת אור התענוג הפשוט הנ\"ל, וזהו עוסק בתורה לשמה לשם התורה כו' (ומ\"ש ישראל מתקשראן באורייתא<sup data-n=\"616\">87</sup> זהו כשהתורה נק' חתן וכנ\"י כלה בחי' יחוד דזו\"נ מ\"ה וב\"ן מלמעלה למטה בבחי' או\"י דיחוד ת\"ת ומל' שהוא תושב\"כ ותושבע\"פ כנ\"ל והן ס\"ר אותיות בתושב\"כ שהן מקוריים לס\"ר נש\"י כו', אבל בעלי' דשם ב\"ן בבחי' או\"ח למעלה מכתר דחכ' דתומ\"צ נהפוך הוא שישראל נק' משפיע לתורה שהן ההלכות שנק' עלמות שאין להם מספר כמו נש\"י למעלה מבחי' יחו\"ע דחו\"ב אינם במספר ס\"ר כמ\"ש והי' מספר בנ\"י כחול כו' שמספר ס\"ר הוא רק בו' מדות דז\"א מחו\"ב כו' וכן המל' כו' דמתניתין מלכתא<sup data-n=\"617\">88</sup> כו' אבל לעלמות אין מספר מטעם הנ\"ל וד\"ל) וזהו שע\"י ישראל שממשיכים למקיפים דשעשועי המלך שאינו במספר חלקים ע\"כ יולידו נשמות חדשות לע\"ל בלי מספר, שאין תולדה במספר באה רק מיחוד דכר ונוק', אבל לע\"ל יהי' בחי' הנוק' למעלה מן הדכר כו' והן הלכות שיקבלו מבחי' מקיף דעצמות התענוג הפשוט כו' (והוא מדריגה הב' דעוה\"ב הנ\"ל שילכו מחיל כו' שלמעלה מחיי העוה\"ב בתענוג הגלוי שבא במספר מדריגות כש\"י עולמות כו' ולכך נק' פרס שאינו רק חלק א' קטן מעצמות השעשועי' דבחי' המקיפים כו' כנ\"ל וד\"ל).",[["614","85","<b>ועלמות אין מספר. . ס' מלכו' ופ' פלגשים</b>: שה\"ש ו, ח וראה שהש\"ר עה\"פ. במדב\"ר פי\"ח, כא. זח\"ג רטז, א."],["615","86","<b>אלה דברי הברית. . שאין האשה כורתת ברית</b>: ע\"פ תבוא כח, סט. סנהד' כח, ב."],["616","87","<b>ישראל מתקשראן באורייתא</b>: ראה זח\"ג עג, א."],["617","88","<b>והי' מספר בנ\"י. . דמתניתין מלכתא</b>: הושע ב, א. ביצה כח, ב."]]],[1900420156,"<b>אך</b> עכ\"ז אומרים משמח חתן עם הכלה, דאע\"פ שישראל נק' חתן משפיע וממשיך לאור התענוג הפשוט הנ\"ל לתורה שנק' כלה, מ\"מ שמחת החתן באה עם הכלה בשביל הכלה דוקא שבעבור הכלה משמח גם לחתן כו'. והענין הוא דגם שע\"י העיון ודיוק דנש\"י בהלכות נמשך מקיף דשעשועי' הנ\"ל, מ\"מ אם לא החכמה דתורה שבהלכות אלה לא הי' בחי' בית קיבול לקבל אור התענוג העצמות הזה ולא הי' נמשך כלל למטה רק בשביל הכלה שנק' מקבל (ולא ישראל לפי שהיתה התורה אצלו שעשועי' קודם שישראל עלו במח' כמ\"ש בשביל התורה שנק' ראשית כו' רק שלא הי' שלימות ניכר בעונג זה עד שבא התורה בעה\"ד בסוף מעשה לתקן דבר המקולקל כו' שזה עלה במח\"ת להשלים התענוג ושעשועי' שהי' תחלה וכמ\"ש בדרוש דתורה ציוה לנו באורך<sup data-n=\"618\">89</sup>), וע\"כ כל עיקר התעוררות שמתעורר ממקיף דשעשועי' להאיר בגילוי שנק' שמחה זהו בשביל הכלה שנק' מקבל בסוף מעשה דנעוץ תחילתן בסופן דוקא, וזהו שנק' הלכה מלשון הליכה כמו הליכות עולם לו<sup data-n=\"619\">90</sup> כו', וע\"כ השונה הלכות גם בלא דיוק הוא בן עוה\"ב לפי שזהו הכלי קבלה לגילוי התענוג הפשוט כו', וע\"כ גם שמחת חתן שהן ישראל המשפיעים בתורה לא באה רק בעבור שמחת הכלה וכמ\"ש א\"ח עט\"ב נקבה תסובב גבר כו'. וזהו שבעוה\"ב שנק' ארץ החיים העליוני' ארץ חפץ כו' וישראל נק' צדיקי' ירשו ארץ ע\"י העיון בתורה ומעשה המצות שנק' בשם חו\"כ עכ\"פ רק שהכלה עיקר כו', אבל למעלה מחיי העוה\"ב אין שם בחי' משפיע כלל אדרבה המשפיעים נעשו בחי' מקבלים, והן נשמות הצדיקים שילכו מחיל כו' לקבל ממקיפי' דשעשועי' העצמיי' כמו שהוא בבחי' א\"ס ממש, והוא מדריגה הב' דעוה\"ב שת\"ח אין להם מנוחה כו' שהן נשמות שעסקו בעמל תורה שמשפיע ומקבל יחדיו יעלו לקבל וכן כאשר התורה נק' חתן וישראל כלה שם שניהם שוין להיותו למעלה מבחי' דו\"נ כו', וזהו מ\"ד דשמים וארץ כא' נבראו כו' כמ\"ש במ\"א וד\"ל.\n[יא] <b>והנה</b> יש עוד בחי' ומדריגה שנית בתורה והוא מצות קריאת התורה בדיבור בפה דוקא, כמ\"ש ודברת בם כו' וכן לא ימוש מפיך למען תהי' תורת ה' בפיך וכן ואשים דברי<sup data-n=\"620\">91</sup> בפיך כו', וכתי' כי על כל מוצא פי ה' יחי' האדם שזה למוציא דבר ה' בפה כמא' חיים הם למוציאיהם בפה<sup data-n=\"621\">92</sup> דוקא, ובמצוה זו יש יתרון מעלה ממצות עיון והגיון בתורה במח' לבד שע\"ז א' והגית בו יומם כו' וכן בתורתו יהגה<sup data-n=\"622\">93</sup> כו' אע\"פ שע\"ז א' למחכה לו למאן דדייק כו' כנ\"ל, כי הנה מצות העיון והגיון במח' לדייק במילין דחכמה הנה ודאי יש",[["618","89","<b>וכמ\"ש בדרוש דתורה ציוה לנו באורך</b>: ראה לעיל סוף אות ז', ובהמ\"מ שם."],["619","90","<b>הליכות עולם לו</b>: חבקוק ג, ו."],["620","91","<b>ודברת בם. . לא ימוש. . למען תהי'. . ואשים דברי</b>: ואתחנן ו, ז. יהושע א, ח. בא יג, ט. ישעי' נא, טז."],["621","92","<b>כי על כל מוצא. . חיים הם למוציאיהם בפה</b>: עקב ח, ג. משלי ח, כב. עירובין נד, א."],["622","93","<b>מצות עיון והגיון. . והגית בו. . בתורתו יהגה</b>: יהושע שם. תהלים א, ב. ראה לעיל ד\"ה משמח חו\"כ (קרוב לסופו). וש\"נ."]]],[1900420157,"בו מעלה יתירה שהוא העיקר במצות ת\"ת בכללות שהוא לידע ולהשיג עומק טעמי ההלכות וטעמי המקראות שבכתב ושבע\"פ להשיגם על בוריים בכדי שיבא על אמיתית הדין וההלכה שהוא אמיתית נקודת רצה\"ע שבמצות בכל פרטי' לענין מעשה דוקא, כנ\"ל שיש בזה ב' דברים, א' מצות ידיעת התורה לאמיתת הדין וההלכה בכל מצוה ומצוה בכל פרטי', והב' ענין המעשה לקיים רצה\"ע האמיתי כמו שהוא ומלבד ענין ההעלאה וביטול המציאות בכל מיצוי הנפש לחכות להשגות הרצה\"ע איך הוא שבזה מגיע לבעה\"ר שיומשך ממנו אופן הרצון כמו שהוא באמיתתו כנ\"ל. וע\"כ בתושבע\"פ דוקא עיקר גילוי רצה\"ע למעשה שאין כל אלה בתושב\"כ שלא ידע ממנה ידיעת דיני התורה בכל פרטי' ולא טעמי הדינים לאמיתתן רק מצות קריאה לבד שקורא לאותיות וצירופים שבתושב\"כ בדבור בפה שלא נודע מהם כלל אמיתית רצה\"ע כלל, וגם בקורא בתושבע\"פ דברים כהווייתן בלי דיוק ועיון כלל לא ישיג לעומק הטעם ולא ידע אמיתי' הרצה\"ע וגם לא ידע לענין מעשה כלום, כמו בפ' ציצית ותפילין לא ידע בקריאתה איך לעשות ציצית ותפילין כלל כו'. אך עכ\"ז יש מעלה יתירה במצות קריאה בתורה שבכתב ובע\"פ במה שבקריאה זו הוא ממשיך ומגלה לדבר ה' שיוצא כמו שהוא למעלה מפי ה' ממש כמ\"ש ואשים דברי בפיך כו', כמו במ\"ת שיצא לגילוי דבר ה' בי' הדברות ודבריו חיים וקיימים, שכך הוא גם עתה בכל מי שיושב וקורא מקרא ושונה משנה שה' קורא ושונה כנגדו כו' כי דבר ה' הוא מדבר ואין זה דברי עצמו כלל כמו תען לשוני<sup data-n=\"623\">94</sup> אמרתך כו' כעונה אחר הקורא כו', וא\"כ הרי בקריאה זו ממשיך גילוי אא\"ס שהוא בעל הרצון העליון שבמצות התורה מאחר שהוא עצמו מדבר דבר הלכה זו או מקרא זה ונק' מוצא פי ה' ממש כנ\"ל, א\"כ יש בדיבור זה מפנימי' ועצמות התענוג ושעשועים שבעצמות ממש שלמעלה מעונג ושעשועים שנמשך ע\"י העלאה דדיוק ועיון במילין דחכ' בסוף מעשה שעלה במחשבה תחילה שאין זה שעשועי' העצמיי' ממש, וכמו עד\"מ אדם ששמח בנפשו בפנימי' התענוג העצמי במה שלומד וקורא בד\"ת שזהו שמחה העצמי' דבחי' יחידה שמתענג בעצמו בשפע זו שממשיך בגילוי הדיבור, וז\"ש כי על כל כו' יחי' האדם וד\"ל (וזהו למעלה גם מבחי' מקיף דשעשועי' הנ\"ל בענין דיוק במילין דחכ' שאינו רק מקיף דעונג ורצה\"ע דתומ\"צ לבד שלמעלה מגילוי השעשועי' שבתורה כו', אבל שמחה ועונג עצמי זה שבהשפעה הבאה בגילוי בדיבור בתורה הוא בתענוג ושעשועי' העצמיי' ממש שלמעלה ג\"כ משעשועי המלך בעצמו, כמשל שמחה ותענוג דמשפיע שפע החכמה בדבור שגדול הוא מעונג שמצד עצמו (ולמעלה גם מעונג שבחכ' זו בפרט כו'), וכמו שהי' במ\"ת שא' ביום חתונתו כו' שנמשך משעשועי' העצמיי' בשפע זו דדיבור דתורה (וז\"ש כי על כל כו' יחי' האדם העליון, לפי שמהבל הדבור נעשה או\"מ דאו\"ח",[["623","94","<b>שה' קורא ושונה כנגדו. . תען לשוני</b>: תדא\"ר ריש פי\"ח. תהלים קיט, קעב."]]],[1900420158,"שלמעלה מתענוג דאו\"י כמ\"ש במ\"א<sup data-n=\"624\">95</sup>, ואע\"פ שבתושבע\"פ נודע עיקר נקודת רצה\"ע לאמיתתו ולמעשה משא\"כ בתושב\"כ כנ\"ל, זהו לגבי המקבלים לבד אבל לגבי המשפיע שהוא דבר ה' שמדבר בעצמן לפניו נגלה כל מה שברצון זה לאמיתתו ועומק הטעם וסוד הדבר וגם מה שצריך לבא למעשה בבחי' הבירורים בסוף מעשה כמו משה ידבר כו' תורה ציוה<sup data-n=\"625\">96</sup> לנו משה שהוא ח\"ת שבתושבע\"פ דהיינו שנותן כח לח\"ת לדייק במילין כו').\n<b>ונמצא</b> שבחי' קריאה זו באותיות וצירופי' שבתורה כמו לקרות בתנ\"ך וגם במשנה בהלכות דברים כהוייתן בלא דיוק הרי ממשיכי' גילוי אור העצמו' דא\"ס ממש באותיות הללו שקורא ושונה כו' שהוא ית' קורא ושונה אותיות הללו ממש כמו במ\"ת שא' וידבר אלקי'<sup data-n=\"626\">97</sup> כו', וה\"ז בחי' המשכה והשפעה דבחי' דכר שזהו מאור העצמו' דא\"ס בשעשועי' ותענוג הפשוט שנמשך בשפע זו כנ\"ל, ואותיות התורה הללו שבהן נגלה השפעה זו נק' בחי' מקבל שמקבל גילוי האור הזה דא\"ס כאשר קורא אותן ונמשכו באותיות הללו. וזהו שאותיות התורה נק' שמותיו של הקדב\"ה<sup data-n=\"627\">98</sup> והקורא באותיות התורה הרי קורא בשמותיו של הקב\"ה דהיינו שבקריאה זו קורא להקב\"ה בשמותיו שיומשך באותיות התורה הללו. וז\"ש קרוב ה' לכל קוראיו (שזהו הקריאה בשמותיו המיוחדי' אליו כשם הוי' ואלקי' כמו בקריאה בתפלה וכה\"ג) לכל אשר יקראוהו באמת ואין אמת אלא תורה<sup data-n=\"628\">99</sup> שהן שמותיו העצמי' שבקריאתו אותם קורא וממשיך לעצמות אוא\"ס שיתגלה בתוך אותיות הללו שנק' אמת והוא במה יושב ה' וקורא ושונה כנגדו כנ\"ל, וזהו פי' באמת בתוך האמת דתורה, שזהו למעלה מקריאה בתפלה כמ\"ש בזהר ע\"פ השמיעני את קולך כי קולך ערב זהו קלא דאורייתא<sup data-n=\"629\">100</sup> כו', וזהו כמשל הקורא את המלך שיפנה אליו בעצמו' פנימיותו כמו שהוא לאמיתתו במקומו שאז יקראנו בשמותיו העצמי' שהוא עצמו נמשך בהם תמיד (וכמ\"ש במ\"א במ\"ש למען אחי וריעיי<sup data-n=\"630\">101</sup> כו' שע\"י קריאת התורה נק' ישראל אחים וריעים להקדב\"ה כאחים שיושבים יחד וקורים ושונים כו'), ולא יוכל להמשיך לעצמו' אוא\"ס ממש כ\"א ע\"י קריאה זו ולא ע\"י העיון ודיוק באותיות התורה במח' לבד שאינו מגיע להעצמות דא\"ס ממש רק",[["624","95","<b>שמהבל הדבור נעשה או\"מ. . כמ\"ש במ\"א</b>: ראה פע\"ח שער ספה\"ע ספ\"ג. לעיל ח\"א ע' קעה. וש\"נ."],["625","96","<b>משה ידבר. . תורה ציוה</b>: יתרו יט, יט. ברכה לג, ד."],["626","97","<b>וידבר אלקי'</b>: יתרו כ, א."],["627","98","<b>שאותיות התורה נק' שמותיו של הקדב\"ה</b>: ראה זח\"ב קכד, א. רמב\"ן עה\"ת בהקדמה."],["628","99","<b>קרוב ה' לכל קוראיו. . ואין אמת אלא תורה</b>: תהלים קמה, יח. ראה ברכות ה, ב. ירושלמי ר\"ה פ\"ג ה\"ה."],["629","100","<b>בזהר ע\"פ השמיעני. . קלא דאורייתא</b>: שה\"ש ב, יד. ראה זח\"א עז, א. זח\"ג סא, א. ריג, א. וראה ד\"ה השמיעני בסה\"מ תקס\"ג ח\"א ע' צט."],["630","101","<b>במ\"א במ\"ש למען אחי וריעיי</b>: תהלים קכב, ט. וראה סה\"מ תקס\"ה ח\"א ע' קכח ואילך. וע' תפז ואילך [ומקבילו באוה\"ת שה\"ש כרך ב' ריש ע' תרפ]. ס' מאמרי אדהאמ\"צ בראשית ע' שמה, ובהנסמן בהמ\"מ שם."]]],[1900420159,"לבחי' התענוג הנעלם שברצון וחכמה דתורה לבד כו' כנ\"ל וד\"ל. (וזהו כי לא על הלחם<sup data-n=\"631\">102</sup> דתורה לבד שהוא מצד מקור החכ' דתו' יחי' האדם כמו במצות עיון דתורה כ\"א על כל מוצא פי ה' בדיבור וקריאה דאותיות התו' דוקא יחי' האדם\n[יב] <b>וזהו</b> ענין הברכה הקודמת דשמח תשמח כו' שמסיים משמח חו\"כ ולא אמר עם הכלה שאין הכלה עיקר אלא החתן, דהיינו שאין שמחת החתן באה משמחת הכלה כנ\"ל אלא שמחת הכלה באה משמחת חתן דוקא, כי הרי בקריאה זו שמח ישמח בהמשכת גילוי אור עצמות א\"ס שמתגלה בדיבור וקריאה זו כנ\"ל במה שמשפיע באותיות הדבור הללו, וזהו שמחת חתן שמשפיע וממשיך לאותיו' התורה, כענין ר\"ש שא' חדאי נפשאי<sup data-n=\"632\">103</sup> לך קראי לך תנאי לשמח הנפש בקריאה זו כענין ונשמח בד\"ת כו' כי הם חיינו כו', ונמצא הדבור הוא המשפיע והכלה הן אותיות התורה עצמן שמקבלים השפע דאוא\"ס ע\"י הדיבור הזה שמדבר וקורא כו', וזהו משמח חתן שהקב\"ה הוא המשמח את החתן שהוא המדבר וקורא בתורה. וזהו שמח תשמח ריעים האהובים שהן החו\"כ דתורה וישראל שממשיכים בתורה ע\"י הדבור (וכן כשישראל נק' כלה שמקבלים מאותיות התורה בדיבור זה להחיות נשמתם כמ\"ש כי הוא חייך<sup data-n=\"633\">104</sup> כו' וכן על כל מוצא פי ה' יחי' האדם שהן נש\"י שמתקשראן באורייתא כו'. וז\"ש כ\"א בתורת ה' חפצו מעיקרא כי עביד אינש<sup data-n=\"634\">105</sup> אדעתי' דנפשי' להחיות ולתקן נשמתו באותיות התורה שכל א' יש לו אות א' בתורה, ואח\"כ ובתורתו יהגה כו' להמשיך אוא\"ס באותיות התורה שהתורה נק' כלה לקבל מעצמות אוא\"ס ע\"י העיון והגיון שנק' דיוק במילין דחכ' כנ\"ל שנעשי' בית קיבול לגילוי א\"ס כנ\"ל. וזהו ובתורתו יהגה שעוסק בתורה לשמה לשם התורה ונק' תורתו לפי שמדייק בה בעיון נק' על שמו, אבל ע\"י הקריאה בדבור נק' תורת הוי' כמ\"ש למען תהי' תורת הוי' בפיך<sup data-n=\"635\">106</sup> שזהו מה שממשיך שם הוי' באותיות התורה כנ\"ל במ\"ש אשר יקראוהו באמת דתורה כו', ובזה יש יתרון מעלה לדיוק דתורה שנק' התורה כלה שהיא עיקר ושמחתה קודמת בקבלתה מאור א\"ס וממנה נמשך שמחת חתן שהוא הנשמה הלומד ומעיין כנ\"ל מפני שסוף מעשה עלה במח\"ת, משא\"כ בדבור שמחת חתן קודם לשמחת כלה), וזהו וי\"ו דוכלה וי\"ו זה הוא המשכת השמחה מן החתן שהוא הקורא ושונה לכלה שהן אותיות התורה עצמן מאחר שבקריאה זו הוא ממשיך לאור א\"ס בתורה כנ\"ל (וזהו בבחי' או\"י, ובעיון דתורה הוא בחי' או\"ח כנ\"ל וד\"ל).",[["631","102","<b>כי לא על הלחם</b>: עקב ח, ג."],["632","103","<b>ר\"ש </b>[רב ששת]<b> שא' חדאי נפשאי</b>: פסחים סח, ב."],["633","104","<b>כי הוא חייך</b>: ע\"פ משלי ד, יג: כי היא חייך. וראה לעיל ח\"א ריש ע' רפח, ובהמ\"מ שם."],["634","105","<b>מעיקרא כי עביד אינש</b>: פסחים שם."],["635","106","<b>למען תהי' תורת ה' בפיך</b>: בא יג, ט."]]],[1900420160,"[יג] <b>ובכל</b> זה יובן מ\"ש שערך כעדר העזים<sup data-n=\"636\">107</sup> שגלשו מהר הגלעד, וקאי בכנ\"י כאשר לומדים וקוראים בתורה בדיבור או בעיון ודיוק במילין דחכמה כנ\"ל שהוא ב' אופנים דאו\"י ואו\"ח כנ\"ל שאז ממשיכים לעצמות אא\"ס באותיות התורה ביחוד פנימי כיחוד דחו\"כ כו', ע\"ז א' שערך כעדר העזים כו'. ותחלה י\"ל מהו ענין הר הגלעד. דהנה גלעד זהו שא' לבן ליעקב עד הגל הזה כו' ועדה המצבה כו' נק' גל עד שהגל הזה הוא עד להבדל והפסק שנעשה ביניהם אם אני לא אעבור אליך<sup data-n=\"637\">108</sup> כו'. ולמעלה הנה זהו בחי' הפרסא המפסיק בין עצמות המאציל לעולם האצי', שזהו שרש בחי' יעקב ולבן למעלה, דיעקב הוא בעל עולם האצי' עולם התיקון שהוא שם מ\"ה דחכמה, וזהו יו\"ד עקב<sup data-n=\"638\">109</sup> שבחכמה אתברירו<sup data-n=\"639\">110</sup> שהוא בחי' בירורים בחי' התכללות דאורות וכלים כו', כמ\"ש במ\"א בענין עובדא דמקלות אשר פצל כו' ויפרוץ האיש מאד<sup data-n=\"640\">111</sup> כו', ובחי' לבן העליון הוא בחי' לובן דרב חסד הפשוט העליון שהוא בחי' התענוג הפשוט שנק' פנימי' ע\"י בחי' כתר שבכתר שלמעלה ממקור התחלקות הקוין דאצי' דזהו מבחי' האחרונה שבעצמו' א\"ס שנמשך משעשועי' העצמי' שלמעלה מהיות גם מקור לחכ' וכמ\"ש והחכמה מאין תמצא<sup data-n=\"641\">112</sup> בדרך דילוג גדול ע\"י צמצום דבחי' מזל ונוצר כו' שנמשך ממותרי ח\"ס חכמה שבכתר לבד כו', ויש בחי' פרסא המפסקת בין עצמות המאציל לנאצלים (וכמ\"ש בזהר שז\"ש והבדילה הפרכת כו' פרכת פרסא בין קה\"ק שהוא בחי' כשב\"כ ובין קדש דחכמה דאצי' שמאין תמצא ע\"י צמצום דמזל הח' ונוצר כו', (והוא כמו בחי' קרומא דאוירא<sup data-n=\"642\">113</sup> שמפסיק בין עצם הגלגלת להמוחין דחו\"ב כו' כקרום העליון שבאדם שמכסה על המוחין כו' שמתצמצם בו ההארה להיות מקור למוחין דחו\"ב כמ\"ש במ\"א) כמו שאין ערך כלל וכלל לבחי' עונג המצומצם בשכל לגבי העונג הנעלם העצמי שבעצמות הנפש כמ\"ש במ\"א<sup data-n=\"643\">114</sup>).",[["636","107","<b>שערך כעדר העזים</b>: שה\"ש ד, א."],["637","108","<b>עד הגל הזה. . אעבור אליך</b>: ע\"פ ויצא לא, נב."],["638","109","<b>יו\"ד עקב</b>: ע\"ח שער סדר אצי' (ש\"ג) ספ\"ב. ובכ\"מ."],["639","110","<b>שבחכמה אתברירו</b>: ראה זח\"ב רנד, סע\"ב. וראה ס' מאמרי אדהאמ\"צ דברים ח\"א ע' רצה, ושם נסמן בארוכה לכמה מקומות."],["640","111","<b>במ\"א בענין עובדא דמקלות אשר פצל. . ויפרוץ האיש מאד</b>: ויצא ל, לז-ח. מג. ראה זח\"א קסב, א. שערי תשובה ס, א ואילך. תו\"ח וישלח לט, ג ואילך."],["641","112","<b>והחכמה מאין תמצא</b>: איוב כח, יב."],["642","113","<b>וכמ\"ש בזהר שז\"ש והבדילה הפרכת. . קרומא דאוירא</b>: תרומה כו, לג. וראה זח\"ג קכח, ב: בחללא דגולגלתא קרומא דאוירא דחכמתא עלאה סתימאה כו'. זח\"ב קס\"ה ורמ\"ז שם. וראה בכ\"ז בס' מאמרי אדהאמ\"צ: ויקרא ח\"ב ר\"ע תשסט. במדבר ח\"ב ע' תקלב. ח\"ג ע' א'רז וע' א'רכא. דברים ח\"א ע' קס. [ובהמ\"מ שנסמנו במקומות אלו]."],["643","114","<b>כמו שאין ערוך. . עונג המצומצם. . לגבי. . שבעצמות הנפש כמ\"ש במ\"א</b>: ראה לעיל ח\"א ע' קצח ואילך."]]],[1900420161,"<b>והנה</b> בחי' הפרסא המפסקת הזאת נק' גל עד שהוא כמו גל אבנים ממש שעשה לבן להפסיק מחיצה כו'. והענין הוא כידוע שהאותיות נק' אבנים להיותם בחי' דומם בלי התפשטות כלל, ואמנם אותיות הדיבור גם שהן בחי' דומם מ\"מ יוכל להאיר על ידן כל אור ושפע דחכמה שבמוח ומדות שבלב וכה\"ג להיותם מסודרים בסדר וצירופים מכוונים ע\"פ אופן השכל שיוכל להתלבש בהן שכל וחכ', אבל כאשר האותיות בלתי מסודרים ואין הפסק בין אות לאות כלל אזי האותיות מצד עצמן הם בחי' דבר מפסיק ומבדיל שמעלים לאור הגנוז בהן, כמו אותיות דחלומות שבלתי מסודרים או כאותיות הקמיעות שנעלם בהן השכל או הסוד כו'. וכך הוא בחי' הפרסא המפסקת הנ\"ל שנק' גל עד גל אבנים שאין סדר והפסק כלל בין אבן לאבן, כאבני הבנין שמונחים זה עג\"ז טרם שמסדרם לבנין (ומ\"ש בס\"י ה' אבנים<sup data-n=\"644\">115</sup> בונות ק\"ך בתים זהו כשמסדרם בצירופים שהן ק\"ך צירופי' כו'), וכמו\"כ אריגת הבגד שארוגה בחוטים זעג\"ז שאין חלל הפסק ביניהם כלל לא יוכל האור להאיר על ידו כ\"א ע\"י שינוי המהות בבחי' הארה דהארה מצומצמת שדוחק ועובר בין דקות הנקבים שבאריגה, וכן בגל אבנים עובר בצמצום במקומות מיוחדים כו', כבקיעת אור השמש בענן או בעלות השחר שיצא השמש ויבקע ברקיע כו' וכה\"ג שזהו נק' בקיעת האור דרך מסך כידוע, וכך הוא בגל האבנים המפסיק בדרך פרסא בין עצמות המאציל לנאצלים כנ\"ל וכמ\"ש והבדילה הפרכת כו' והיינו בין בחי' לובן העליון דתענוג הפשוט ליעקב בעל עולם האצי' אי אפשר שיאיר האור דעצמות המאציל כמו שהוא בבחי' א\"ס ממש בעולם האצי' כ\"א ע\"י צמצום ודילוג הערך מאד רק בבחי' הארה דהארה לבד, והוא מפני בחי' המסך המפסיק הזה שנק' גל עד (וכמו בחי' קרומא דאוירא המפסיק כנ\"ל), וכמ\"ש אם אני לא אעבור אליך כו' גם באתעדל\"ע שמצד עצמות המאציל כו' ואם אתה לא תעבור אלינו באתעדל\"ת מאצי' בהעלאה וביטול כו' רק ע\"י בחי' בקיעה שבוקע האור דעצמות התענוג הפשוט באור החכ' שמאין תמצא בדרך דילוג גדול והוא במזל ונוצר כו' בבחי' הארה דהארה לבד, כמו בנקבים הדקים שבאריגת המסך ובחללים קטנים שבגל אבנים וכבקיעת השמש ברקיע וכה\"ג, וכן יוכל לעלות האור דאצי' למעלה ע\"י בקיעה מלמטה למעלה שז\"ש אך יצא יצא יעקב אותיות יבקע וכמו אז יבקע<sup data-n=\"645\">116</sup> כשחר כו' וכמו בקיעת האור דרך בחי' קרום המפסיק בין הגלגלתא והמוחין כו' (כמו שיכולים נשמות דבריאה לעלות באצי' ומאצי' לבריאה כו' בגילוי הנבואה ורוה\"ק וגילוי שכינה כו' אע\"פ שמסך מפסיק בין אצי' לבריאה כמו שמסך שנק' פרסא מפסיק בין קודש לקדה\"ק בין החכ' להכתר כו').",[["644","115","<b>בס\"י ה' אבנים</b>: ס' יצירה פ\"ד מי\"ב."],["645","116","<b>אך יצא יצא יעקב אותיות יבקע וכמו אז יבקע</b>: תולדות כז, ל. ישעי' נח, ח. וראה בהנסמן לעיל סוף המאמר הקודם. וש\"נ."]]],[1900420162,"<b>אך</b> הנה ג\"ז הצמצום הגדול שבוקע ומאיר דרך המסך מעצמות המאציל ומאצי' לבריאה כו' זהו בא ג\"כ במדה ושיעור קצוב ע\"פ מאמר קו המדה שנק' משחתא<sup data-n=\"646\">117</sup> כו' שמודד כל מדידה וקצבה באור ושפע הנמשך מעצמות המאציל לאצילות (וכך עד רום המעלות גם מעצמות א\"ס בא\"ק ע\"י צמצום דקו\"ח שנק' קו המדה בכללות), וכמו מי מדד בשעלו מים בחי' מים עליונים שמעל לרקיע המפסיק כמ\"ש יהי רקיע<sup data-n=\"647\">118</sup> בתוך המים כו' כידוע בענין אמ\"ר אור מים רקיע<sup data-n=\"648\">119</sup> כו', והוא בחי' חכ' הקדומה שלפני ההשתל' שנמשך במדה לאבי\"ע כו' (וכמו\"כ ורוח אלקי' מרחפת ע\"פ המים עליונים והארץ היתה כו' ויאמר אלקים<sup data-n=\"649\">120</sup> יהי אור בדרך בקיעה מבחי' ההעלם וצמצום דחושך סתרו כו'), דאם לא כל המדה הזה לא הי' קיום למציאות ההשתל' דאבי\"ע מעצמות המאציל שהיו מתבטלי' ממציאותם לגמרי.\n<b>ואמנם</b> כ\"ז מה שאינו נמשך מבחי' לבן העליון רק ע\"י מחיצה דגל עד הנ\"ל, זהו רק לפי אופן הרצון הקדום באופן וסדר ההשתלשלות דאבי\"ע שכבר קדם בעצמות המאציל שיהי' ע\"פ מדה המצומצמת הזאת כו' שבאופן זה יהי' המשכה התמידי' מהעלם עצמות המאציל לנאצלים וא\"א שיומשך משם ביתר מכפי המדה הזאת כו', וכמו והחכ' מאין תמצא בדרך דילוג במזל ושערה מצומצמת בלבד כו', אבל הנה מלמעלה מסדר ואופן ההשתלשלות שעלה ברצה\"ק יוכל להיות בחי' המשכה והשפעה מעצמות התענוג הפשוט שבעצמו' הא\"ס כמו שהוא ביתר הרבה מכפי מדה זו דקו המדה, כי קמי' לא יסתיר ויעלים המסך הנק' פרסא כו' ויכול להאיר אור עצמותו כמו שהוא ממש גם ע\"י הסתר המסך הזה ולא יסתיר כלל וכלל כמו שלא הי' בחי' צמצום והסתר כלל וכלל והי' מאיר אורו להדיא שלא ע\"י צמצום דשערות בלי שינוי המהות כלל (כמו שיהי' בעוה\"ב שא' ולא יכנף עוד מוריך כו' וכן הנה אלקינו זה ממש כו') כך גם שהמסך מפסיק בוקע אורו להדיא על ידו דוקא ונק' לבוש של אור המאיר אור העצמות ולא לבוש המסתיר כלל, אדרבה האור דעצמות א\"ס ממש נמשך ובא להדיא בתוס' הבהקת האור כמו שהוא בעצם ממש על ידי לבוש זה, והוא לבוש דתורה אור כמ\"ש עוטה אור כשלמה<sup data-n=\"650\">121</sup> כו' וד\"ל.\n[יד] <b>וביאור</b> הענין הנה ידוע שיש הפרש גדול בין הרצון ותענוג להשתלשלות העולמות שהוא רק בבחי' החיצוני' אע\"פ שחפץ",[["646","117","<b>מאמר קו המדה שנק' משחתא</b>: ראה זח\"א טו, א. יח, ב. זח\"ב רלג, א. תקוני זהר ת\"ה בתחילתו. וראה ביאוה\"ז לאדהאמ\"צ נז, ד."],["647","118","<b>מי מדד. . יהי רקיע</b>: ישעי' מ, יב. בראשית א, ו."],["648","119","<b>כידוע בענין אמ\"ר אור מים רקיע</b>: ראה לעיל ד\"ה שמח תשמח (השני) אות יו\"ד. וש\"נ. זח\"ב קסז, א ואילך. ס' הערכים-חב\"ד כרך ג' ע' תא ואילך."],["649","120","<b>ורוח אלקי'. . והארץ היתה. . ויאמר אלקים</b>: ע\"פ בראשית א, ב-ג."],["650","121","<b>ולא יכנף. . הנה אלקינו. . עוטה אור כשלמה</b>: ישעי' ל, כ. כה, ט. תהלים קד, ב."]]],[1900420163,"חסד הוא בעצמות אין זה מבחי' פנימי' עצמותו כמו שהוא ממש, ובין הרצון ותענוג העצמי שבתו\"מ שהם עצם פנימי' רצונו וחכמתו כו' שכל עצמותו ממש כמו שהוא לאמיתתו מלובש בהן, ולזאת גם שהרצה\"ע דתו\"מ בא ג\"כ בבחי' אותיות וצמצומים בשיעור ומדה אין זה בחי' צמצום והסתר כלל, אדרבה בחי' אותיות הללו הם המגלים כל פנימית עצמותו שבהן ועל ידן יאיר אור עצמותו ממש לפי שהן בחי' אותיות עצמיי' כמו שמותיו העצמי' או לבוש שמאיר אור העצמות על ידו, משא\"כ בחי' אותיות וצמצומים שנמשך על ידן הרצון וחכ' למע\"ב הן בחי' הסתר וצמצום גמור (כמו בריש הורמנא כו' גליף גליפו<sup data-n=\"651\">122</sup> בטה\"ע שהן אותיות המצמצמים עצמות האור דא\"ס שיוכל לבא בהשתלשלות דקו\"ח להאציל ע\"ס כו' לאחזאה לאתנהגא בהון עלמין<sup data-n=\"652\">123</sup> כו', וכן מעילה לעילה הכל נמשך ע\"י הצמצום והסתר דאותיות שבעליון, כמו המשכת החכ' דאצי' מאין דכתר ע\"י מזל ונוצר כו' ע\"י הצמצום דפרסא שמפסיק בין כתר לחכמה (שנק' קרומא דאוירא כנ\"ל), וכן מחכמה לבינה שהוא ג\"כ מאין ליש ע\"י צמצום כו', כידוע הכלל דבחי' מל' שבעליון נעשה כתר לתחתון<sup data-n=\"653\">124</sup> כו', וכן מאצי' לבריאה ומבריאה ליצי' עד צמצום האחרון יותר דמל' דעשי' כו'. אך הנה בהשתלשלות דתומ\"צ אע\"פ שירד האור ג\"כ מעילה לעילה מעצמות א\"ס באבי\"ע עד תורה דעשי' הנגלית לנו באותיות גשמיי' ומעשה גשמי' אין בכ\"ז שום צמצום והסתר כלל מכמו שהתורה הי' כלולה במהו\"ע ית' ממש שהוא עצמו' ופנימי' רצונו וחכמתו ממש כמ\"ש ואהי' אצלו כו' שעשועי' עצמי' אע\"פ שירדה באותיות או בלבושים אין זה צמצום כלל אדרבה הן המגלים עצמות אורו, כמו במ\"ת דכתי' וידבר אלקים כו' הרי הי' כל עצמות התענוג והרצון שבעצמיות פנימיותו ממש מאיר באותיות הללו בלי שום לבוש והעלם וצמצום כלל וכלל כמ\"ש באור פניך ממש נתת לנו כו', לפי שחכמת התו' חכ' הפנימי' ורצון ותענוג העצמי יאיר באור פנימי' ועצמי' גם בהיותו מדבר באותיו' או מתלבש בלבוש נק' לבוש של אור ממש כנ\"ל, וכן עכשיו כל מי שקורא ושונה בדבר ה' קורא וממשיך לבחי' פנימי' ועצמות דא\"ס שהוא עצמו כמו שהוא קורא ושונה כנגדו כו' כמו במ\"ת שא' אנכי כו' בלי שום העלם וצמצום כלל, וזהו במצות קריאת התורה שנמשך האור דעצמות א\"ס בד\"ת מלמעלה למטה בגילוי אור דרך האותיות או הפרסא באין לבוש מסתיר, כי החכ' דתורה שמאין תמצא אינה באה בדרך דילוג וצמצום (אעפ\"י שא' הכל תלוי במזל<sup data-n=\"654\">125</sup> אפי' ס\"ת שבהיכל) אלא אדרבה כמו שהוא במקורה ממש באה מאין ליש באותיות",[["651","122","<b>בריש הורמנא כו' גליף גליפו</b>: זח\"א טו, א."],["652","123","<b>לאחזאה לאתנהגא בהון עלמין</b>: ע\"פ תקוני זהר בהקדמה ד\"ה פתח אליהו."],["653","124","<b>כידוע הכלל דבחי' מל' שבעליון נעשה כתר לתחתון</b>: ע\"ח שער עקודים (ש\"ו) פ\"ב. שער דרושי אבי\"ע (שמ\"ב) פ\"א."],["654","125","<b>הכל תלוי במזל</b>: זח\"ג קלד, א. וראה לעיל ח\"א ע' לג. ס' מאמרי אדה\"ז עה\"ת ח\"א ע' קכז [ובהמ\"מ]. מאמרי אדהאמ\"צ דברים ח\"א ע' רכט [ובהמ\"מ ]."]]],[1900420164,"הללו כו', וכן מאצי' לבריאה בגעה\"ע שלומדים התורה בדיבור ע\"י אותיות התורה הנגלית לנו כו' שקורא בשמותיו העצמיי' ממש כנ\"ל במ\"ש יקראוהו באמת כו', וכמ\"כ במצות עיון והגיון דדיוק בחכ' דתורה ע\"י ביטול והעלא' מיש לאין ממש ביגיעה רבה כנ\"ל ממשיך מהעלם דהעלם דעצמות המאציל שיבא לגילוי דהיינו מעצמות אור התענוג הפשוט דחכ' דתוה\"ק שנק' משל הקדמוני כו', שז\"ש יעשה למחכה לו בבחי' עדן דעוה\"ב שהוא מאיר מפנימי' העצמות בלי לבוש והעלם כלל כמ\"ש ולא יכנף עוד כו' והיו עיניך רואות כו', וגם שירד אור דתורה בלבוש ומשל, הכל בא לגילוי מעצמותו ממש המלובש בלבוש של אור הזה כו' (כמ\"ש בתורתו של ר\"מ הי' כתוב כתנות אור בא'<sup data-n=\"655\">126</sup> כי כל הדיוק במילין דחכ' הוא לברר ולתקן לעה\"ד שיהפך מחושך והעלם דתוהו לאור בבחי' או\"ח שהוא מחשמל העליון יהי' לבוש של אור דוקא כנ\"ל וד\"ל).\n<b>(ונמצא</b> שע\"י עסק התורה בב' אופנים דמצות קריאה בדיבור ומצות עיון ודיוק הנ\"ל נמשך כל בחי' עצמות אא\"ס באותיות התושב\"כ ובההלכות דתושבע\"פ כשקורא ושונה כמו שהוא בלי לבוש וצמצום כלל ולא דרך בקיעת האור במסך ופרסא הנ\"ל בבחי' הארה דהארה לבד אלא אדרבה בא האור להדיא בגילוי גמור כמו שהוא בעצם בין מלמעלה למטה בבחי' או\"י בקריאה בדיבור שמאיר בלבוש של אור וכן בצמצום דאותיות הרי אותיות הללו הם המגלים האור היפך הצמצום (ועד\"מ הקרום העליון המפסיק בין הגולגולת והמוחין שיומשך ממקור השכל הנעלם בגילוי גמור דרך הקרום דוקא בבחי' או\"י בחכם גדול שנמשך החכ' מאין ליש בלי העלם וצמצום כלל, וכן ביגיעת המוח בדיוק שעומד ומתעכב על הדבר בביטול ושממון בבחי' אין כנ\"ל שעובר דרך הקרום בהעלאה מלמטה למעלה בבחי' או\"ח כמו קשי ההבנה שממשיך ממקור השכל הנעלם לגילוי גמור, ואין זה נק' בקיעה אלא גילוי העצמו' באמצעות הלבוש הזך ובהיר כו', וכן בענין צמצום השערות הרי בא בגילוי המשכה עצמי' בלי צמצום והסתר כלל ממקור המוחין דוקא (כמשי\"ת).\n[טו] <b>וזהו</b> שערך כעדר העיזים שגלשו מהר הגלעד, פי' שערך הן הלכות דתושבע\"פ מל' קרינן לה שכל הלכה והלכה יש לה שרש המשכה מיוחדת כמו כל שערה שיש לה גומא מיוחדת ונק' נימין דמטרוניתא כו', כידוע בענין סלסלה ותרוממך<sup data-n=\"656\">127</sup> שסלסול זה הוא לברר וללבן ההלכות שלא יקשה ויבולבלו בדיבוק אלא כל א' על מקומו וכמו ורמינהו ומתרץ לא קשי'",[["655","126","<b>בתורתו של ר\"מ הי' כתוב כתנות אור בא'</b>: ראה ב\"ר פ\"כ, יב. זח\"א לו, ב. לעיל ח\"א ע' סו, ובהמ\"מ שם."],["656","127","<b>נימין דמטרוניתא כו' כידוע בענין סלסלה ותרוממך</b>: משלי ד, ח. וראה לקו\"ת שה\"ש ו, ג-ד. ס' מאמרי אדהאמ\"צ בראשית ע' תקכו. ויקרא ע' נג. קז. קטז. דברים ח\"ב ס\"ע תתקלד. להלן סוד\"ה לה\"ע שמחת חו\"כ (השני)."]]],[1900420165,"כו' שאז מתגלה עיקר עצם פנימי' רצה\"ע למעשה בהלכה ברורה בכל פרט ופרט, שעי\"ז דוקא תרוממך למעלה מן החכ' שהוא בבחי' פנימי' והכתר והוא פנימי' התענוג הפשוט שבמצות שנק' י\"ג חיורתא דגלגלתא שהוא מקום פנוי מן השערות כו' ששם מאיר מפנימי' ועצמי' דא\"ס ממש בלי לבוש וצמצום כלל. וזהו שערך שהן ההלכות דתושבע\"פ אעפ\"י שהן בבחי' צמצום והתחלקות כשערות ממש הרי הן כעדר העזים שגלשו מהר הגלעד כמו עדר העזים שעברו בהר הגלעד שנגלשו ונמרטו השערות שלהם והן מקורחים בלי שערות כלל כו'. והענין הוא דבחי' גלעד הוא גל עד הנ\"ל שהוא בחי' הפרסא המפסיק בין כתר דגלגלתא לח\"ס והוא כמו קרומא דאוירא כו' שבחי' התענוג הפשוט מסתלק שם ואינו מאיר רק דרך מסך זה בבחי' הארה דהארה לבד שנק' בקיעה כנ\"ל, אבל למעלה מן הפרסא הזאת והוא בבחי' עצם הגלגלתא בחי' כשב\"כ שהוא עצם התענוג הפשוט שבפנימי' רצה\"ע שבמצות כנ\"ל שם מאיר האור העצמי כמו שהוא ממש בלי שינוי המהות כדילוג דשערות כלל, והיינו כללות התרי\"ג מצות שהן בחי' י\"ג חיורתא דע\"י כו' שהוא בחי' לובן הפשוט שפנוי וחלק מן השערות כו' כמו שמאיר בפנים שהוא חלק מן השערות לגמרי להיותו בבחי' פנימי' ועצמיות (שהוא תיקון ואמת בתרין תפוחים שזהו עיקר הארת פנים די\"ג מדה\"ר שמלובשים בשערות כו' ואין אמת אלא תורה כמ\"ש תתן אמת ליעקב<sup data-n=\"657\">128</sup> כו' (כמ\"ש במ\"א).\n<b>וזהו</b> שערך כעדר העזים כו', דגם שהתו\"מ בא בבחי' צמצום והתחלקות כשערות בבחי' אותיות כמו וזרח משעיר למו כו' ואתא מרבבות<sup data-n=\"658\">129</sup> כו' באותיו' דתושב\"כ ובהלכות דתושבע\"פ כנ\"ל, מ\"מ הרי הן בלא צמצום והעלם כלל אדרבה פנימי' ועצמות ההמשכה מאור העצמות דתענוג ורצה\"ע נמשך על ידן כמ\"ש וזרח משעיר כו' ואתא כו', וע\"כ הן כמו עדר העזים שגלשו מהר הגלעד מלמעלה מבחי' הפרסא דגלעד הנ\"ל ששם השערות דעדר העזים נעשו מגולשים ומקורחים לגמרי לפי שהאור מאיר שם כמו שהוא לאמיתתו בלי העלם כלל עד שנגלשו השערו' ונקרחו שלא יצמצמו האור כלל, כי פי' גלישה זאת כמו מאן דגלש למטרוניתא<sup data-n=\"659\">130</sup> כו' שהוא להשיר השערות המעלימים ומצמצמים, כי יש יניקה לחיצוני' ממותרות השפע דשערות (כענין שער באשה ערוה כו' כמו בשערהא אחידן<sup data-n=\"660\">131</sup> כו'), אבל שערך באותיות דתורה מאירים גם הם",[["657","128","<b>תיקון ואמת בתרין תפוחים. . ואין אמת אלא תורה. . תתן אמת ליעקב</b>: ע\"ח שער א\"א (שי\"ג) פ\"ט. ירושלמי ר\"ה פ\"ג ה\"ח. מיכה ז, כ. וראה לקו\"ת מסעי צג, א ואילך [ובהנסמן בהמ\"מ לשם]. ובכ\"מ."],["658","129","<b>וזרח משעיר. . ואתא מרבבות</b>: ברכה לג, ב."],["659","130","<b>מאן דגלש למטרוניתא</b>: ע\"פ זח\"א ריז, א. וראה גם ס' מאמרי אדהאמ\"צ במדבר ח\"ד ע' א'שלז, ובהמ\"מ שם. ולהלן סוף אות כ'."],["660","131","<b>שער באשה ערוה. . בשערהא אחידן</b>: ברכות כד, א. זח\"ג ס, ב. וראה בהנסמן עוד בהמ\"מ בס' מאמרי אדהאמ\"צ במדבר שם."]]],[1900420166,"כמו שהיו נגלשו ונקרחו כי הן עצמן אור בלתי מעלים הארת אור העצמי' שאין מזה יניקה לחיצוני' כלל וכלל אדרבה עיקר אור עצמות הקדושה נמשך על ידן כמו ענין קדוש יהי' בכה\"ג היפך הלווים שצריך להעביר תער על כל בשרם להיותם מבחי' הגבורות כו' אבל אותיות התורה ניתנו באש שחורה ע\"ג אש לבנה<sup data-n=\"661\">132</sup> בהתכללות דתיקון דאמת כו' וד\"ל.\n[טז] <b>ולהבין</b> כ\"ז בתוס' ביאור למה בחי' אותיות דתורה שנק' שערך הן כמו שלמעלה מן הפרסא כו' שהאור בא שם בגילוי כמו שהוא ממש אחר שנתצמצם האור ביותר בהמשכה זו דמותרי מוחין שיונקת השערה כו'. הנה יש להקדים לזה ענין א' באופן אחר בענין מחיצה דגלעד הנ\"ל, והוא כמו שידוע דיש מחיצה שנק' פרסא מפסיק בין עצמות הכתר דאצי' לחכ' דאצי' למעלה כך יש בחי' פרסא מפסיק בין אצי' לבריאה (שהוא בחי' חשמ\"ל התחתון) שנק' מסך שעשוי ג\"כ כמו מחיצה מגל של אבנים שנק' גלעד דהיינו בחי' אותיות שהן בלתי מסודרים בצירופי' שיהיו למחיצה והפסק בין לבן ליעקב, אך בחי' גלעד העליון הוא הפסק בין לבן העליון דקדושה שהוא בחי' לובן דתענוג הפשוט העצמי בפנימי' בכתר דאצי' שהוא למעלה הרבה מבחי' יעקב בעל התיקון דאצי' כו', ע\"כ עשה לבן זה העליון הפסק בפרסא שלא יעבור האור דעצמות מעצמות המאציל לאצילות רק דרך בקיעת הפרסא שנק' גלעד כנ\"ל, אבל בבחי' פרסא זו שבין אצי' לבריאה נהפוך הוא שבחי' לבן למטה הרבה מבחי' יעקב דקדושה דאצי', והוא בחי' קליפת נוגה דבריאה שנק' לבן למטה בחי' חכ' דקליפה ארמי אובד אבי לנגד חכמה דקדושה כו' ואינה רוצה ליכלל ולעלות בקדושה האלקי' בבחי' יעקב דאצי' שהוא חכ' דאצי' שם מ\"ה כו', וע\"כ עשה מחיצה שנק' גל עד מגל אבנים שנק' מסך שלא יעבור אור מאצי' להיכלות דנוגה דבריאה ולא יעלה מהיכלות דק\"נ דבריאה לאצי' רק ע\"י בקיעה בצמצום דרך הפרסא הזאת לבד. וז\"ש אם אני לא אעבור אליך מנוגה דבריאה לאצי' ואתה לא תעבור אלי מבחי' יעקב דאצי' לא יתגלה בנוגה דבריאה כו' וד\"ל.\n<b>וביאור</b> הענין ידוע דאת זלע\"ז עשה האלקי', דכמו שיש ע\"ס דקדושה באצי' ובבריאה בחכ' ומדות כו', כך ע\"י צמצום האור במותרי השפע בחיצוניות הכלים דע\"ס דקדושה נמשך ונפל יניקה להיות בחי' כח\"ב תענוג ורצון וחו\"ב דקליפה בבחי' הפירוד מאלקות בחי' ישות וגסות כענין תענוגי עוה\"ז וחכמות חיצוני' כו', וזהו בחי' לבן דקליפה שלמטה מהפרסא שבין אצי' לבריאה שנפל מבחי' לבן העליון דקדושה, והיינו ענין שבה\"כ דתוהו שהוא בחי' ס\"ג שלמעלה משם מ\"ה שירד למטה בבחי' ב\"ן דנוג\"ה דבי\"ע כידוע. והנה",[["661","132","<b>באש שחורה ע\"ג אש לבנה</b>: ראה ירושלמי שקלים פ\"ו סה\"א. תנחומא ר\"פ בראשית. זח\"ג קלב, א. רש\"י ברכה לג, ב ושה\"ש ה, טז (ד\"ה שחורות)."]]],[1900420167,"כמו שמבואר בענין לבן העליון דקדושה שעשה מחיצה דגל עד הנ\"ל להפסק דהיינו שלא יצא האור מבחי' התענוג הפשוט ניצוצי' דקדושה שנק' צאן לבן העליון ביותר מכפי המדה לאצי', לפי שיעקב בעל עולם התיקון במקלו' אשר פצל כו' השיג הרבה אורות עליונים מעצמות התענוג העליון שנק' עקודים כו' להיות בריבוי התכללות דבחי' ברודים דתיקון כמ\"ש ויפרוץ האיש מאד עד שאמרו בני לבן מכל אשר לאבינו הציל יעקב את כל הכבוד הזה כו' (כמ\"ש במ\"א בפ' ויצא<sup data-n=\"662\">133</sup>), וכך יהי' לע\"ל שיומשכו נשמות חדשות מעצמות התענוג הפשוט בבחי' עדן העליון לאין שיעור (כנ\"ל בפי' עלמות אין מספר, וז\"ש והי' מספר כו', והוא ע\"י אמצעות בחי' התיקון דתומ\"צ דיעקב כמו בדיוק דחכ' דתושבע\"פ (כמשי\"ת), וכמ\"כ יובן בהיפך בטעם הפסק הפרסא שבין אצי' לבריאה שעשה לבן, ולמטה כנ\"ל היינו כדי שלא יתגלה מאורות עליוני' דחכ' דשם מ\"ה דאצי' למטה מטה גם בהיכלות דק\"נ דבי\"ע להעלותם ולבררם ליכלל בקדושה דאצי', כמו בבירור דחכ' בק\"נ דעשי' ותענוגי עוה\"ז החומריי' שמתבררים ועולים למעלה ע\"י תשובה ומע\"ט בדברים גשמי' כו', וכן לא יוכל לעלות באתעדל\"ת מלמטה למעלה מהיכלות דנוגה דבריאה לאצי' גם ניצוצות דקדושה שנפלו שם כנשמות הגבוהות דגרים שגייר אברהם ענר אשכול כו', וכנשמות ר\"ע ור\"מ ונשמת שמעי' ואבטליון, וכן בנביאים כעובדי' כו' וכה\"ג לא הי' התעוררות תשובה בבע\"ת כלל, וגם לא הי' יכול להיות גילוי אלקות מאצי' לבריאה בבהמ\"ק, וכגילוי הנבואה בנביאים וכן הנסים ונפלאות, שכ\"ז למעלה מכפי המדה דגל עד שהוא הפסק המסך שבין אצי' לבריאה שאין האור האלקי דאצילות בא רק בצמצום דבקיעת המסך רק בהארה דהארה לבד כנ\"ל (ובקי\"ס הי' בחי' התגלות אור דאצי' בבריאה או העלאה דנשמות דבריאה באצי'<sup data-n=\"663\">134</sup> שלא ע\"י מסך כלל, וכ\"ש במ\"ת שהי' גילוי עצמות א\"ס בא' אנכי בה\"ס בנוגה דעשי' בלי הסתר וצמצום כלל כמ\"ש וזרח משעיר כו', וא\"כ הרי מסך זה דלבן שלמטה הי' היפוך כל התומ\"צ שאינו רק העלאות דנוג\"ה בבירור העה\"ד לעלות למעלה ביחו\"ע דאצי' כו' ובחי' המשכות דאורות דאצי' למטה מטה כו').\n[יז] <b>וז\"ש</b> לבן דנוגה אם אני לא אעבור כו' שלא יעלה מנוגה דבריאה לאצילות רק ע\"י צמצום המסך הזה לפי שאינו חפץ לעלות בביטול אור האצי' כמו שהוא שלא יתבטל מגסותו כו', ואם אתה לא תעבור אלינו לבא בגילוי אור לברר ולתקן הרע דנוגה כו' שאם הי' יוצא האור דחכמה דאצי' כמו שהוא למטה גם חושך לא יחשיך ויהפך הכל לאור הקדושה האלקי' כו', רק ע\"י",[["662","133","<b>במקלו' אשר פצל. . ויפרוץ האיש מאד. . מכל אשר לאבינו. . במ\"א בפ' ויצא</b>: ויצא ל, לח. מג. לא, טז. ראה ד\"ה והי' העטופים — בס' שערי תשובה לאדהאמ\"צ ס, א ואילך."],["663","134","<b>ובקי\"ס. . דאצי' בבריאה או. . דבריאה באצי'</b>: ראה זח\"ב מח, ב. פע\"ח שער חהמ\"צ פ\"ח. סידור עם דא\"ח רפט, ד ואילך. ס' מאמרי אדה\"ז עה\"ת ח\"א ע' רנח. מאמרי אדהאמ\"צ ויקרא ח\"א ע' ריב ואילך וע' רנ ואילך. ובכ\"מ."]]],[1900420168,"צמצום ומדה בריחוק גדול דרך שערות לבד ע\"י בקיעת הגל הזה כנ\"ל וד\"ל. וכל זה עשה לבן שלמטה מפני היראה להבא מאחר שכבר ראה מה שהצליח יעקב דאצילות בעובדות שלו במקלות שהמשיך לבחי' שם מ\"ה דתיקון גם בצאן לבן דנוגה דבריאה והיפך חושך לאור ביתר מכפי המדה מאד וכמ\"ש מכל אשר לאבינו הציל כו', והשיג שלפ\"ע זה יוכל יעקב בעל התיקון לתקן ולהעלות הכל מנוגה דבריאה ויצירה לאצי' כמו שיהי' לע\"ל דכתי' אז אהפוך אל עמים<sup data-n=\"664\">135</sup> כו' שיובררו הכל כו' וד\"ל (ולפי אופן הראשון בפי' לבן העליון דעצמות התענוג הפשוט הי' המשכת העונג דעצמות בא בגילוי ההעלם מעדן העליון גם למטה בגעה\"ע וגעה\"ת מבלי לבוש והעלם כלל כמו בעוה\"ב ממש דכתי' ולא יכנף עוד כו', משא\"כ עכשיו אין הנשמות מקבלים עונג העליון דעדן כ\"א ע\"י ריבוי צמצומים והעלמות כנ\"ל, וגם זה ע\"י לבוש חשמ\"ל העליון שמסתיר האור לנשמות שלא יתבטלו ממציאותם כו', וגם גילוי אלקות מאצי' לבי\"ע גם למטה בעשי' הי' ביתר מכפי המדה ביותר עד שהי' נגלה כבוד ה' לכ\"ב כו' ולא לנביאים בלבד, וכמו שיהי' לע\"ל שכולם ידעו אותי וכמו בקי\"ס שראתה שפחה<sup data-n=\"665\">136</sup> כו' לפי שהי' האור דעצמות התענוג הפשוט שבעדן הקדום מאיר כמו שהוא לאצי' וכן מאצי' לבריאה ומבריאה ליצירה כו'). ולזאת עשה לבן ההפסק דגל עד הזה שזהו בחי' המסך שבין עצמות המאציל לנאצלים שלא יומשך משם רק בבחי' צמצום ודילוג גדול בבחי' בקיעה הנ\"ל כמו בשערות וכנ\"ל בענין והחכמה מאין כו', וכן מאצי' לבריאה כו' יבא ויומשך רק בצמצום ומדה בדילוג גדול, וזהו ע\"פ מאמר קו המדה שמודד במדידה וקצבה לכל אור ושפע מעצמות המאציל לאצילות וכן מאצי' לבי\"ע ולעשות הפסק בריחוק מקום ליניקת החיצוני' דנוגה שלא יקרבו לקבל יותר מכפי מדתם המצומצם ביותר מצירופים האחרונים דשם אלקים כידוע. וז\"ש אם אני לא אעבור אליך כו', ויתפרש בב' אופנים הנ\"ל בפי' לבן ויעקב הכל בצמצום דקו המדה שקץ שם לחושך דנוגה כו' כמו שעשה שיעור ומדה לאור דקדושה הנמשך מעצמותו לאצי' כו', דכ\"ז נכלל בשיעור ומדה א' ששיער ומדד בעצמו איך יהי' אופן ההמשכה מעצמותו באו\"כ דאבי\"ע כו' ואיך וכמה יהי' ריחוק מקום ליניקת החיצוני' דאת זה לעו\"ז כו' בבחי' נוגה דאבי\"ע כו', וזהו ענין ההפסק דגל עד הזה למעלה ולמטה שעי\"ז יהי' הליכות אור ושפע מצומצם בד' עולמות דאבי\"ע וביניקה דנוגה שלהם הכל במדה ושיעור קצוב לא יוסיף ולא יגרע לעולם וד\"ל.\n<b>אך</b> הנה כ\"ז אשר נעשה ע\"פ מאמר קו המדה שנמשך בחי' הקו הזה למדוד שיעור ומדה באופן ההשתלשלות בע\"ס או\"כ דאבי\"ע ולהיות מסך מבדיל בין המאציל לאצי' ומאצי' לבריאה כו' כנ\"ל, זה הי' בתחלת ההשתל' כשעלה",[["664","135","<b>אז אהפוך אל עמים</b>: צפני' ג, ט."],["665","136","<b>בקי\"ס שראתה שפחה</b>: מכילתא בשלח טו, ב. וראה שער האמונה פנ\"ד. ובכ\"מ."]]],[1900420169,"ברצונו הפשוט להאציל ולברוא כו' (וששיער בעצמו בכח מה שיהי' בפועל<sup data-n=\"666\">137</sup>, והן אותיות החקוקים דגליף גליפו בטה\"ע כו') וכמ\"ש מי מדד<sup data-n=\"667\">138</sup> כו' (וכמו במא' יהי אור יהי רקיע כו' הכל במדה וצמצום המדה דשם אלקים כמ\"ש בראשית ברא אלקים ושיתף עמו מדה\"ר שהוא שם הוי' כמ\"ש בסוף ביום עשות הוי' ואלקים<sup data-n=\"668\">139</sup> ארץ ושמים כו'). אך א\"כ י\"ל למה הוצרך לעשות למחיצה זאת דגלעד להפסיק האור שיבא במדה כנ\"ל אחר שכבר נעשה הכל ע\"פ קו המדה הרי לא יוסיף ולא יגרע לעולם כנ\"ל, ואם מפני שראה לבן ליעקב אשר עשה בתחבולותיו במקלות אשר פצל כו' בבחי' התיקון דשם מ\"ה להמשיך ריבוי אורות עליונים ביותר הרבה מכפי המדה הראשונה כנ\"ל (ולפי' הב' שהוא לבן התחתון דנוגה ראה ביעקב איש תם שהרבה לברר ולהעלות ע\"י מק\"נ כו' כנ\"ל), היא גופא קשיא איך הי' ביכולת יעקב גם שהוא בבחי' מ\"ה דחכמה דאצי' להוסיף על מדת הצמצום דקו המדה אחר שגם החכמה מאין תמצא ג\"כ בצמצום ומדה ממזל ונוצר כנ\"ל. ועוד י\"ל דהלא הגלעד הזה יעקב הוא שעשה בהסכמת לבן כשא' הבנות בנותי כו' נכרתה ברית כו' ויאמר יעקב לאחיו לקטו אבנים כו' ויעשו הגל ויאמר לבן עד הגל הזה<sup data-n=\"669\">140</sup> כו', ולמה עשה זה יעקב להסתיר לו הדרך והמבוא כמ\"ש לו כי נסתר איש מרעהו כו' אם אני כו', ומוכרח לומר שהגל הזה הי' לכריתת ברית אהבה דוקא כמ\"ש לו אם תענה את בנותי כו', ומ\"ש אם אני לא אעבור אליך כו' היינו לרעה אבל לטובה אדרבה יהי' להם חיבור זע\"ז ע\"י הגל הזה שנעשה לעד כמובן בפשט הכתובים וכמ\"ש וישבע יעקב כו'.\n[יח] <b>אך</b> הענין הוא דהפסק זה דגלעד עשה יעקב ע\"פ החכמה דשם מ\"ה דתורה דוקא, כי שרש יעקב דאצי' בקו האמצעי שהוא בחי' ת\"ת שמקורו בפנימית הכתר שלמעלה מהבדלת הפרסא כנ\"ל ששם מאיר עצמות האור דא\"ס בבחי' התענוג הפשוט בלי צמצום והעלם כלל כנ\"ל, אך עכ\"ז ניתן שיעור ומדה באופן המשכה פנימי' ועצמי' זו דתומ\"צ בקו המדה דתורה שכלולה מחו\"ג במ\"ע ול\"ת כו' בשיעורים וצמצומים כך וכך יהי' אופן המשכת העונג ורצה\"ע הפנימי במ\"ע וכך יהי' אופן העלאת הבירורים דתוהו מחושך דק\"נ בסו\"מ דל\"ת במדידה קצובה לא יוסיף ולא יגרע, כמ\"ש במ\"א בפי' איה סופר<sup data-n=\"670\">141</sup> איה שוקל כו' שהן אותיות התורה שבאים במספר ושוקל הכל במדה באופן העלאות והמשכות ביחו\"ע דמ\"ע רק כפי הצריך להיות בבחי' התיקון כמ\"ש",[["666","137","<b>וששיער עצמו בכח מה שיהי' בפועל</b>: ראה לעיל ד\"ה שמח תשמח (הראשון) אות י\"א."],["667","138","<b>מי מדד</b>: ישעי' מ, יב."],["668","139","<b>ושיתף עמו מדה\"ר. . ביום עשות ה' ואלקים</b>: ע\"פ בראשית ב, א. רש\"י שם א, א. ב\"ר פי\"ב, טו. וראה לעיל ח\"א ע' רנח, ובהמ\"מ שם."],["669","140","<b>הבנות בנותי. . עד הגל הזה</b>: ויצא לא, כג ואילך."],["670","141","<b>במ\"א בפי' איה סופר</b>: ישעי' לג, יח. וראה ס' מאמרי אדה\"ז נביאים ע' קכג [ובהמ\"מ לשם]. אמרי בינה ח\"ג קלא, ד [הוצאת קה\"ת, תשמ\"ה]. ס' מאמרי אדהאמ\"צ במדבר ח\"ד ע' א'תעב."]]],[1900420170,"לעשות לתקן<sup data-n=\"671\">143</sup>, וז\"ש מי מדד בשעלו מים דאורייתא<sup data-n=\"672\">142</sup> כו'. וזהו שירדה התורה בעה\"ד טו\"ר לתקן ע\"י ישראל במצות בפו\"מ, ואבות סימן לבנים<sup data-n=\"673\">144</sup> זהו שניתן ליעקב איש תם יושב אוהלים שרש התושב\"כ ושבע\"פ<sup data-n=\"674\">145</sup> שעשה הכל במדה ושיעור בעובדא דמקלות בצאן לבן העליון להביאם לגילוי אור בהתחלקות רבות והתכללות שונות בתוס' מרובה על עיקר המדה הראשונה שהי' בתחלת ההשתלשלות כשעלה ברצונו וחכמתו למע\"ב כו' (וכבר הי' התחלה מאברהם שא' לו לך לך מארצך מח\"ס להיות תוס' אור מן המאציל לאצילות ולעלות מבריאה לאצי' (כמ\"ש במ\"א<sup data-n=\"675\">146</sup>) ונוסף לו ה' ע\"י המילה להיות אב המון גוים לברר ולהעלות כל הניצוצים דקדושה שנפלו באוה\"ע ונתן לו הז' אומות ששרשם בז\"מ דתוהו כו', ואמנם יעקב גמר בחי' התיקון הזה בשלימות כפי בחי' שם מ\"ה דתורה דכתי' ויקם עדות ביעקב<sup data-n=\"676\">147</sup> ותורה שם בישראל דוקא, ולזה הי' גם הכוונה גם בקו המדה שבתחלת ההשתלשלות שהרי א' אם לא בריתי כו' חוקות שמים וארץ בקו המדה לא שמתי כו', וע\"כ א' בראשית בשביל התורה שנק' ראשית כמ\"ש ה' קנני ראשית דרכו ובשביל ישראל שנק' ראשית כשיקבלו התומ\"צ בה\"ס ותנאי<sup data-n=\"677\">148</sup> הי' וכו' שלפי אופן המדידה דשם מ\"ה דחכמה דתוה\"ק דוקא שנמשך בתו\"מ הנגלות לנו כך הי' אופן הרצון במע\"ב לא יוסיף ולא יגרע, וזהו שיעקב הוא שהוסיף על המדה ע\"פ התורה כנ\"ל שזהו שעלה במח' טרם שעלה ברצונו להאציל ולברוא כו', וגמר הדבר ממש הי' במ\"ת דכתי' ביום חתונתו כו' שחכמת אדם תאיר פניו בבחי' התכללות דחו\"ג דתורה כמ\"ש מימינו אש דת כו' באש שחורה ע\"ג אש לבנה במזיגה נכונה באופן שפנימי' ועצמות דא\"ס ממש מתלבש ושורה בזה (משא\"כ בקו המדה הראשונה בקו\"ח דגם שכלול מצמצום והתפשטות יחד ומודד כל מדה כו', זהו רק בחי' חיצוני' האור דעצמות א\"ס בשביל בנין העולמות לבד כי חפץ חסד הוא כו', אבל בהתכללות דחו\"ג דתו\"מ שורה כל עצמותו בזה כמו במ\"ת שא' אנכי כו', ואין זה הצמצום כשאר הצמצום אלא אדרבה בזה מתצמצם כל אמיתי' עצמותו כמו בגילוי שכינה בהיכל קד\"ק אע\"פ שהשמים ושה\"ש טה\"ת וטה\"ע לא יכלכלוהו, וכמ\"ש במצות דכתי' רחבה מצותך מאד ובתורה א' ארוכה מארץ",[["671","143","<b>לעשות לתקן</b>: ע\"פ בראשית ב, ג. וב\"ר פי\"א, ופרש\"י שם."],["672","142","<b>מי מדד בשעלו מים דאורייתא</b>: ראה גם ס' מאמרי אדהאמ\"צ נ\"ך ע' עא."],["673","144","<b>ואבות סימן לבנים</b>: ראה ב\"ר פמ\"ה, ז. רש\"י וירא יח, א. רמב\"ן לך יב, ג."],["674","145","<b>ליעקב איש תם יושב אוהלים שרש התושב\"כ ושבע\"פ</b>: ראה תולדות כה, כז. ב\"ר פס\"ג, יו\"ד. ס' מאמרי אדהאמ\"צ דברים ח\"א ע' וא\"ו, ובהמ\"מ שם."],["675","146","<b>לך לך מארצך. . כמ\"ש במ\"א</b>: ר\"פ לך לך. תו\"ח לך לך פ, א ואילך."],["676","147","<b>ויקם עדות ביעקב</b>: תהלים עח, ה."],["677","148","<b>אם לא בריתי. . בראשית בשביל התורה שנק' ראשית. . ה' קנני. . ותנאי</b>: ירמי' לג, כה. רש\"י ר\"פ בראשית. משלי ח, כב. שבת פח, א."]]],[1900420171,"מדה<sup data-n=\"678\">149</sup> ורחבה כו', וצמצם כל פנימית ועצמות רצונו וחכמתו בצמצום מעשה דמצות ובחכמה דתו' באותיות דתורה שבכתב ושבעל פה (כמשי\"ת).\n[יט] <b>ובזה</b> יובן משארז\"ל דבשעת מ\"ת החזיר ה' התורה על כל אומה ולשון ולא קבלוה, עשו אמר מה כתי' בה לא תרצח כו', וזהו וזרח משעיר<sup data-n=\"679\">150</sup> למו הופיע מהר פארן כו'. דהנה לפי כל הנ\"ל מובן בעיקר ירידת התורה למטה שהי' רק לתקן לעה\"ד טו\"ר במדה ושיעור כפי עצמות בעה\"ר ותענוג הפשוט כו' באופן הצריך להעלאות הבירורים דרפ\"ח כו' מק\"נ ובאופן המשכות דיחו\"ע במצות בגשמיות דנוגה כו' לא יוסיף ולא יגרע כמ\"ש כל אמרת אלוה צרופה<sup data-n=\"680\">151</sup> שנק' חכמה ברורה שכבר הוברר מקודם שעלה ברצונו להאציל כו', ולזאת ירדה למטה בשיעורים וצמצומי' דוקא, ואמנם שיעור וצמצום הזה הוא שמאיר בזה מפנימית ועצמות רצונו וחכמתו הקדומה, ולכך החזירה על עשו וישמעאל שהן בחי' חו\"ג דק\"נ אם יקבלו התורה עכשיו שיובררו כפי הצריך, וכפי שיהי' לע\"ל שיהפוך אל עמים כו', אמנם לא ניתנה להם התורה עכשיו שעדיין לא רצו בבירור מעצמם כ\"א ע\"י ישראל דוקא שהן בבחי' שם מ\"ה דחכמה דבחכמה אתברירו, והיינו בבחי' הת\"ת דיעקב שהוא התורה שנק' אמת כמ\"ש תתן אמת ליעקב דוקא, וז\"ש עשו מה כתי' בה לא תרצח כו' ובו נאמר על חרבך תחי'<sup data-n=\"681\">152</sup> כו', וע\"י ישראל מתברר מבחי' הגבורות הקשות דעשו ונהפך חושך לאור, וכן בבחי' חסד דקליפה דישמעאל בירורם ע\"י ישראל דוקא, וכמ\"ש במ\"א במ\"ש והייתם לי סגולה מכל העמים שמכל העמים שיבררו ישראל יהי' נק' סגולה בבחי' סגול העליון, וכמ\"ש אז יאמרו בגוים<sup data-n=\"682\">153</sup> דוקא הגדיל ה' לעשות עם אלה כו' לפי שיהי' ע\"י הבירור דק\"נ יתרון האור מן החושך שעי\"ז מאיר גם בחי' החשך וצמצום העליון בתוס' מרובה על עיקר האור כנודע. וזהו וזרח משעיר למו משעיר דעשו איש שעיר גבורות דקליפת נוגה כשיבורר ע\"פ אמת דחכמה דתורה זרח אור מן החושך העליון, וכן הופיע אור גדול יותר בחסד דק\"נ מהר פארן דישמעאל, ואתא מרבבות קודש העליון שהן ישראל אשר בך אתפאר<sup data-n=\"683\">154</sup> בפאר דת\"ת דתורה שיבא בתוס' אור בבחי' רבבות קודש, וזהו ואתא בבחי' אותיות וצמצומים דאותיות התורה שניתנה באש שחורה כו' דכד אתכפיא סט\"א<sup data-n=\"684\">155</sup> אסתלק יקרא דקוב\"ה כו'. אך כ\"ז ניתן במדה ושיעור ע\"פ החכ' הקדומה דתו' שז\"ש ואתא מרבבות קודש דחכ' הקדומה",[["678","149","<b>שהשמים ושה\"ש. . רחבה מצותך מאד. . ארוכה מארץ מדה</b>: מלכים-א ח, כז [ועוד]. תהלים קיט, צו. איוב יא, ט."],["679","150","<b>דבשעת מ\"ת החזיר. . וזרח משעיר</b>: ברכה לג, ב וספרי שם."],["680","151","<b>כל אמרת אלוה צרופה</b>: משלי ל, ה."],["681","152","<b>על חרבך תחי'</b>: תולדות כז, מ."],["682","153","<b>במ\"א במ\"ש והייתם לי סגולה. . אז יאמרו בגוים</b>: יתרו יט, ה. תהלים קכו, ב. ראה ס' מאמרי אדהאמ\"צ שמות ח\"א ע' קעג."],["683","154","<b>ישראל אשר בך אתפאר</b>: ישעי' מט, ג."],["684","155","<b>דכד אתכפיא סט\"א</b>: ראה זח\"ב קכח, ב. ובכ\"מ."]]],[1900420172,"כמ\"ש מי מדד כו' כנ\"ל, ולע\"ל יבוררו בשלימות, וכענין שאמר בתורתו של ר\"מ כתיב כתנות אור בא' בחי' זיהרא עילאה<sup data-n=\"685\">156</sup> כו' שלבוש החשמל לא יהי' כתנות עור בבחי' לבוש שק אלא לבוש של אור המאיר בתכלית ההבהקה והיינו באותיות התורה שא' עוטה אור כשלמה כנ\"ל וד\"ל (והיינו ע\"י ב' מצות דעיון התו' וקריאת התורה, דבעיון התורה בדיוק במילין דחכמה בהלכות דתושבע\"פ יעשה כל העלם העליון לגילוי ע\"י העלאה ובירור ביגיעת המוחין בבחי' או\"ח לברר וללבן הלכתא כו', וכן הלכה כמו הליכות אלי הליכות עולם<sup data-n=\"686\">157</sup>, והוא בבחי' צמצום דשער' בכל הלכה המשכת אור מיוחד מהעלם העצמות דכתר שבכתר שלמעלה מן הפרסא המפסיק, כידוע דבקיעת השערות יוצא ממקור המוחין שלא יכילו להיות בבחי' או\"פ כמו י\"ג ת\"ד כו'. וזהו וזרח משעיר למו כענין הנ\"ל בסלסלה ותרוממך כו', והוא מ\"ש שערך כעדר העזים דהיינו שערות דנוק' דוקא בתושבע\"פ דבינה יתירה ניתנה באשה יותר מבאיש להיות שמכוין לאמיתת הרצה\"ע לבא למעשה בכל פרטי' כנ\"ל. וזהו כעדר העזים לאחר הבירור דבחי' נוגה דעשו איש שעיר כו' שזהו בירור דחשמל דנוגה שעי\"ז יבא יתרון האור מחושך העליון דישת חושך סתרו כו', וגם זה במדה ושיעור וזהו בחי' התחלקות השערות כו', וע\"י מצות קריאת התורה באותיות דתורה שבכתב נמשך בחי' פנימי' ועצמות דתענוג הפשוט שבעצמות א\"ס שלמעלה מהפרסא כנ\"ל שיאיר אורו באותיות הללו, כענין דיבור אנכי כו' שזהו בבחי' המשכה דחסדים דאו\"י מלמעלה למטה בלי העלם כלל אלא כמו שהוא בעצם מתצמצם באותיות הללו כנ\"ל (לפי שזהו עיקר מעלת התו\"מ שגם שהאור מלובש בכלי כמו האותיות אין זה צמצום כלל ואין הכלי מסתיר לאור כלל להיותו בבחי' שם הוי' דבחי' הת\"ת דאו\"כ שוין כמ\"ש במ\"א<sup data-n=\"687\">158</sup>, וזהו ואתא מרבבות קודש דבחי' רבבות קודש העליון דחכמה דתוה\"ק בא באותיות בלתי מעלימים כלל וגם שהכל במדה ושיעור כנ\"ל. וז\"ש אז ראה ויספרה הכינה וגם חקרה במדה ושיעור קודם ההשתל' דקו\"ח ויאמר לאדם שהוא בחי' התיקון דתו\"מ הן יראת ה' היא חכמה כו' וכמ\"ש במ\"א<sup data-n=\"688\">159</sup> וד\"ל.\n<b>וזהו</b> ענין הגלעד שעשה יעקב ואחיו שיהי' חיבור וקשר דמאציל ונאצלים ונבראים ע\"פ החכמה דתורה שנק' אמת גם בבחי' הצמצום דאותיות ולא יסתיר כלל, ואמנם לא יעברו על המדה למעלה מכפי משפט ומשקל קו המדה דתורה. וז\"ש אם אני לא אעבור אליך כו' לרעה דוקא שלא יהי' עי\"ז גרעון אור",[["685","156","<b>בתורתו של ר\"מ. . זיהרא עילאה</b>: ראה לעיל אות י\"ד, ובהמ\"מ שם."],["686","157","<b>הליכות אלי הליכות עולם</b>: תהלים סח, כה. חבקוק ג, ו."],["687","158","<b>שם הוי' דבחי' הת\"ת דאו\"כ שוין כמ\"ש במ\"א</b>: ראה תו\"ח בראשית מא, ד. נח סד, ג. סה, א. ס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' תשסג. דברים ח\"ג ע' תשפד, ובהמ\"מ שם."],["688","159","<b>אז ראה ויספרה. . וכמ\"ש במ\"א</b>: איוב כח, כז-כח. וראה לעיל ד\"ה שמח תשמח (הראשון) אות ט\"ו, ובהמ\"מ שם."]]],[1900420173,"לשלוט בזה החיצוני' רק לטובה, והן ע\"י דרכים דתו\"מ הנק' ישרים בלי נטי' ימין ושמאל כי ישר ה' כו' בבחי' קו האמצעי שנמשך ע\"פ בחי' אמת דתורה ולא יוסיף להמשיך אור בחסדים דאו\"י דקו הימין ולא ירבה לעלות בהעלאה דגבורות בקו השמאל כו' וד\"ל).\n[כ] <b>וזהו</b> שערך כעדר העזים שגלשו מהר הגלעד, פי' שגלשו שנגלשו ונקרחו כאלו חלק ופנוי מן השערות כו'. דהנה סיבת גלישת השערות בא מתוקף חום השמש וזריחתו בהר גבוה מאד נעלה שלא יסבלו הצאן שם לבוש השערות מפני החום ויקרחו, ופי' הב' בגלישה זו ענין הבהקת אור ששערן מצהיב ומבהיק במראה לובן מפני תוקף אור זריחת השמש עליהם ונראים כחלקים בלתי שערות כלל כו' (עי' פרש\"י בשה\"ש<sup data-n=\"689\">160</sup>). ושניהם ענין א' לענין בחי' האותיות דתושב\"כ והעיקר באותיות דתושבע\"פ בהלכות שע\"ז א' שערך שנק' נימין דכלה כנ\"ל שזהו בדיוק במילין דחכמה לגלות רצה\"ע כמו שהוא לאמיתתו ממש כנ\"ל שמגיע בתענוג הפשוט שבגלגלתא שהוא עצם הרצון כמו שהוא בלי העלם ולבוש כלל, א\"כ בחי' שערות הללו הן מאירי' בבחי' לובן העליון בהבהקת אור כאילו נגלשו ונקרחו ואינם לבוש מסתיר כלל כשערות הראש המכסים על עצם הגלגלתא שנק' לבוש כלבוש המכסה על הגוף אלא הן מעצם הגולגלת ממש, כמו י\"ג חיוורתא דע\"י שפנוי מן השערות כך נראים חלקים לפי שמלאים אור וזיו מראה הלובן כו'. וזהו מאן דגליש למטרוניתא כו' שהוא בחי' מל' בהלכות שנק' כלה בכתר שבה לא יסתירו לבוש השערות שבגלגלתא ויתגלה מאור העצם הרצה\"ע כמו שהוא ממש בבחי' כתר עליון דא\"א וע\"י בפנימי' ועצמות התענוג הפשוט ששם עובר האור להדיא שלא ע\"י צמצום דשערות כלל כנ\"ל וד\"ל (ומ\"ש ושער רישי' כעמר נקי<sup data-n=\"690\">161</sup> כו' שהוא שערות הראש שבגלגלתא דא\"א כו', הנה באמת הרי יש אותיות בתושב\"כ והן בחי' חסדים דאו\"י דתענוג שלמעלה מן החכמה שמתצמצם בשערות הראש שהן כעמר נקי כו', והוא בקריאת התורה בדבור כנ\"ל, ומ\"ש שערך כעדר כו' זהו בשערות דגלגלתא דנוק' כו' שעולה בבחי' או\"ח בבירור דעה\"ד ע\"י הדיוק ועיון דתורה שנק' ליבון הלכתא שנעשו השערות לבנות כעדר העזים ששערן לבנות מבהיק, וכעדר הרחלים העולות מן הרחצה כו', וזהו שיעשה למחכה למאן דדייק כו' שיתגלה עי\"ז בחי' העדן דתענוג הפשוט בעוה\"ב שהן גילוי עצמות רצונו שבמצות (וז\"ש משמח חתן עם הכלה בשביל הכלה כנ\"ל), וזהו שגלשו מהר הגלעד מלמעלה מן הפרסא דגלעד הנ\"ל וד\"ל (ששם מאיר אור העצמו' דא\"ס שמחמת זה יאירו בהבהקת אור שלא ע\"י צמצום והעלם כלל",[["689","160","<b>ע' פרש\"י בשה\"ש</b>: שם עה\"פ (ד, א): שגלשו — שנקרחו, גבח מתרגם גלוש, כשהבהמות יורדות מן ההר נמצא ההר נקרח וממורט מהם. ע\"כ."],["690","161","<b>ושער רישי' כעמר נקי</b>: דניאל ז, ט."]]],[1900420174,"אע\"פ שהן בבחי' שערות כנ\"ל, והוא הגלעד שעשה יעקב ע\"פ בחי' קו המדה דאמת דתורה כנ\"ל.\n<b>ואמנם</b> יש עוד מדריגה שהיא למעלה גם מבחי' אמת דתורה, והוא ענין גילוי אור עצמו' הטוב ורב חסדו הפשוט שלמעלה מרצה\"ע וחכ' שבתומ\"צ, והוא כמו ביו\"כ שמרבה לסלוח ולמחול לעוברי רצונו שבתומ\"צ בי\"ג מדה\"ר ע\"י תשובה כו', וזהו שנמשך מבחי' רעוא דכל רעוין שבמצחא דע\"י כו' שמאיר בהארת פנים העליונים שלמעלה מתענוג ורצון דחכ' דתורה כו', והיינו כאשר לפרקים מתעורר עצמות המאציל להאיר ברוב חסדו וטובו הגדול בתוס' הארת פנים בהארה חדשה שלמעלה גם מכפי סדר הקצוב וקבוע ע\"פ משפט החכמה דתו' הקדומה, וזהו מבחי' שעשועי המלך בעצמו שלמעלה מעונג ושעשועים שבתו\"מ. וזהו מדריגה הב' דעוה\"ב שלמעלה גם משכר המצות בעונג ורצה\"ע שבהם כו' (וכמ\"ש ובשביעית כו' חנם בלא מצות<sup data-n=\"691\">162</sup>), וזהו ביו\"כ שנק' שבת שבתון מעין העוה\"ב ממש, וזהו שגלשו מהר הגלעד שנגלשו ממש בלי לבוש וצמצום דשערות כלל לפי שהוא למעלה מן הפרסא דגל עד הנ\"ל שעשה הפסק להיות במדה שע\"פ אמת דתורה, וביוכ\"פ הולך האור מעצמות השעשועים, ועכ\"ז עובר זה האור מרעוא דכ\"ר ונמשך בשערות, והן שערות די\"ג ת\"ד דכה\"ר כמ\"ש שיורד על הזקן<sup data-n=\"692\">163</sup> זקן אהרן כו' שנק' מדות הרחמים הגדולים בלי צמצום ומדה כלל וכלל גם לא בצמצום דאותיות התורה והלכות כו' אלא הן בחי' רחמים פשוטי' ועצמי' ע\"כ יש בכחם להיות נושא עון ועובר על פשע נגד משפט התורה כו'. וזהו שערך כעדר כו' היינו ע\"י בחי' או\"ח דבע\"ת דוקא שגדולים מצ\"ג בתומ\"צ שמעוררים המשכת י\"ג מדה\"ר שלמעלה מן התומ\"צ דתשובה קדמה לעולם יותר מתוה\"ק כמ\"ש במ\"א<sup data-n=\"693\">164</sup>, וזהו מאן דגליש כו' כמ\"ש במ\"א בענין וגלחה את ראשה<sup data-n=\"694\">165</sup> כו'. וזהו וזרח משעיר שעי\"ז ניתנה התו' וכמ\"ש תכלית חכ' תשומע\"ט<sup data-n=\"695\">166</sup> כו' וד\"ל.\n[כא] <b>ובכ\"ז</b> יובן ג\"כ ענין מ\"ש בזכרי' ועמדו רגליו ביום ההוא<sup data-n=\"696\">167</sup> על הר הזיתים אשר על פני ירושלים כו' ונבקע הר הזיתים מחציו מזרחה וימה גיא גדולה מאד ומש חצי ההר צפונה וחציו נגבה כו'. דהנה בדרך כלל נבואת",[["691","162","<b>ובשביעית. . חנם בלא מצות</b>: ראה לעיל אות ז. וש\"נ."],["692","163","<b>שיורד על הזקן</b>: תהלים קלג, ב."],["693","164","<b>דבע\"ת דוקא. . דתשובה קדמה לעולם. . כמ\"ש במ\"א</b>: ע\"פ ברכות לד, ב. פסחים נד, א. ראה ס' מאמרי אדה\"ז הקצרים ע' שכט. לקו\"ת דרושי ר\"ה ס, סע\"ד. ס' מאמרי אדהאמ\"צ בראשית ע' שדמ. דברים ח\"ד ע' א'קעט וע' א'קפח."],["694","165","<b>מאן דגליש כו' כמ\"ש במ\"א בענין וגלחה את ראשה</b>: ע\"פ זח\"א ריז, א. ס' מאמרי אדהאמ\"צ דברים ח\"ב ס\"ע תקלד ואילך. וראה לעיל סוף אות ט\"ו."],["695","166","<b>תכלית חכ' תשומע\"ט</b>: ברכות יז, א."],["696","167","<b>ועמדו רגליו ביום ההוא</b>: זכרי' יד, ד ואילך."]]],[1900420175,"זכרי' מדבר לע\"ל בעליות המל' בפנימי' הכתר שלמעלה מן החכ' שבראש, וז\"ש ועמדו רגליו על הר הזיתים כו' משום דנעוץ תחלתן בסופן דוקא, ובחי' הר הזיתים הוא בחי' חכמה שבמל' ח\"ת שמאיר בה מכ\"ע דכתר מל' איהו כ\"ע<sup data-n=\"697\">168</sup> כו'. ותחלה י\"ל מהו ענין הר הזיתים, להיות ידוע ששרש השמן זית הוא בבחי' החכמה והר הזיתים הוא מקום שבו גדל וצומח מקור התפשטות החכמה שהוא אילן זית כו' כמ\"ש והחכמה מאין תמצא<sup data-n=\"698\">169</sup> שתמצא מאין דכתר בבחי' צומח לבד כצמיחת הזיתים בהר שההר עצמו בחי' דומם דעפר שהוא העצם שלמעלה מבחי' התפשטו' וצמיחה, ומה שיש בדומם כח הצמיחה וההתפשטות כאילן הצומח מן הארץ זהו רק בחי' הצומח שבדומם שנכלל ובטל בגוף עצם הדומם, וע\"כ בירך על פרי העץ בורא פרי האדמה יצא משום דמארעא קא רבי כו' שענפי האילן היונקים בארץ מקבלים רק מכח הצומח שבארץ כצמיחת השערות בראש וגוף וכו' כמ\"ש במ\"א<sup data-n=\"699\">170</sup>. וכך יובן בענין גידול הזיתים דבחי' חכמה בהר הזיתים שאין גידול זה דחכ' באה רק מבחי' כח הצומח שבהר זה שהוא בחי' עצם הכתר עצמו שהוא למעלה הרבה מבחי' צומח שבו, ומה שצומח ומתפשט ממנו בחי' החכמה מאין ליש נכלל ובטל לגבי עצמות אור הכתר לפי שיש בכלל מאתיים מנה כו', וכמ\"ש במ\"א בענין סייג לחכמה שתיקה<sup data-n=\"700\">171</sup> שהשתיקה שהוא בחי' דומם הוא שנק' סייג לחכמה שאינו בגדר התפשטות דחכמה עדיין כו', וגם כאן מה שנק' הר הזיתים שבו צומחים הזיתים זהו רק בחי' צומח שבהר הדומם הזה מבחי' האחרונה שבו כו' (כמו ארץ מגדלת חכמים<sup data-n=\"701\">172</sup> שהוא מקום שמסוגל לגידול אנשים חכמים, ויש ארץ מגדלת אנשי מדות דוקא כידוע, ואע\"פ שמזל מחכים כידוע אמנם גם המזל העליון ששופע החכמה באדם תלוי לפי טבע האקלים שבארץ שמגדלת חכמים או טפשים כו', ויש בכל אקלים שינוי בגידול אופני החכמה בבנ\"א וכן בגידול המדות לטו\"ר, כמו גידול החיות ובהמות שיש שינויים גדולים במקומות הארץ, כי כל חלקי צוח\"מ כלולים בדומם שהכל הי' מן העפר<sup data-n=\"702\">173</sup> כו' לפי שבשרש דדצח\"מ בחי' הדומם למעלה מכולם וע\"כ כל חידוש מאין הכל בארץ דוקא לפי שנתחב\"ס דוקא כמ\"ש במ\"א<sup data-n=\"703\">174</sup>). ואנו רואים זה בנפש האדם שנק' נפש השכלית",[["697","168","<b>דכתר מל' איהו כ\"ע</b>: ע\"פ תקוני זהר בהקדמה ד\"ה פתח אליהו."],["698","169","<b>והחכמה מאין תמצא</b>: איוב כח, יב."],["699","170","<b>בירך על פרי העץ. . שענפי האילן. . כצמיחת השערות. . כמ\"ש במ\"א</b>: ברכות מ, א. ראה ס' מאמרי אדהאמ\"צ דברים ח\"ג ע' תתקו, וש\"נ."],["700","171","<b>במ\"א בענין סייג לחכמה שתיקה</b>: אבות פ\"ג מי\"ז. וראה ס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תרנט. תתסג. במדבר ח\"ב ע' שנט. שסא. שפד. תתעג. נ\"ך ע' שנח."],["701","172","<b>ארץ מגדלת חכמים</b>: ע\"פ זח\"א קכה, א [וזח\"ב ל, ריש ע\"ב]: אית מיא מגדלין חכימין ואית מיא מגדלין טפשין. ובבמדב\"ר פט\"ז, יב: יש ארץ שמגדלת גבורים כו'. [ונסמן בארוכה לכ\"מ בדא\"ח בהמ\"מ בס' מאמרי אדהאמ\"צ במדבר ח\"ד ע' א'תמט]."],["702","173","<b>שהכל הי' מן העפר</b>: קהלת ג, כ."],["703","174","<b>חידוש מאין בארץ דוקא לפי שנתחב\"ס דוקא כמ\"ש במ\"א</b>: ראה תו\"ח ויגש צא, א ואילך. ובכ\"מ."]]],[1900420176,"לפי שמשכלת כל שכל וחכמה, ובאמת התינוק שנולד אין בו שכל וחכמה כלל רק בגידולו בימים ושנים יצמח בנפשו כח השכל מעט מעט עד שיגדיל בשנים ויחכים ביותר, וא\"כ בעצם מהות נפשו הי' כלול כח צמיחה זו שצומח וגדל בכח השכל כל ימיו כי אין זה רק בחי' צומח שבעצם הנפש להיות צמיחה וגידול זה בכח השכל כו' שישכיל כל שכל מן ההעלם לגילוי, כי גם כח המשכיל שיש בנפש זהו כמו כח הצומח שיש בארץ לבד שבטל ונכלל בנפש עצמה שנק' יחידה כו', ולמעלה היינו בחי' חכמה שבכתר שיש הבדלה מפסקת ביניהם כנ\"ל בענין הפרסא שנק' גלעד כו', וז\"ש והחכמה מאין תמצא אפי' כח המשכיל שיצמיח ויוליד שכל מאין ממש תמצא ע\"י בחי' דילוג גדול רק בבחי' צומח לבד, והוא ענין דאור אבא יונק מן בחי' מזל ונוצר כידוע<sup data-n=\"704\">175</sup> וד\"ל. וזהו ענין צמיחת הזיתים בהר הזיתים ששם צומח מקור לחכ', ומה שנק' הר הזיתים לפי שגם בחי' צומח זה דהר הוא בחי' מדות שבכתר עצמו, כי גם בחי' הכתר עצמו כלול מחכמה ומדות כידוע, והיינו גם בעצם התענוג והרצון שלמעלה מן החכ' שמאין תמצא כנ\"ל שאין טעם לרצון ותענוג כלל אפי' טעם כמוס כו' רק רצון ותענוג פשוט ועצמי לבד יש בו חכ' ומדות, והוא מה שהרצון בעצם נוטה לחסד או לדין וכמו אהבה בתענוגים כידוע, שעי\"ז יבא ממילא מקור להתהוות גידול כח השכל מן ההעלם דכח המשכיל להשכיל לטוב וחסד כאב לבנו וכה\"ג, וכמו השוחד שיעור עיני חכמים כו' כמ\"ש במ\"א<sup data-n=\"705\">176</sup>. וזהו בחי' הר הזיתים שזהו רק בחי' צומח שבדומם דמדות חו\"ג שבעצמות התענוג ורצה\"פ שבדילוג גדול יהי' שם מקור ליניקת כח השכל שמאין תמצא בגידול וצמיחה בהתפשטות ממש כנ\"ל וד\"ל.\n[כב] <b>אך</b> הנה כ\"ז אינו רק כשהאור והשפע העליונה הולך בסדר והדרגה בהשתלשלות דעו\"ע מעליון לתחתון ע\"פ מאמר קו המדה כנ\"ל שאז א\"א שיאיר מעליון לתחתון שאין ערוך כלל ביניהם, כמו מבחי' עצם הרצון והתענוג הפשוט להיות מזה מקור למציאות התהוות החכמה מאין ליש כנ\"ל כ\"א ע\"י צמצום אור העצמו' דעליון ולא יאיר רק מבחי' האחרונה שבה שאינו רק צומח שבדומם וכה\"ג, וגם זה ע\"י בחי' הפסק שנק' פרסא כנ\"ל כמו הפסק גל אבנים שנק' גל עד הנ\"ל שמאיר דרך בקיעה לבד וכן דרך יניקה דשערות כמזל ונוצר שנק' מזל מחכים כו' כנ\"ל, וזהו עכשיו שהכל בא מלמעלה למטה בדרך השתלשלות דוקא כנ\"ל, אבל לע\"ל כתי' ועמדו רגליו ביום ההוא על הר הזיתים ונבקע הר הזיתים מחציו מזרחה כו', פי' ענין בקיעה זאת בדרך כלל היינו שלא יהי' עוד בגידול מקור החכמה מאין דכתר רק ע\"י בחי' כח הצומח",[["704","175","<b>דאור אבא יונק מן בחי' מזל ונוצר כידוע</b>: ע\"ח שער הכללים פ\"ה. ובכ\"מ. וראה לעיל ח\"א ע' לג, ובהמ\"מ שם."],["705","176","<b>וכמו השוחד שיעור עיני חכמים כו' כמ\"ש במ\"א</b>: שופטים טז, יט. ראה גם ס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' רטו [ובהמ\"מ שם]. ח\"ב ע' תרסב."]]],[1900420177,"שבדומם דהר לבד כנ\"ל (שזהו בא בדילוג הערך בשינוי המהות כצמיחת הגשם מן הרוחני ע\"י כח הצומח שבארץ שרוחניות דכח הצומח יורד בצמצום להיות מגדל הגשם הזה כגשם דחיות הדם מן חיות הנפש הרוחני' כו' כך גידול החכמה מאין, כמו ימים ידברו<sup data-n=\"706\">177</sup> ורוב שנים כו' שבכל יום יש התפשטות צמיחה זו בכח המשכיל להשכיל כו' שעי\"ז נמשך התהוות מציאות שכל בבחי' יש ודבר מה גם שיגדיל בחכמה ונק' זקן שקנה חכמה ממקורה ה\"ז באה מאין ליש ממש, ודוגמא לדבר בחכמה דמע\"ב דבראשית נמי מאמר הוא שיצא מהעלם דמקור החכמה מאין ליש ע\"כ יוכל להיות התהוות בריאה גשמי' מבחי' חכ' זו כמ\"ש כולם בחכמה עשית<sup data-n=\"707\">178</sup> כו' להיות באה בבחי' צמיחה דמזל העליון בשינוי המהות ע\"י הפרסא דבחי' הקרום כו' כנ\"ל), אבל בחי' בקיעה זו בהר הזיתים היינו ע\"י בקיעת אור העצמו' דתענוג ורצה\"פ כמו שהוא ממש למעלה גם ממקור לחכמה כנ\"ל יאיר בחכ' שלא ע\"י בחי' צמיחה והתפשטות ע\"י לבוש מסך ופרסא כלל וכלל שאז אין החכמה במציאות יש ודבר מה כלל בלי שינוי המהות מאחר שאינה באה בדרך השתלשלות עו\"ע בבחי' צמיחה מאין ליש כלל אלא גם החכ' הוא בבחי' אין דכתר עצמו ממש שהוא עצם התענוג ורצה\"פ שנבדל בערך מהיות מקור למציאו' מהות שכל והשגה כו' (ודוגמא לדבר מ\"ש וה' נתן חכמה לשלמה כו' הרי בחי' החכ' דא\"ס שנק' חכים ולא בחכ' ידיעא כו' דלתבונתו אין מספר כי הוא המדע<sup data-n=\"708\">179</sup> כו' בתורה הקדומה שכלולה בעצמות א\"ס ממש הוא שנמשך כמו שהוא בנשמת שלמה, כענין שיהי' במשיח דכתי' בי' ישכיל עבדי<sup data-n=\"709\">180</sup> ירום ונשא כו' שהוא בבחי' חכמה דעצמות אור פנימיות הכתר שהוא בבחי' אין ממש שבאה למטה בלי צמצום והעלם כלל שאין פרסא מפסיק כלל להיות באה בדרך השתל' עו\"ע מבחי' האחרונה שבעליון כו', אלא כמו שהיא למעלה בעליון בעצמות המאציל באה למטה בתחתון באצי' ממש, וכך בענין הארת אור האצי' בבריאה כמו שהוא באצי' בלי הבדלת מסך כלל, כענין גילוי הנבואה האלקית בנביאים וכמו ויאצל מן הרוח<sup data-n=\"710\">181</sup> דמשה ממש כמו שהוא בזקנים שלא ע\"י העלם וצמצום הנק' הארה דהארה כו' (ודוגמא לענין החכ' שבבחי' אין כמו שהיא למעלה ממש זהו שמצינו גם בדורות האחרוני' כמ\"ש בשבחי האריז\"ל שהי' רואה חכמה האלקית",[["706","177","<b>ימים ידברו</b>: איוב לב, ז."],["707","178","<b>דבראשית נמי מאמר הוא. . כולם בחכמה עשית</b>: ר\"ה לב, א. תהלים קד, כד."],["708","179","<b>וה' נתן חכמה לשלמה. . חכים ולא בחכ' ידיעא. . דלתבונתו אין מספר כי הוא המדע</b>: מלכים-א ה, כו. תקוני זהר בהקדמה ד\"ה פתח אליהו. תהלים קמז, ה. רמב\"ם הל' יסוה\"ת פ\"ב ה\"י."],["709","180","<b>ישכיל עבדי</b>: ישעי' נב, יג."],["710","181","<b>ויאצל מן הרוח</b>: בהעלותך יא, כה."]]],[1900420178,"בחלום ברגע א' מה שהי' צריך להביא בכתב ובדיבור כמה שנים<sup data-n=\"711\">182</sup> כו', וכמו בהשגת ברזא דחכמה שהי' ברשב\"י ותלמידיו בפרצופים העליונים כמו בי\"ג ת\"ד דא\"א שא' לר' חזקי' נושא עון חמית<sup data-n=\"712\">183</sup> כו' וזהו לשון אסתכלנא ברזא דחכמתא שזהו בחכמה שבבחי' אין ממש כו' כמ\"ש במ\"א<sup data-n=\"713\">184</sup>). וזהו שבימות המשיח נאמר ולא ילמדו עוד איש את רעהו כי כולם ידעו אותי כו', דענין הלימוד לא שייך רק בבחי' החכ' הבאה מאין ליש בדרך גידול וצמיחה ממהות למהות שיש בזה חילוקי מדריגות בקטנות וגדלות וראשי אלפי ישראל הן המשפיעים לקטני' כו', אבל בבחי' החכמה כמו שהיא בבחי' אין דכתר עצמו שלא ע\"י העלם וצמצום כלל שם שוין קטן וגדול שכולם ידעו אותי בשוה ממש, כמ\"ש ומלאה הארץ<sup data-n=\"714\">185</sup> כו'), וכמו\"כ כבר הי' במ\"ת בהגלות נגלות מאור עצמות א\"ס ב\"ה בבחי' גילוי התענוג הפשוט העצמי בדיבור דאנכי כו' שזה הי' התגלות אור עצמות הכתר כמו שהוא בחכ' דיו\"ד הדברות כו' בלי צמצום והעלם כלל דהיינו למעלה מבחי' הפרסא שאינו מאיר רק ע\"י צמצום דקו המדה כו' אלא כמו שהאור בעצמות ממש בא לגילוי וע\"כ קיבלו כולם כאיש א' מאור פנימי' ועצמות התענוג בחכ' שבדיבור עד שעל כל דיבור כו', ועד\"ז יהי' למעלה יותר והוא בגילוי השעשועי' העצמי' דעצמות א\"ס ממש שנק' עדן העליון שלמעלה גם מהתלבשות בחכמה בדיבור, והוא העוה\"ב שיעשה למחכה לו אחרי ימוהמ\"ש כידוע, שגם בחי' גילוי זה דעצמות השעשועי' לא יבא ע\"י צמצום והעלם בדרך עו\"ע משפיע ומקבל מאין ליש שאינו בא רק מבחי' האחרונה שבעליון לבד כנ\"ל, אלא כמו שהוא בעצמות ממש יתגלה בנשמות כמ\"ש להנחיל אוהבי יש מבחי' יש האמיתי כו' בלי מסך מפסיק כלל וכמ\"ש ולא יכנף<sup data-n=\"715\">186</sup> עוד כו' (וזהו ב\"פ אהי' אשר אהי' אנא זמין לאתגלאה<sup data-n=\"716\">187</sup> כו' כמו שהוא בעצמות ממש א' בימוהמ\"ש בחכמה והב' בעדן דעוה\"ב כו'). וכמו\"כ בדוגמא זו יש גם עכשיו בכל מי שקורא ושונה במצות לימוד התורה בדיבור שקורא וממשיך לבחי' עצמות התענוג הפשוט מעצמות הרצה\"פ שלמעלה מהבדלת הפרסא כנ\"ל באותיות התורה כמו שהוא בעצם דוקא בלי מסך מבדיל כלל",[["711","182","<b>כמ\"ש בשבחי האריז\"ל. . שהי' רואה. . ברגע א'. . בכתב ובדיבור כמה שנים</b>: פע\"ח שער ק\"ש שעל המטה פ\"א. שם הלשון: ”אם הייתי דורש פ' שנים רצופים כו' איני יכול להשלים\". אמנם בכ\"מ מובא הלשון ”לכתוב פ' שנה\" — ראה סה\"מ הנחות הר\"פ ע' קו. סה\"מ תקס\"ד ע' רג. תו\"ח שמות קצג, סע\"ב. שער האמונה ע' 185. ס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' שכט. דברים ח\"א ע' קמח. אוה\"ת ואתחנן ע' ס. ולכללות הענין ראה גם לקו\"ת צו יז, ב (ובהמ\"מ שם — הוצאת ה'תשד\"מ). אמור לט, ג. ואתחנן ג, ג. שמע\"צ פה, ד. ברכה צה, ב. סה\"מ תש\"א ע' 133. ובכ\"מ."],["712","183","<b>שא' לר' חזקי' נושא עון חמית</b>: זח\"ג קלב, ב: קם ר\"ח ואמר כו' מסתכל הוינא וארו חמית נהורא יקירא דבוצינא עלאה נהיר וסליק לשכ\"ה עיבר כו' פתחו ואמרו נושא עון חמיתא כו'."],["713","184","<b>אסתכלנא ברזא דחכמתא. . כמ\"ש במ\"א</b>: מובא בכ\"מ בשם הזוהר, ראה סה\"מ תקס\"ה ח\"א ע' רסה. ס' מאמרי אדהאמ\"צ שמות ח\"ב ע' תלז וע' תקמט. ויקרא ח\"א ע' שכט. במדבר ח\"ב ע' תרמז. דברים ח\"א ע' קמח וע' רסא. ועוד."],["714","185","<b>ולא ילמדו עוד. . ומלאה הארץ</b>: ירמי' לא, לג. ישעי' יא, ט [וראה בהמ\"מ לעיל ח\"א ע' קנו]."],["715","186","<b>להנחיל אוהבי יש. . ולא יכנף</b>: משלי ח, כא. ישעי' ל, כ."],["716","187","<b>אהי' אשר אהי' אנא זמין לאתגלאה</b>: שמות ג, יד. ראה זח\"ג יא, א־ סה, ב. ומפרשי הזהר שם. פרדס שער השמות (ש\"כ) פ\"א. לעיל ח\"א ע' רלט."]]],[1900420179,"כמו שהי' במ\"ת ממש כנ\"ל, וכמ\"ש דוד אני תורתך שעשעתי<sup data-n=\"717\">188</sup> כו', וכמו שיהי' התגלות עצמות התענוג דפנימית הכתר בחכמה כמו שהוא בלי מסך בימוהמ\"ש שיתגלו אז טעמי התומ\"צ (ואין הכוונה בטעם לרצון שבשכל מושג מאין ליש אפי' לא טעם כמוס שנק' ח\"ס כו', אלא הכוונה הוא בשרש החכמה שבעצמות הכתר כמו שהוא עדיין בבחי' אין ממש למעלה מבחי' התפשטות וצמיחה כנ\"ל), וכן במצות עיון ודיוק דתורה שיגיע למעלה יותר, והוא בבחי' עדן עצמו שלמעלה גם מעונג שבחכמה והוא בעצמות בעל הרצון הפשוט שז\"ש יעשה למחכה לו למאן דדייק במלין דאורייתא מטעם הנ\"ל וד\"ל.\n[כג] <b>וזהו</b> ועמדו רגליו כו' על הר הזיתים ונבקע ההר מחציו מזרחה וימה כו', שזה יהי' לעתיד דוקא בהגלות נגלות אור פנימית ועצמו' המאציל עצמו כמו שהוא שלא ע\"י בחי' פרסא מפסקת כלל, והיינו שלא יהי' המשכת החכמה מבחי' צומח שבדומם דהר הזיתים כפי סדר ההשתלשלות דחכ' מאין ליש כנ\"ל אלא יהי' בקיעת ההר עצמו מחציו מזרחה כו' מפני שיאיר בו מעצמות התענוג הפשוט כמו שהוא ממש כנ\"ל וד\"ל.\n<b>אך</b> הנה עדיין י\"ל מה שהי' סיבת בקיעת הר הזיתים הזה ע\"י שעמדו רגליו דוקא על הר הזיתים מהו ענין עמידה זו ברגליו ולמה על הר הזיתים דוקא וביום ההוא דמשמע לע\"ל דוקא. והנה הענין הוא כנ\"ל בב' מדריגות דמצות קריאת התורה ומצות עיון כו' דבקריאת התורה נמשך מעצמות התענוג הפשוט בחכמה בלי מסך כלל כו' הנה זהו בבחי' ע\"ס דאו\"י מלמעלה למטה כנ\"ל שמאיר מפנימית הכתר כמו שהוא בחכמה בראש בלי העלם דפרסא דקרומא כו' וממילא כשנתגלה הארת אור העצמו' במאציל בראשית דחכ' דאצי' מפנימי' הכתר כמו שהוא כך האור הולך מחכמה לבינה ומבינה למדות עד שגם במל' דאצי' בחי' הדבור העליון שנק' חכמה בסוף נמשך האור מבחי' פנימית כתר מל' דאצילות בבריאה כמו שהוא בלי מסך כלל עד סוף העשי' שיאיר גם חושך דק\"נ דעשי' דהא בהא תלי' דנעוץ תחילתן בסופן וסופן בתחילתן דכאשר בחי' החכמה בראש מאיר בבחי' אין דכתר דאצי' כך הוא יורד למטה בחכ' שבדיבור בלי העלם דמסך כלל, וכמו שהי' במ\"ת בגילוי עצמות התענוג דפנימי' הכתר דאנכי מי שאנכי בלי העלם גם בחכ' שבדיבור כמ\"ש וידבר אלקי' כו' וכתי' קול ה' בכח כו' חוצב כו' עד שירד האור בע' שרים דנוגה דעשי' לבררם כמ\"ש קול ה' יחיל מדבר היינו מדבר העמים דק\"נ וכמ\"ש וזרח משעיר<sup data-n=\"718\">189</sup> כו' לתקן לעה\"ד בל\"ת ומ\"ע בגשמיות בלא תרצח כו' וזה",[["717","188","<b>אני תורתך שעשעתי</b>: תהלים קיט, ע ואילך."],["718","189","<b>וידבר אלקי'. . קול ה' בכח. . חוצב. . יחיל מדבר. . וזרח משעיר</b>: יתרו כ, א. תהלים כט, ד ואילך. ברכה לג, ב."]]],[1900420180,"הי' הירידה דשם הוי' דעצמות א\"ס בה\"ס עד שעשן כולו וכמא' בהגלותך מלכנו על הר סיני גם בריות כו' שהן בחי' נוגה דעשי' חרדו כו' וכן גם עכשיו כשקורא בדבור דדבריו חיים כו' מהפך גם חושך דק\"נ לאור כמו בן עזאי שהי' אש לוהטת סביבו<sup data-n=\"719\">191</sup> בדברו בד\"ת כו' וז\"ש ועמדו רגליו ביום ההוא שזהו בתשלום הבירורים דעה\"ד גם למטה בסוף העשי' שהוא בבחי' רגל כמ\"ש הארץ הדום רגלי (דהיינו בחי' עקב דא\"ק שמסתיים בסוף העשי'<sup data-n=\"720\">192</sup>) כמו במ\"ת שירד על ה\"ס<sup data-n=\"721\">190</sup> במדבר העמים שהארץ האירה מכבודו כנ\"ל. אך לע\"ל בשלימות הבירורים דע' שרים דנוגה דעשי' אז יעמדו רגליו על הר הזיתים דוקא שהוא בחי' חכמה שבמל' ח\"ת, שבח\"ת דתושבע\"פ אתברירו בבחי' או\"ח מלמטה למעלה (כמ\"ש עד דמטו רגלין ברגלין<sup data-n=\"722\">193</sup> דדכר בנוק' כו') שזהו ע\"י מצות העיון דתורה שמדייק במילין דחכמה לידע נקודת אמיתי' הרצה\"ע למעשה בבחי' ביטול ההשגה והטעם לרצון אפי' טעם כמוס כו' שעי\"ז מגיע לבחי' העדן עצמו שלמעלה מעונג הנמשך בחכ' שז\"ש יעשה למחכה לו בעוה\"ב כנ\"ל. אז ונבקע הר הזיתים דהיינו שיהי' בבחי' ביטול דחכ' הצומח מהר זה להיות מקבל מעצמות התענוג הפשוט עצמו שלמעלה מהתלבשות גם בחכמה, וזהו יתרון מעלה מירידה בה\"ס בחכ' שבדבור שהוא בבחי' או\"י דנעוץ תחב\"ס אבל עמידה זו ברגליו על הר הזיתים שהוא נבקע עי\"ז בבחי' או\"ח דסב\"ת מגיע למעלה יותר שהוא בשעשועי' העצמי' ממש ע\"כ יבוטל כל ההר דהיינו גם מקור דחכמה שבמל' למעלה ויהי' גיא גדולה מאד שהוא בחי' עומק תחת שנמשך מעומק רום<sup data-n=\"723\">194</sup> כמו בעוה\"ב שיהי' התגלות עצמות א\"ס ממש למטה כמו שהוא למעלה ממש בשוה לפי שסוף מעשה עלה במח\"ת עד שיהי' למעלה ולמטה בשוה וע\"כ א' דעתידי' לומר קדוש<sup data-n=\"724\">195</sup> לפני צדיקים דהיינו לפי שיהי' גילוי עצמות א\"ס למטה בנשמות הצדיקי' ע\"י תומ\"צ שלהם כמו שהוא קדוש למעלה בשוה ממש כו' והוא מקיף דטה\"ע שמקיף לקו וחוט מראשו לסופו כא' עד שמקור האצי' וסוף העשי' שוין מבלי שימצא ראש וסוף כלל אחר שהאור דא\"ס עצמו מאיר בלי העלם וצמצום הראשון דקו המדה כלל הרי מאיר באצי' ועשי' בשוה והוא וי\"ו דקדוש כמו שהוא למעלה במוה\"ע כך הוא למטה בגילוי בצדיקים כו' וד\"ל. וזהו ונבקע הר הזיתים מחציו מזרחה וימה שהביקוע הזה יהי' לאורך מן המזרח למערב מח\"ע דראש בח\"ת בסוף בלי העלם כלל והגיא ביניהם בין צפון ודרום שהן ב' קוין לבד שמעצמות הרצון שלמעלה מן החכמה לגמרי ואח\"כ ומש חצי ההר צפונה",[["719","191","<b>בן עזאי שהי' אש לוהטת סביביו</b>: ויק\"ר פט\"ז, ד."],["720","192","<b>הארץ הדום רגלי. . עקב דא\"ק שמסתיים בסוף העשי'</b>: ישעי' סו, א. ע\"ח דרוש עגולים ויושר (ש\"א) ענף ד'."],["721","190","<b>בהגלותך מלכנו על ה\"ס</b>: נוסח ברכת שופרות במוסף דר\"ה."],["722","193","<b>עד דמטו רגלין ברגלין</b>: ראה זח\"ב רנח, א ובמק\"מ שם. ובהנסמן עוד בס' מאמרי אדהאמ\"צ שמות ח\"ב ע' תקד. ויקרא ח\"א ע' תתמה. במדבר ח\"ה ע' א'תתלה. דברים ח\"א ע' עז."],["723","194","<b>עומק תחת. . עומק רום</b>: ס' יצירה פ\"א מ\"ה."],["724","195","<b>דעתידי' לומר קדוש</b>: ב\"ב עד, א."]]],[1900420181,"וחציו נגבה שיומשך לצפון ודרום וינוסו שם מפני הרעש כמו שמסיים ואז יסתם הגיא ובא ה' אלקי' וכל קדושים עמך כו' שזהו אחר מלחמת גוג שיהי' תחה\"מ ועוה\"ב שיהי' בגילוי למטה כמו למעלה ממש כנ\"ל, שזהו רק מצד עליות המל' בפנימי' הכתר שע\"ז עיקר נבואת זכרי' בכל דבריו שדיבר רק בשם ה' צבאות כידוע ומבואר במ\"א<sup data-n=\"725\">196</sup> וד\"ל וכמ\"ש לעת ערב יהי' אור כו' ויצאו מים חיים<sup data-n=\"726\">197</sup> מירושלים אל הים כו' (כמשי\"ת).\n[כד] <b>ובכל</b> הנ\"ל יובן בתוספת ביאור יותר ענין ההפרש בשתי ברכות האחרונות בין משמח חו\"כ ובין משמח חתן עם הכלה כנ\"ל, דהנה הגם שמבואר למעלה שבהגלות נגלות מבחי' פנימי' התענוג הפשוט שבעצמות המאציל כמו שהוא אזי יבא האור והשפע גם בחכמה מאין דכתר שלא ע\"י צמצום ולבוש דפרסא כלל והיינו ע\"י מצות קריאה ומצות עיון בתורה (שהן בחי' או\"י ואו\"ח כנ\"ל) וכמו שהי' במ\"ת שהי' בבחי' גילוי אור העצמות ע\"כ חכמת אדם תאיר פניו בפנימית דחכמה כמו שהיא בעצמות התענוג הפשוט וז\"ש ביום חתונתו זו מ\"ת<sup data-n=\"727\">198</sup> שנק' חתן משפיע למקבל שהוא בחי' חכמה דתורה שנק' כלה שמאין דכתר תמצא בלי העלם ולבוש כו' כנ\"ל, וכך יהי' בעדן עצמו בעוה\"ב כו', אך הנה באמת היא גופא י\"ל מאיזה סיבה הי' זה הגילוי דבחי' פנימי' ועצמות התענוג מן ההעלם שבעצמות שנק' סדכ\"ס כו' דודאי א\"א לומר שע\"י הדבור לבד באמרו אנכי כו' וכן ע\"י קריאת האדם בדיבור דתורה היא שנעשה גילוי זה הפנימי' והעצמות דמהיכן יש כח באותיות הדיבור לעשות זה כו' ומהו הגורם לבא לדיבור זה שהוא ענין התגלות מן ההעלם כו'.\n<b>אך</b> הענין הוא דעיקר סיבת התגלות אור התענוג העצמי' אינו בא רק ע\"י השמחה דוקא דהשמחה הוא הגורם להיות התגלות עונג הנעלם הפנימי' שיבא גם בדבור בלי העלם ולבוש כלל כמ\"ש ביום חתונתו וביום שמחת לבו דוקא שזהו הנק' שמחת חתן ושמחת כלה דבשמחת לבו הי' סיבת התגלות אור שפע העצמו' בחכמה דתורה כנ\"ל לפי שיש בכח השמחה להביא כל פנימי' אור העצמו' דתענוג הסתום ונעלם בעצמות שיבא לגילוי למקבל כמו שהוא ממש בלי לבוש והעלם כלל כנ\"ל וד\"ל.\n<b>וזהו</b> לכאורה אינו מובן דהלא ידוע שעיקר סיבת השפע דמשפיע למקבל אינו רק מצד בחי' התענוג הפשוט שיש בזה כמו להשפיע חכ' דיותר משהעגל כו' וא\"כ העיקר הוא זה העונג שיש בטבע כל משפיע ולזאת למה צריך לשמחה דוקא שנק' שמחת חתן כנ\"ל. ועוד דהלא משמע שהשמחה",[["725","196","<b>שע\"ז עיקר נבואת זכרי'. . ה' צבאות כידוע ומבואר במ\"א</b>: ראה תו\"ח שמות קיא, סע\"ב."],["726","197","<b>לעת ערב יהי' אור. . ויצאו מים חיים</b>: זכרי' יד, ז-ח."],["727","198","<b>ביום חתונתו זו מ\"ת</b>: שה\"ש ג, יא. תענית כו, ב."]]],[1900420182,"למטה מן התענוג כידוע דהתענוג הוא בהעלם גנוז בעצם הנפש כמו כשמתענג מאיזה בשורה טובה מהשגת הון יקר או גדולה וכה\"ג מבן הנולד כו' והשמחה באה אח\"כ בגילוי בחיצוני' לעין כל לעשות משתה ושמחה ואם אין תענוג אין שמחה כלל כו', אמנם באמת יש שרש לשמחה בנפש עצמו שלמעלה מבחי' התענוג והוא בבחי' מקיף דיחידה שמשם מקור מציאות מהות העונג<sup data-n=\"728\">199</sup> גם בהעלם כו' דאע\"פ שא' אין לך למעלה מן העונג כו' עכ\"ז אין העונג רק חלק א' מן עצם הנפש ממש ולא שאין בנפש זולת העונג שהרי יש מהות הנפש בלא עונג כלל רק שלפעמים תתענג הנפש כו' אבל השמחה הוא בכל מהות הנפש עצמה והיינו כשהנפש עצמה בשמחה שנק' שמחת הנפש שאז יתגלה בה העלם העצמות שבה כמו העונג להתענג בהשפעת חכמה או חסד או להתענג מהון וכבוד ומבנו ואשתו שאם אין הנפש בשמחה לא יתענג כלל אע\"פ שישנם בהעלם בנפש (וכן להיפוך יוכל לשמוח ביסורים היפוך העונג כו'), וכן גם בטבע הטוב להיטיב ולהשפיע אע\"פ שיש עונג גדול בזה אם אין הנפש שמחה לא ירצה להשפיע כי לא יבא העונג הזה בגילוי בנפשו רק ע\"י השמחה וכן בכל מיני רצון ותענוג, גם בחידוש שכל תלוי' בשמחת הנפש כו', וזהו הטעם שאנו רואים שהשמחה טבעה להביא כל העלם מצפון לגילוי כו' כמו גם סוד סתום ממצפון לבבו שנוגע לנפשו יגלה בעת שמחת לבו וכל סוד דבר חכמה עמוקה שלא הי' מגלה לשום אדם יגלה בשמחתו ולא יוכל להתאפק ולעצור רוחו לפי ששמחת הנפש עצמה פותחת כל בחי' סתום והעלם שבה שיבא לגילוי בדיבור דוקא כי הדיבור הוא הפתח ושער שע\"י יתגלה כל הסתום בלי צמצום ולבוש כלל וזהו דוקא בעת השמחה שאז ידבר הכל בגילוי ולא יאמר דבר בהסתר וסתימות כלל, משא\"כ כשאינו בשמחה יכלכל דבריו במשפט השכל איך לכסות דבר שא\"צ לגלות רק מה שצריך לבד כו' וכמו המלך במסבו במשתה ושמחת לבו לא ידבר דברים בדרך הסתר והעלם אלא יגלה כל הסתום וצפון בלבו כמו שהוא בלי העלם דבר כלל וכלל כו' וכך הוא הטעם לענין העונג שבשפע הדיבור בחכ' וכה\"ג שאין זה כ\"א ע\"י שמחת הנפש שישמח לבו ביותר אז יבא לכלל עונג בשפע זאת וירבה לגלות השפע בדיבור בלי העלם וצמצום ולבוש כלל וד\"ל.\n<b>וכך</b> יובן במ\"ש ביום חתונתו זו מ\"ת שהי' מצד שמחת לבו דוקא, שהשמחה הוא בעצמות א\"ס ממש בבחי' מקיף דשעשועי' העצמי' שנק' שעשועי המלך בעצמו שאז מביא כל העלם העונג שבעצמו' המאציל שיתענג בגילוי באור שפע דחכמת התורה בדיבור, והוא מה שחכמת אדם תאיר פניו במ\"ת ברוב אורה ושמחה באמרו אנכי כו' (וכנ\"ל בענין יתרון מעלת קריאת התורה בדיבור בפה על מצות עיון שזהו צד השמחה ששמח בנפשו במה שלומד",[["728","199","<b>אין לך למעלה מן העונג</b>: ספר יצירה פ\"ב מ\"ד."]]],[1900420183,"וקורא בד\"ת שזהו שמחה העצמי' דבחי' יחידה שעי\"ז יתענג בתענוג עצמי בשפע זו שממשיך בגילוי בדיבור כו').\n[כה] <b>וזהו</b> ענין ברכה דשמח תשמח ריעים האהובים כו' שמסיים משמח חתן ואח\"כ כלה כו' שע\"י בחי' השמחה העליונה שבעצמות המאציל ישמח גם לריעים האהובים שהן חו\"כ, והוא בחי' חו\"ב דתושב\"כ ותושבע\"פ, שכאשר ישמח בעצמו דוקא אז יאיר מהעלם התענוג הפשוט לגילוי כמו שהוא בלי לבוש כלל מטעם הנ\"ל, ואז יבא האור ושפע גם בחכמה דתורה ע\"י התגלות הדיבור בלי לבוש והעלם כלל, וכמ\"ש ר\"ש חדאי נפשאי לך קראי לך תנאי כו' ורבה הוה אמר מילתא דבדיחותא<sup data-n=\"729\">200</sup> ובדחי רבנן והדר פתח בשמעתתא כו', לפי שבשביל גילוי אור התענוג הפשוט בחכ' שבתורה שיתגלה כמו שהוא בלי צמצום והעלם כלל צ\"ל ע\"י השמחה בעצם הנפש תחלה מפני שהתענוג הזה להשפיע בחכמה בגילוי בדיבור כמו שהוא א\"א להיות כ\"א ע\"י חדוה ושמחה בתחלה מטעם הנ\"ל שאם אין שמחה אין עונג כלל וד\"ל. וזהו עוז וחדוה במקומו<sup data-n=\"730\">201</sup>, פי' עוז הזה היינו עוז דתורה שנק' עוז כמ\"ש ה' עוז לעמו יתן כו', וכאשר משפיע עוז דתורה אינו אלא בחדוה ושמחה דוקא שנק' שמחת חתן שמחה שבמשפיע כאשר רוצה להשפיע בחכ' כמו שהוא בלי לבוש כלל. וז\"ש עוז וחדוה במקומו דוקא כמו שהוא בעצמו שנק' שעשועי המלך בעצמו שאז ישתעשע וישמח בשפע דעוז דתורה כמ\"ש ואהי' אצלו אמון שעשועי' יום יום וקאי בתורה הקדומה שקדמה לעולם שהי' משתעשע ושמח בה כמו שישמח אדם בקריאתו בתורה שנק' שמחה של תורה ששמח משפע זו בחכמה דתורה, ומשמחה וחדוה זו דתו' שבמקומו ממש נמשך שמחה לתורה עצמה, כמו משחקת לפניו כו' וכן אמר אני תורתך שעשעתי<sup data-n=\"731\">202</sup> פועל יוצא, ונק' שמחת כלה שמקבלת משמחת חתן שהחתן משמח את הכלה. וזהו משמח חתן ואח\"כ הולך שפע זו דשמחה מן החתן אל הכלה דאשה בעלה משמחה (כמו שמחת תורה שאחר ש\"ע שהתורה שמחה), כי כמו שא\"א לגילוי התענוג מן המשפיע למקבל בלי לבוש רק ע\"י השמחה דוקא, כך א\"א לתענוג דמקבל שמתענג בקבלת השפע רק ע\"י השמחה דוקא, כמו במ\"ת כאשר התורה נק' חתן וכנ\"י נק' כלה שקיבלו שמחה משמחת חתן, וכמו עכשיו שישמח נפש האדם ממה שלומד וקורא כו' כמ\"ש חדאי נפשאי לך בשבילך קראי ותנאי לשמח הנשמה ולהחיותה מאור דתורה, וכמ\"ש ונשמח בד\"ת כי הם חיינו ממש, ושמחת חו\"כ באה עצמות א\"ס ב\"ה. וז\"ש שמח תשמח שמח לדכורא ותשמח לנוק' כו', וזהו",[["729","200","<b>ר\"ש </b>[רב ששת]<b> חדאי נפשאי. . ורבה הוה אמר מילתא דבדיחותא</b>: פסחים סח, ב. קיז, א [וראה לעיל בהמ\"מ בד\"ה משמח חו\"כ, קרוב לסופו. ושם ע\"ד ב' הגירסאות רבה ורבא]."],["730","201","<b>עוז וחדוה במקומו</b>: דה\"א טז, כז."],["731","202","<b>משחקת לפניו. . אני תורתך שעשעתי</b>: משלי ח, ל. תהלים קיט, ע."]]],[1900420184,"ריעים האהובים משפיע ומקבל שנק' תרין ריעין דלא מתפרשין<sup data-n=\"732\">203</sup>, כמו תושב\"כ ותושבע\"פ חו\"ב כו' וכמו בבנין חוה מאדה\"ר ששמח לשניהם. וזהו כשמחך יצירך בג\"ע מקדם מעוז וחדוה שבמקומו ממש כנ\"ל וד\"ל (וכמו\"כ במצות עיון דתורה לדייק במילין דחכמה כו' שיש בזה שמחת חו\"כ כמשי\"ת שזהו בברכה אחרונה משמח חתן עם הכלה כו' א\"א להיות כ\"א ע\"י שמחה לשמח החו\"כ שיוכל להיות גילוי התענוג הפשוט בעצמות הרצון שלמעלה מן החכמה שהוא העוה\"ב כנ\"ל, וזהו מבחי' מקיף דשעשועי' העליונים כו', ולזה צריך שמחה יותר כי העיון הוא בא בעמל ויגיעת הנפש, וז\"ש דרבא הוה אמר מילתא דבדיחותא ובדחי רבנן כו').\n<b>אך</b> הנה גם בבחי' שמחה זו עצמה שמשמח החו\"כ שמביא מהעלם העצמות דתענוג הפשוט לידי גילוי כמו שהוא בלי לבוש כלל יש הפרש בין משמח חו\"כ למשמח חתן עם הכלה, שזהו ענין ב' ברכות אחרונות דשמח תשמח כו' ואשר ברא כו', והוא ענין ההפרש בין מצות עיון דתורה למצות קריאה בדיבור, דבמצות קריאה בדיבור אמר משמח חתן וכלה, ובמצות עיון אמר משמח חתן עם הכלה כו'.\n[כו] <b>ולהבין</b> ביאור הענין הנה יש להקדים תחלה מ\"ש חכמות בחוץ כו' שיש ב' מיני חכמות חכ' בראש וחכמה בסוף<sup data-n=\"733\">204</sup>, חכמה בראש היינו כמו שהחכמה מאין תמצא, כמו באדם הוא כאשר השכל וחכ' נמשך ונובע מכח המשכיל שבנפש שהוא עצם כח השכל ההיולי שמוליד וממציא כל שכל וחכמה כאשר מתחכם בדבר מה, ולמעלה זהו שנק' בחי' ח\"ס שנובע משם כל שכל וחכמה מאין ליש, או נק' שכל מופלא או חכמה הקדומה כו', והיינו בחי' תושב\"כ שהן אותיות שבח\"ע שנמשך מחכ' העצמי' חכים ולא בחכמה כו', ובחי' חכמה בסוף שנק' ח\"ת זהו השכל והחכמה שבאה בגילוי בדבור בפה, ונק' חכ' שבדיבור לבד כמו פיה פתחה בחכמה<sup data-n=\"734\">205</sup>, שזהו ענין גילוי השכל והחכמה שמתגלה למקבלים ע\"י אותיות הדיבור. ובודאי יש הפרש גדול בין אור השכל והחכמה כמו שהוא במוח החכ' שבראש שבא מאין לגילוי השכל זה באותיות הדבור בבחי' יש גמור, ועכ\"ז הרי אמר דנעוץ תחילתן בסופן<sup data-n=\"735\">206</sup> דוקא דהעיקר שלימות דאור הח\"ע בבחי' תחלה היינו כאשר נמשך ובא בגילוי באותיות הדיבור בפה שנק' חכמה בסוף. וזהו ב' מדריגות דתושב\"כ ותושבע\"פ, דתושב\"כ הוא בבחי' חכ' בראש, כמו ויאמר ה' אל משה כו' שנמשך מעצמות",[["732","203","<b>תרין ריעין דלא מתפרשין</b>: זח\"ג ד, א."],["733","204","<b>חכמות בחוץ. . חכ' בראש וחכ' בסוף</b>: משלי א, כ. זח\"א כו, ב. וראה לעיל ח\"א ע' ריט. ס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תצה. במדבר ח\"א ע' רכד. וש\"נ."],["734","205","<b>פי' פתחה בחכמה</b>: משלי לא, כו."],["735","206","<b>אמר דנעוץ תחילתן בסופן</b>: ס' יצירה פ\"א מ\"ז."]]],[1900420185,"א\"ס בשם הוי' דח\"ע אל משה כו' ועשו להם ציצית וכה\"ג בכל המצות דתושב\"כ, ובחי' חכמה בסוף הוא תושבע\"פ שזהו בחי' התגלות דח\"ע דתושב\"כ באותיות הדיבור בפה דוקא כמ\"ש ודברת בם<sup data-n=\"736\">207</sup> שזהו בחכמה ושכל הנגלה בדיבור לבד, וזהו גם בתושב\"כ עצמו שמצות ת\"ת בקריאה ודבור דוקא וכמ\"ש לא ימיש ס\"ת הזה מפיך וכן למען תהי'<sup data-n=\"737\">208</sup> תורת ה' בפיך כו'. ואמנם לפי שנתחב\"ס דוקא ע\"כ עיקר שלימות דח\"ע דתושב\"כ זהו במצות קריאה בדיבור דוקא שהרי א' לא ימיש ס\"ת הזה מפיך כו' והגית בו יומם ולילה הרי מצות תושב\"כ בהגיון שהוא במח' דוקא והוא לפי ששרשה בח\"ע בבחי' חכמה שבראש ואמנם מפני שנתחב\"ס דוקא ע\"כ מצות תושב\"כ בקריאה דוקא יותר וכמשי\"ת, ומצות קריאה בה עיקר יותר מתושבע\"פ שהרי גם ע\"ה עולה לתורה אע\"פ שאינו מבין כלום יוצא י\"ח בקריאה לבד, אבל תושבע\"פ ששרשה בבחי' ח\"ת בכלל כנ\"ל ונעוץ סובת\"ח דוקא ע\"כ מצות ת\"ת בתושבע\"פ בעיון יותר מבקריאה, והוא כמו לדייק במילין דאורייתא שהוא בחכ' שבראש כו' וד\"ל.\n<b>(ושרש</b> הענין הוא כידוע ומבואר במ\"א בהפרש שבין אותיו' דתושב\"כ שהן אותיות עצמיי' שכל אור העצמו' דא\"ס גנוז בהן כנ\"ל וע\"כ הן במספר מכוון וקרי וכתיב כו', וזהו כמו אבנים טובות שמאירים בעצם מתחילת הוייתן וכוכבים המאירים בעצם וכמ\"ש אז ראה ויספרה כו', ונק' ספר<sup data-n=\"738\">209</sup>, והן ס\"ר מקוריי' לס\"ר נש\"י, וע\"כ אפי' ע\"ה עולה לתורה<sup data-n=\"739\">210</sup> שיש לו אות מיוחד לשרש נשמתו כו' באור הזרוע לצדיק עליון כו', כמ\"ש במ\"א בענין מיילדות העבריות<sup data-n=\"740\">211</sup> כו').\n<b>וע\"כ</b> מצות קריאה בה עיקר כמ\"ש כי על כל מוצא פי הוי' יחי' האדם כמ\"ש כי אמרתך חייתני<sup data-n=\"741\">212</sup> כו', וזה הי' במ\"ת בדיבור דאנכי שהי' אור וחיות לנש\"י עד שעל כל דיבור כו' דישראל מתקשראן באורייתא<sup data-n=\"742\">213</sup> כו', ולפי שנעוץ תחב\"ס דח\"ע אתמשך בח\"ת<sup data-n=\"743\">214</sup> בחי' מל' ע\"כ עיקר שלימות דח\"ע דתושב\"כ באותיות הדיבור דוקא, ונק' פנים מאירות<sup data-n=\"744\">215</sup> דדכר לנוק' וכמ\"ש חדאי נפשאי לך קראי כו', ולמעלה בחי' מוצא פי הוי' שקורא ושונה כנגדו<sup data-n=\"745\">216</sup> כמו במ\"ת ה\"ז בחי'",[["736","207","<b>ועשו להם ציצית. . ודברת בם</b>: שלח טו, לח. ואתחנן ו, ז."],["737","208","<b>לא ימיש. . למען תהי'</b>: יהושע א, ח. בא יג, ט."],["738","209","<b>אז ראה ויספרה. . ונק' ספר</b>: איוב כח, כז. בראשית ה, א: זה ספר תולדות אדם."],["739","210","<b>וע\"כ אפי' ע\"ה עולה לתורה</b>: ראה גם ס' מאמרי אדה\"ז נביאים ע' רכו. מאמרי אדהאמ\"צ ויקרא ח\"א ע' שפח. במדבר ח\"ב ע' תרלח."],["740","211","<b>כמ\"ש במ\"א בענין מיילדות העבריות</b>: תו\"ח שמות מא, ב."],["741","212","<b>כי על כל מוצא. . כי אמרתך חייתני</b>: עקב ח, ג. תהלים קיט, נ."],["742","213","<b>שעל כל דיבור. . דישראל מתקשראן באורייתא</b>: שבת פח, ב. זח\"ג עג, א."],["743","214","<b>דח\"ע אתמשך בח\"ת</b>: זח\"א קמא, ב."],["744","215","<b>ונק' פנים מאירות</b>: ראה להלן סוף אות כ\"ט. וש\"נ."],["745","216","<b>שקורא ושונה כנגדו</b>: תדא\"ר ריש פי\"ח."]]],[1900420186,"גילוי כל עצמות השעשועי' בשפע זו (שנק' המשכת מ\"ד דחסדים דאו\"י) כנ\"ל. אבל בחי' תושבע\"פ אין האותיות שבה עיקר כלל כי יכול להשכיל ולהבין בהלכה בכל לשון כי אינו אלא פי' וביאור לבד לפרש הדבר איך ומה, ונק' פנים מסבירות, וכמו לדייק במילין דחכ' לעמוד על אמיתי' הדבר כו' (ומה שנק' תושבע\"פ דוקא זהו מפני שנמסרה דברים בע\"פ בקבלה איש מפי איש עד משה שנק' הלכה למשה מסיני כמ\"ש תורה ציוה לנו משה<sup data-n=\"746\">217</sup> כו' כידוע שלא ניתנה בכתב), וזהו כמו אבנים שמזככי' אותם ונעשים מאירים כמו ותהי להם הלבינה לאבן כו' (כמ\"ש במ\"א, ונק' אבן ספיר כמ\"ש ותחת רגליו<sup data-n=\"747\">218</sup> כו', והוא כמו העלאת מ\"נ דנוק' בבחי' או\"ח כו', וזהו כמו טהרה שמביאה לידי קדושה<sup data-n=\"748\">219</sup> שאותיות דתושב\"כ הן בבחי' קדושה בעצם והבירורים דח\"ת דתושבע\"פ בע\"פ בכל לשון הוא בחי' טהרה כו', וזהו בחי' שערות דנוק' שהן ההלכות כנ\"ל בפי' שערך כעדר כו' כמ\"ש סלסלה כו', אבל יש בה יתרון מעלה מתושב\"כ דבינה יתירה<sup data-n=\"749\">220</sup> ניתנה באשה כו' שזהו ענין גילוי אמיתי' הרצה\"ע מבעל הרצון כנ\"ל ע\"י העלא' וביטול דעיון התורה שמעיין המקבל בחכ' שבראש עד שבא לאין דחכמה ולמעלה מן החכמה כמשל בקיעת הקרום מלמטה למעלה כנ\"ל, וז\"ש למחכה לו למאן דדייק כו'. ונמצא מה שהמקבל בא לבחי' ביטול שבחכמה בראש שבו בבחי' או\"ח דנעוץ סובת\"ח מגיע למעלה יותר מאור התענוג הפשוט דח\"ע דמשפיע באותיות דתושב\"כ, וע\"כ בתושבע\"פ מצות עיון עיקר יותר שהוא בח\"ע דנעוץ סובת\"ח, ובתושב\"כ מצות קריאה עיקר דנעוץ תחלתן בסופן כנ\"ל וד\"ל).\n[כז] <b>ומעתה</b> יובן ההפרש בין משמח חו\"כ למשמח חתן עם הכלה. דהנה מבואר למעלה בשרש בחי' השמחה שהוא למעלה מן התענוג שאם אין שמחה אין עונג כלל לפי שיש בכח השמחה שבעצם הנפש להביא לגילוי כל נעלם וצפון גם להתענג בשפע חכמה וחסד וכה\"ג. והנה כמו שמבואר למעלה שיש ב' מיני חכמה ח\"ע וח\"ת ועיקר שלימות דחכמה עילאה שבראש הוא בח\"ת שבא בגילוי בדיבור דוקא, כך ודאי יש ב' מיני עונג, עונג שבחכ' שבראש, ועונג שבחכ' שבדיבור, שעיקר שלימות התענוג הוא בגילוי השפע דחכ' בדיבור, וכמו שאנו רואים שגם שיתענג אדם מאד בחידוש אור שכל חדש במוח החכמה שבראש כאשר נובע מאין ליש מ\"מ עיקר התענוג הוא כשבא בגילוי למקבל בדיבור, כמו לתלמידו שישפיע לו בדיבור וכן בכל השפעת עו\"ע כמו צדקה וחסד לעני או השפעת דכר לנוק' ביחודם כידוע. אך",[["746","217","<b>תורה ציוה לנו משה</b>: ברכה לג, ד."],["747","218","<b>ותהי להם הלבינה לאבן. . כמ\"ש במ\"א. . ותחת רגליו</b>: נח יא, ג. משפטים כד, י. ד\"ה ותחת רגליו, בסה\"מ תקס\"ח ע' עו ואילך."],["748","219","<b>טהרה שמביאה לידי קדושה</b>: ע\"ז כ, ב."],["749","220","<b>סלסלה. . בינה יתירה</b>: משלי ד, ח. נדה מה, ב."]]],[1900420187,"בחי' עונג זה שבשפע בראש ובסוף א\"א להיות כ\"א ע\"י השמחה שישמח בנפשו תחלה בעצם שאז יבא מן ההעלם לגילוי בלי לבוש וצמצום כלל אלא כמו שהוא בעצמו ממש דוקא ואם לא יהי' השפע בעונג מצומצם רק לפי הצריך למקבל ולפעמים ימנע להשפיע כי לא יתענג כלל משפע זו כנ\"ל. וא\"כ ממילא מובן מזה דכמו שיש ב' מיני עונג וחכ' בראש ובסוף כך יש ב' מיני שמחה, שמחה בראש כאשר ישמח בעצמו שיגלה הצפון שזהו לגלות העונג וחכ' מאין ליש לעצמו בלי צמצום כלל, כמו שאנו רואי' שכל שישמח יותר יותר יוכל להביא לגילוי כל חכמה ושכל עמוק וחריף ממקור השכל בלי צמצום ומדה כלל עד שכל רז לא אניס לי', וכמו ר\"ז דהוה בדיחא דעתי' וא' דכל חללי דעלמא<sup data-n=\"750\">221</sup> שהיו שואלים ממנו יגלה וכן א' דרבא הוה א' מילתא דבדיחותא<sup data-n=\"751\">222</sup> ובדחי רבנן והדר פתח בשמעתא כו', וגם מיין המשמח יוכל להביא גם הסוד יותר סתום לגילוי כענין שא' אגברו חמרא אדרדקי<sup data-n=\"752\">223</sup> כי היכא דלימרו מילתא וכה\"ג, שכ\"ז לפי שמצד שמחת הנפש יבא כל העלם לגילוי בלי העלם ולבוש כלל גם לעונג הנעלם וחכ' היותר עמוקה מכלי שכלו בתחלה. והשמחה הב' הוא מה שמביא לגילוי בחכמה שבדיבור למקבלים שהיא גדולה הרבה יותר משמחה הראשונה שהביאה לגילוי מן ההעלם לעצמו כנ\"ל. דהנה הגם שלכאורה שמחה זו שמביאה רק לגלות השכל בדיבור קטן הוא בערך לגבי שמחה העצמית שמביאה לגילוי לבחי' חכמה ועונג שבראש ממקור חוצבה בלי לבוש והעלם כלל כנ\"ל דאין ערך למקבל לגבי המשפיע עצמו, ואע\"פ שאנו רואים שבעת השמחה יגלה הכל בדיבור בלי העלם כלל וכשאינו בשמחה לא יגלה מחכמתו מאומה לזולתו ואם יגלה יכסה טפח כו' וכמו אגברו חמרא כו' כדי שיאמרו בדיבור כו', מ\"מ גם גילוי זה אינו בערך כלל לגבי גילוי חידוש החכמה לעצמו. וכמו שאנו רואים בחוש במי שחידש חכמה עמוקה והמציאה בכח שכלו מן ההעלם במקור ושרש החכמה שישמח מאד ויצהבו פניו ביותר כענין חכמת אדם תאיר פניו ברוב אורה ושמחה כמ\"ש בר\"א שמצא תוספתא חדתא שצהבו פניו כו', (שזהו שמחה העצמי' שקדם בתחלה והביאה מן ההעלם דעונג כו' רק שבאה בגילוי אחר שחידשה ונמשכה מן ההעלם כו' כמ\"ש במ\"א<sup data-n=\"753\">224</sup>), ובודאי שמחה זו גדולה הרבה יותר משמחה שישמח בגלותו כל זה עצמו שחידש לתלמידו שאין כל חדש בזה כלל רק מה שהשפיע' למקבל כמו שהיא בעצמו, וגם זה ודאי לא יש ערך לגילוי זה למקבל לכמו שהוא בעצמו בשעה",[["750","221","<b>ר\"ז. . דכל חללי דעלמא</b>: שבת עז, ב. וראה לעיל ד\"ה שמח תשמח (הראשון) אות י\"ז, ובהמ\"מ שם."],["751","222","<b>דרבא הוה א' מילתא דבדיחותא</b>: פסחים קיז, א [ובגירסת הר\"ח שם ”רבא\", וראה בהמ\"מ לעיל בד\"ה משמח חו\"כ קרוב לסופו]."],["752","223","<b>אגברו חמרא אדרדקי</b>: סנהד' לח, א."],["753","224","<b>בר\"א </b>[ברב אבהו]<b> שמצא תוספתא. . כמ\"ש במ\"א</b>: ראה ירושלמי שבת פ\"ח ה\"א. קה\"ר ח, א (פיסקא ד'). וראה לקו\"ת מסעי צג, ריש ע\"ב (ובהמ\"מ לשם — הוצאת קה\"ת תשד\"מ). ס' מאמרי אדהאמ\"צ בראשית ע' נא. במדבר ח\"א ע' רמא ואילך וע' רנב ואילך. ח\"ב ע' תשל. ובכ\"מ."]]],[1900420188,"שנמשך לו בחידוש מאין והעלם דחכמה ממש כו'. אך אעפ\"כ הנה אנו רואים שעיקר גילוי השמחה העצמי' שהי' לו בעצמותו כשהשיג והמציא שכל החדש מאין אינו אלא כאשר בא לידי גילוי בדיבור לתלמידו המקבל דוקא, אע\"פ שהשמחה שהי' לו בעצמותו ה\"ז במקור דחכ' שבראש והשמחה שממנה יגלה אותה בדיבור אינו רק מצד ענין התגלות שמחת לבו שבא בגילוי יותר למקבל בלבד, אבל באמת שמחת לבו זאת שעי\"ז מגלה השכל בדיבור היא יותר גדולה ועצומה שמגעת בעצמות הנפש בפנימית יותר משמחה הראשונה שהביאה לגילוי עיקר התחדשות השכל וחכ' ממקורה בהעלם. ויש בזה ב' טעמים שהן א'. דהנה אע\"פ שאותיות הדיבור אינו רק גילוי בעלמא בחיצוניות הבל הפה לחוץ למקבלים בלבד מ\"מ היא הנותנת שיבא זה הגילוי ביותר מחמת שמחה גדולה יותר בעצם הנפש עד שיגלה גם בדיבור דוקא, כמשל המלך שכאשר שמח ביותר יצא חוץ לפתח היכלו וישב בשער לבא לגילוי לעין כל דוקא ולדבר עם הפחותים ומתגלה לעין כל כמו שהוא ממש בלי העלם וצמצום כלל כו' (כמו דוד שהי' מפזז ומכרכר<sup data-n=\"754\">225</sup> כו' מעוצם השמחה כו'), וכמ\"ש בזהר על ובט\"ו יום כו' בי' מלכא בתרעא יתיב<sup data-n=\"755\">226</sup> כו' (וכמו משתה שעשה בחצר גינת ביתן כו', וכמ\"ש במ\"א בענין יו\"ט שני דגליות<sup data-n=\"756\">227</sup> כו'). והטעם הב' לפי שעיקר שלימות החכמה דמשפיע שחידש לעצמו אינו אלא כשמביאה למקבל דוקא שאז נשלם שלימותו יותר מבתחלה לפי שנעוץ תחילתן בסופן דוקא כידוע דאין שלימות למשפיע כלל בלתי מקבל שיקבל אור שפעו כמו שאין שלימות לדכר בלא נוק' כמ\"ש בזהר שאינו נק' אדם שלם רק בכללות דדכר ונוק' כמ\"ש ויקרא שמם אדם<sup data-n=\"757\">228</sup> ויא' להם פרו ורבו כו' וז\"ש והתקין לו ממנו בנין כו'), וכך יובן ממילא שעיקר שלימות דשמחה העצמית בחידוש החכ' מאין כו' רק בשמחה זאת שמביא השפעתו לגילוי לחוץ ממנו שהוא באותיות הדיבור למקבל דוקא שנשלם בזה שמחה ועונג שבתחלה לעצמו א\"כ שמחה ועונג זה שבגילוי הדיבור הרבה יותר משמחה שבתחלה כו' מאחר שאם לא תבא בגילוי בדבור אין לה שלימות כלל, וע\"כ אנו רואים שעיקר גילוי כל הצפון ונעלם ביותר גם בכח שכלו אינו אלא בגילוי הדיבור שיתגלה ביותר מה שחידש לעצמו, כמו פיה פתחה בחכמה שפתח הצינור הנעלם המקור לחכמה כמו פתח ר' פלוני כו' וכמ\"ש במ\"א<sup data-n=\"758\">229</sup> וד\"ל.",[["754","225","<b>דוד שהי' מפזז ומכרכר</b>: שמו\"ב ו, טז. וראה לעיל ח\"א ע' רסב."],["755","226","<b>בזהר על ובט\"ו יום. . מלכא בתרעא יתיב</b>: זח\"ג קב, ב."],["756","227","<b>בחצר גינת. . במ\"א בענין יו\"ט שני דגליות</b>: אסתר א, ה. סה\"מ תקס\"ד ע' רמב. ומקבילו בלקו\"ת שמע\"צ צב, סע\"א."],["757","228","<b>בזהר. . בכללות דדכר ונוק'. . ויקרא שמם אדם</b>: ע\"פ בראשית ה, ב. זח\"א נה, ב. קסה, א. ועוד. וראה גם לעיל ח\"א ע' קצא, וס' מאמרי אדהאמ\"צ דברים ח\"ב ע' תנב."],["758","229","<b>פי' פתחה. . שפתח הצינור. . וכמ\"ש במ\"א</b>: משלי לא, כו. וראה ס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' תלו (ובהמ\"מ שם), וע' תשכט. אמרי בינה נה, א."]]],[1900420189,"<b>וכמו\"כ</b> יובן בב' מדריגות דח\"ע וח\"ת שבתורה שיש בזה ב' מיני שמחה ועונג בראש ובסוף, והוא בלימוד התורה בדיבור דוקא דגם שע\"י שמחה תבא התגלות החכמה ממקור בלי לבוש כלל כנ\"ל, אבל העיקר הוא בשמחה הב' בגילוי הדיבור בד\"ת בפה דוקא שבזה נשלם שלימות דשמחה העצמית דחכמה בעיון והשגה ממקורה כמ\"ש לא ימיש ס\"ת הזה מפיך והגית בו כו' דאין שלימות לעיון בהגיון בלי קריאה בדיבור כמ\"ש ר\"ש חדאי נפשאי לך קראי ותנאי בדיבור דוקא כמ\"ש כי על כל מוצא פי ה' בדיבור יחי' האדם שהוא חכמה בראש משום דנעוץ תחב\"ס דוקא מטעם הנ\"ל דהא בהא תלי' דעיקר שלימות דשמחה דחכמה בראש בא דוקא לגילוי בדיבור, וכמו שהי' במ\"ת דכתיב ביום חתונתו שהוא בחי' חתן דמשפיע התורה לישראל ממקורה בהעלם דתוה\"ק בעצמות א\"ס ממש כו' שודאי הי' גילוי דהעלם זה ע\"י שמחה בעצמו ממש כמ\"ש חכמת אדם תאיר פניו כנ\"ל, אבל עיקר שלימות דשמחה זו העליונה (גם במקור כשהיתה התורה אצלו שעשועים יום יום) הי' בהתגלות באותיות הדיבור העליון כמ\"ש וידבר אלקים כו' אנכי כו' שזה הי' מחמת שמחת לבו שמגלה הצפון ונעלם ביותר לפי שנעוץ תחב\"ס דוקא כשנמשך למקבלים כנ\"ל, וזהו ביום שמחת לבו שבא בגילוי יותר בדיבור (וגם עכשיו בכל מי שקורא ושונה שדבר ה' הוא קורא כי דבריו חיים כו' אע\"פ שאינו בשביל מקבל מ\"מ הרי האותיות דתורה עצמ' הן בחי' כלי קיבול שנמשך בהן מעצמות הא\"ס שזהו ענין עוסק בתורה לשמה לשם התורה להמשיך אוא\"ס בתורה כמ\"ש אשר יקראוהו באמת כנ\"ל). וזהו הטעם שבתושב\"כ מצות קריאה בדיבור עיקר יותר מעיון לפי שבה דוקא נשלם שלימות דשמחה ותענוג הפנימי דח\"ע שבה וד\"ל.\n[כח] <b>וזהו</b> ענין הב' ברכות הנ\"ל דמשמח חו\"כ היינו במצות קריאה בתושב\"כ וגם בתושבע\"פ כשקורא ושונה כו' שזהו בחי' ירידת האור ושפע דמשפיע שנק' חתן אל הכלה בחי' מקבל, דמבואר למעלה שיש ב' מיני שמחה, א' שמחה עליונה שבעצמות כאשר מזה יבא להשפיע החכמה ממקורה בהעלם מאין בלי לבוש כלל לעצמו, ואין שלימות לשמחה זאת עד שיבא השפע הזאת בגילוי בדיבור למקבל, שאע\"פ שנשלם בשלימות השמחה העצמי' ע\"י השמחה הב' שמשפיע בדיבור ומבלעדה אין לו שלימות לעצמו גם כי קטנה היא בערך לגבי שמחת העצמי' שהוא כאשר ממשיך ח\"ע ממקורה מפני שנעוץ תחב\"ס דוקא ולזאת הי' עיקר שמחתו לעצמו, מ\"מ הרי קדם שמחתו העצמי' לעצמו בחידוש אור דחכמה בראש וממנה נמשך בגילוי בחכ' שבדיבור כידוע דח\"ע אתמשך בח\"ת, ע\"כ ודאי משמחת חתן נמשך שמחת הכלה שהוא כשמחה הב' שבגילוי הדיבור. וזהו משמח חתן שהוא המשפיע תחלה וממנו נמשך לשמח את הכלה שהוא בחי' המקבל השפע מגילוי הדיבור, וזהו וי\"ו וכלה דוי\"ו זה היינו בחי' המשכת השמחה דשמחת חתן לשמח את הכלה (והיינו בשמחת חתן בגילוי אור שפעו למקבל בדיבור שבשביל זה הי' כל"],[1900420190,"עיקר שמחתו העצמי ולא שמקבל שמחתו משמחת הכלה אע\"פ שאין לו שלימות בשמחה העצמית בלא גילוי הדיבור משום דנעוץ תחב\"ס כנ\"ל), וזה הי' במ\"ת כנ\"ל דמבחי' שמחת חתן כמ\"ש ביום חתונתו גם במקור הח\"ע דתורה הקדומה שהוא שעשועים כו' נמשך משם בגילוי הדיבור לישראל באמרו אנכי כו' לישראל דאע\"פ שזהו שלימות דשמחה העצמית שבתוה\"ק משום דנעוץ תחב\"ס כנ\"ל מ\"מ שמחת חתן קודם לשמחת כלה בבחי' או\"י דהשפע הולך מלמעלה למטה מן המשפיע אל המקבל וכנ\"ל בפי' ביום שמחת לבו כו' וזהו הטעם שבתושב\"כ מצות קריאה עיקר יותר ממצות עיון כנ\"ל וד\"ל.\n<b>(אך</b> עדיין אין זה מובן, דמאחר ששמחת חתן קודם לשמחת כלה עכ\"פ כמ\"ש משמח חו\"כ א\"כ למה מצות קריאה עיקר יותר, דודאי שמחה שבעיון בחכמה בראש ועצמות קודם כנ\"ל אע\"פ שנעוץ תחב\"ס כנ\"ל, ולמה אמר לא ימיש ס\"ת הזה מפיך כו' ואח\"כ והגית בו כו' הי' ראוי שההגיון במח' יהי' תחלה ואח\"כ הקריאה בדיבור, ומה גם שבאמת עיקר שרש תושב\"כ הוא בח\"ע דוקא שהוא ענין עיון וההגיון כנ\"ל וד\"ל. אך הנה הענין הוא דבאמת אין הפי' במשמח חו\"כ דמן החתן נמשך השמחה לכלה כנ\"ל שהרי א' משמח חו\"כ דמשמע דמי שמשמח לחתן הוא שישמח גם לכלה רק שמשמח לחתן תחלה ואח\"כ לכלה כמ\"ש כשמחך יצירך כו' והוא מה שהקדב\"ה משמח לחו\"כ למשפיע ומקבל יחד וארישא קאי שא' שמח תשמח ריעים האהובים כו' שמח לדכורא ותשמח לנוק' שנק' ריעים האהובים כנ\"ל, ומוכרח לומר דגם בבחי' שמחה עליונה שבח\"ע בראש כאשר נמשך מאין והעלם כו' שנק' שמחת חתן בשמחה ועונג לעצמו כנ\"ל זהו באה מלמעלה דוקא, והוא מבחי' שעשועי המלך בעצמו שלמעלה גם מעונג ושעשועי' שבתוה\"ק שישמח לחתן תחלה והוא שמביא שמחה העליונה במקור התורה שיאיר אור דתורה עי\"ז מן ההעלם לגילוי בבחי' התחדשות מאין דתענוג הפשוט בלי העלם וצמצום כלל, והוא מ\"ש ואהי' אצלו שעשועי' שנמשך בחינת שעשועי' העצמיי' בתורה לשמח את החתן שיבא לכלל גילוי מההעלם וכמו אני תורתך שעשעתי<sup data-n=\"759\">230</sup> מבחי' מקיף דשעשועי' העליוני' לגילוי, והוא בחי' שמחת חתן שהוא בחופה דוקא כמ\"ש כחתן יוצא מחופתו כו', וכמ\"ש כי על כל כבוד<sup data-n=\"760\">231</sup> חופה כבוד עליון דתוה\"ק (ונק' מקיף דאו\"י דתענוג הפשוט על אור הח\"ע (כמשי\"ת). וזהו שמח לדכורא ואח\"כ תשמח לנוק' שזהו מה שיבא בגילוי בדיבור למקבל לשמח גם לכלה, וכמו ונשמח בד\"ת כו' חדאי נפשאי כו', כמו במ\"ת שנמשך מדיבור דאנכי שמחה לכלה דישראל מתקשראן באורייתא ואורייתא בקוב\"ה כו' כנ\"ל, וזהו משמח חו\"כ למשפיע ומקבל ח\"ע וח\"ת יחד. ולפי שעיקר השלימות דשמחה דמשפיע בתחלה הוא בסוף בחכ' שבדיבור למקבל שלזאת הי' כל עיקר שמחה העצמי',",[["759","230","<b>אני תורתך שעשעתי</b>: תהלים קיט, ע."],["760","231","<b>כחתן יוצא מחופתו. . כי על כל כבוד</b>: תהלים יט, ו. ישעי' ד, ה."]]],[1900420191,"ע\"כ ממילא מובן דגם מה שמשמח לחתן בשעשועי' המקיפים הי' בשביל שמחה בסוף שבה עיקר שלימות דשעשועי' העליונים שבתוה\"ק מטעם הנ\"ל וד\"ל. וזהו בעטרה כו' ביום חתונתו במקיפים דשעשועי' העצמיי' בשביל גילוי הדיבור שזהו ביום שמחת לבו שעי\"ז נשלם שמחת חתן וזהו לפי שבבחי' או\"י נעוץ תחב\"ס דוקא וסוף מעשה הוא שעלה במח\"ת וזהו נעוץ סוב\"ת וד\"ל.\n<b>(וזהו</b> ענין הג' דיעות בגמרא אם שמים קדמה לארץ או ארץ קדמה לשמים ודיעה הג' דשמים וארץ כא' נבראו שנאמר קורא אני עליהם<sup data-n=\"761\">232</sup> יעמדו יחדיו כו', דמ\"ד שמים קדמו זהו בחי' שמחת חתן דתוה\"ק דמן השמים ניתנה מבחי' מקיף דתענוג הפשוט באור החכמה הקדומה כמ\"ש מן השמים השמיעך כו' וירדה לארץ בגילוי באותיות הדיבור ביו\"ד הדברות כמ\"ש והארץ האירה מכבודו<sup data-n=\"762\">233</sup> בחי' חכמה בסוף כנ\"ל, ומ\"ד ארץ קדמה לשמים לפי שעיקר שלימות דשמים ח\"ע בראש הוא בחכ' שבדיבור דסוף מעשה עלה במח\"ת דהיינו תחלה לחכה\"ק שנק' מחשבה הקדומה לפי שנעוץ תחב\"ס וסוב\"ת כו' וע\"כ אמר לא בשמים היא<sup data-n=\"763\">234</sup> אלא בארץ דוקא, ומ\"ד שמים וארץ ח\"ע וח\"ת כא' נבראו כו' לפי שכ\"ז הוא בבחי' הילוך השפע ממשפיע למקבל בע\"ס דאו\"י דיש מעלה בסוף יותר מבתחלה כו' אבל לגבי מקיפי' דשעשועי' העצמי' שם שוין ממש כא' תחלה וסוף דמשפיע ומקבל להיותו למעלה מבחי' ראש וסוף כו'. וזהו משמח חתן וכלה לשניהם יחד מבלי שימצא ראש וסוף (וז\"ש רבב\"ח לדידי חזי לי<sup data-n=\"764\">235</sup> היכא דנשקי ארעא ורקיע אהדדי כו' כמשי\"ת).\n<b>ומעתה</b> יתורץ ענין הטעם שבתושב\"כ מצות קריאה עיקר כמ\"ש לא ימיש כו', דגם ששמחת חתן בגילוי ההעלם דתוה\"ק קודם לגילוי הדיבור, אבל זה הי' בשביל גילוי הדיבור שבה שלימות ח\"ע הקדומה כנ\"ל, וא\"כ לאחר שירדה התורה בגילוי הדיבור מצות קריאה באותיות עיקר כדי להשלים לח\"ע וכמ\"ש לא בשמים היא כו' דסוף מעשה כו', ולזה אמר לא ימיש ס\"ת הזה מפיך ודברת בם שעי\"ז יהי' שלימות במח' דהגיון בתורה, כי באמת ענין ההגיון בתושב\"כ אינו רק לחשוב ולהרהר בצירופי אותיות שכבר באו בכתב בספר תורה בלבד שז\"ש והגית בו כו' ואין זה ענין עיון שבשכל וסברא לחקור לעיין בטעמי המקראות ולדרוש בהם דרשות בפרטי ידיעת התורה איך ומה שזהו דוקא בתושבע\"פ לבד (כמשי\"ת), ואמנם מצות הגיון שזה במח' והרהור באותיו' זהו בשומע דברי רבו שבדיבור המשפיע נחקק במחשבתו והיינו בחי' התקשרות דמקבל התורה בדיבור ובמחשבה תחלה מקשר דיבורו באותיות",[["761","232","<b>הג' דיעות בגמרא אם שמים קדמה לארץ. . קורא אני עליהם</b>: חגיגה יב, א. ע\"פ ישעי' מח, יג."],["762","233","<b>מן השמים השמיעך. . והארץ האירה מכבודו</b>: ואתחנן ד, לו. יחזקאל מג, ב."],["763","234","<b>לא בשמים היא</b>: נצבים ל, יב. ב\"מ נט, ב."],["764","235","<b>רבב\"ח </b>[רבה בר בר חנה]<b> לדידי חזי לי</b>: ב\"ב עד, א."]]],[1900420192,"הדיבור דתורה בקריאת אותיות ואח\"כ מקשר מחשבתו במח' והיינו במח' שהי' במשפיע התורה בדיבור שא\"א לדיבור בלי מח' בתחלה, כמו בדיבור דאנכי קדם לו במח' דדיבור זה שמאיר בדיבור דאנכי והיינו בחי' מח' דחכ' הקדומה שבתורה שבאה מן ההעלם דאין לגילוי בדיבור שעי\"ז נשלם שלימות דח\"ע לפי שנעוץ תחב\"ס כנ\"ל, וע\"כ אחר קריאה בדיבור אמר והגית במח' שאז נשלם בחי' המחה\"ק דתורה וד\"ל.\n[כט] <b>וביאור</b> הענין הנה ידוע בזהר דאית מחשבה ואית מח'<sup data-n=\"765\">236</sup> כו' דהיינו מח\"ס שבהעלם ומקור החכמה טרם שבאה לגילוי מאין ליש, והוא כמו שהחכ' בבחי' אין דפנימית הכתר שהוא בחי' התענוג הפשוט שבלתי מורכב בחכ' וטעם עדיין אפי' טעם כמוס, כנ\"ל בענין הר הזיתים שהחכמה מאין תמצא אינו רק צומח שבדומם כו', והיינו בחי' החכ' דתוה\"ק שהיתה כלולה במקיף דשעשועי' העצמיי' כנ\"ל, ואח\"כ יצאה לגילוי מאין ליש בבינה שנק' מח' גלוי' שמתגלה גם בדיבור, וכך הי' במ\"ת שבחי' מחה\"ק דתורה של מעלה באה מן ההעלם דעצמו' השעשועי' לגילוי בחכ' שבדיבור שזהו מח' שבאה בגילוי בדיבור למקבל (וזהו שנק' הרהור או הגיון בחי' בליטת אותיות המח' מן ההעלם לגילוי, וז\"ש אז ראה ויספרה באותיות דמחו\"ד שזהו הכינה וגם חקרה כו') וע\"כ אע\"פ שעיקר שרש תושב\"כ בהעלם דח\"ע הקדומה שיצאה לגילוי אבל שלימותה הוא בדיבור דוקא מטעם הנ\"ל דאין שלימות למשפיע בלתי מקבל, וכמו עיקר תפארת דחכמה הוא כאשר יגלנה למקבל כו' ולזה מצות קריאה עיקר גם במקבל התורה שהן ישראל דמתקשראן באורייתא בדיבור ובמח' בהגיון דאותיות התורה כנ\"ל ואע\"פ שבמשפיע כשא' אנכי וכה\"ג קדמה המח' שנק' מאמר סתום לגילוי הדיבור שח\"ע נמשך בח\"ת, אך במקבלים צ\"ל קריאה בדיבור תחלה ואח\"כ ההגיון במח' כענין השמע לאזנך<sup data-n=\"766\">237</sup> מה שאתה מוצא בפיך לבד להיות עולים בבחי' או\"ח מלמטה למעלה, וכמו שבדיבור בקריאה דמשפיע נשלם מחה\"ק שלו כך בקריאה דמקבל באותיות התורה נשלם יותר בחי' מחה\"ק דמשפיע דנעוץ סופן בתחילתן וסוף מעשה כו', והוא ענין ההגיון דמח' דמקבל אחר מצות קריאה דוקא שעולה מלמטה למעלה בבחי' או\"ח להתקשר במח' עליונה דמשפיע אותיות התו' להשלים אותה, וזהו כל הקורא ושונה הקב\"ה יושב ושונה כנגדו בדיבור ומח' עליונה דעי\"ז נשלם מחה\"ק דמשפיע בתחלה (כמו במ\"ת שעכ\"ד פרחה נשמתן כו') וד\"ל (וכמו שישראל מתקשראן באורייתא בצירופי אותיות שבה בדיבור ומעשה מלמטה למעלה, כך אורייתא עצמה מתקשראה בקוב\"ה בעצמות השעשועים שנק' סדכ\"ס דלית מחת\"ב כו' בבחי' או\"ח למעלה יותר מבחי' או\"י דתענוג הפשוט בח\"ע הנ\"ל וד\"ל) (וזהו כי",[["765","236","<b>בזהר דאית מחשבה ואית מח'</b>: ראה תקוני זהר תס\"ט (קטו, א)."],["766","237","<b>השמע לאזנך</b>: ברכות יג, א. וראה גם ס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' שעה. נ\"ך ע' יט [ובהמ\"מ שם]."]]],[1900420193,"אם בתורת ה' חפצו בקריאה בדיבור שיהי' תורת ה' בפיך דוקא לקשר דיבורו בדבר הוי' דתורה להחיות נשמתו כמ\"ש כי אמרתך חייתני, דס\"ר נש\"י מקבלים מס\"ר אותיות התורה, וזהו מעיקרא עביד אדעתי' דנפשי' כו' ואח\"כ ובתורתו יהגה כו' במצות הגיון במחשבה להתקשר במח' דתוה\"ק שזהו כמ\"ש בס' הבהיר דדוד הי' מחבר<sup data-n=\"767\">238</sup> תורה של מעלה בהקב\"ה שהוא בחי' שלימות דח\"ע הקדומה מטעם הנ\"ל וד\"ל.)\nאך הנה כ\"ז הוא בתושב\"כ במצות קריאה והגיון ששרשה בח\"ע דתוה\"ק שהוא המשכת השפע דמשפיע אל המקבל והיא כלולה מב' מדריגות דחכמה בראש וחכמה בסוף ושלימות דח\"ע דמשפיע גם בעונג ושמחה הוא בחכ' שבדיבור משום דנעוץ תחב\"ס וסוב\"ת כנ\"ל. וזהו ענין משמח חו\"כ שכ\"ז הוא בבחי' או\"י דמשפיע שהוא אותיות דתושב\"כ, וגם מה שסוף מעשה עבמח\"ת הכל הוא במשפיע עדיין כו', ואע\"פ שחכ' שבדיבור דמשפיע הוא שלימות דח\"ע שבראש לעצמו כנ\"ל, אין זה שלימות האמיתי עדיין, כי אין זה רק בהשפעת השפע דמשפיע בדיבור שלו למקבל בלבד בבחי' או\"י אע\"פ שנעוץ תחב\"ס כנ\"ל אבל עיקר שלימות האמיתי דמשפיע בדיבור הוא דוקא בקבלת השפע במקבל שאז נשלם שלימות השפע דמשפיע בחכ' בסוף שבו, והוא בבחי' תושבע\"פ שבא לכנ\"י בחכמי ישראל בכל דור ודור כמ\"ש תורה ציוה לנו משה בע\"פ כידוע, וכמו במ\"ת כאשר נתקבל התורה בכנ\"י שנק' קבלת התורה זהו בבחי' ח\"ת בכלל עד\"מ האשה שמקבלת השפע דמ\"ד דדכורא כו' שע\"ז א' בינה יתירה ניתנה באשה כו', כמו בקבלת הנוק' המשכת המ\"ד שעיקר גידול הולד בכל פרטי אברים בט\"ח כו' הכל הוא ממ\"ן דנוק' כמ\"ש אשה כי תזריע<sup data-n=\"768\">239</sup> וילדה כו', כך תושבע\"פ נק' מקבל שבה עיקר שלימות דשפע דתושב\"כ כו'.\n<b>וזהו</b> כללות ענין דמשמח חתן עם הכלה דהכלה עיקר כו', והוא מצות עיון דתושבע\"פ בדיוק במילין דחכמה שע\"ז א' יעשה למחכה לו למעלה גם ממקיף דשעשועים דחכמה דתורה במשפיע שע\"י מצות קריאה בדיבור הנ\"ל, וז\"ש עין לא ראתה כו' וביאור הענין הנה מבואר למעלה ביתרון מעלה שיש בתורה שבע\"פ על תושב\"כ במה שיש בה ידיעת התורה בכל פרטי המעשה איך ומה ובעומק טעם הדבר כו' שאין זה בתושב\"כ כלל, ואמנם זהו רק לגבי המקבל בלבד שעוסק בתורה שלא יוכל לידע כלום מתושב\"כ רק בתושבע\"פ כמו במצות ציצית לידע איך לעשות הציצית ממ\"ש ועשו להם ציצית רק כשלומד הלכות ציצית וכן במצות תפילין במ\"ש וקשרתם כו' לא ידע כלום",[["767","238","<b>בס' הבהיר דדוד הי' מחבר</b>: ספר הבהיר סקצ\"ו. זח\"ג רכב, ב. וראה לעיל ח\"א ע' יח. ס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' תתסז, ובהמ\"מ שם."],["768","239","<b>אשה כי תזריע</b>: תזריע יב, ב."]]],[1900420194,"עד שילמוד הלכות תפילין וכה\"ג בכל המצות, ואע\"פ שכל דיני ההלכות למדים הכל מן המקרא כמו מנלן אמר קרא כו', ולזה א' דהעוסק במקרא מדה ואינו מדה<sup data-n=\"769\">240</sup> במשנה מדה ומקבלים עלי' שכר, אך העוסק בתלמוד אין לך מדה גדולה הימנה כו', וגם בספרי הקבלה אמר דמקרא בעשי'<sup data-n=\"770\">241</sup> ומשנה ביצירה ותלמוד בבריאה כו', ולכאורה זהו פלא גדול דמהיכן יהי' יתרון מעלה כזו במקבל יותר מן המשפיע, מאחר דבחי' ח\"ת דתושבע\"פ מקבל הכל מתושב\"כ וכידוע דתושב\"כ נק' פנים מאירות ותושבע\"פ נק' פנים מסבירות<sup data-n=\"771\">242</sup> כו'. אמנם באמת ודאי כל ידיעת חידושי הדינים וההלכות שבתושבע\"פ גם מה שכל תלמיד ותיק<sup data-n=\"772\">243</sup> עתיד לחדש כו' ניתנה למשה בסיני כו' והכל הוא בתושב\"כ דוקא, כמו ר\"ע שהי' דורש<sup data-n=\"773\">244</sup> על כל קוץ כו' תילי תילים של הלכות כו', א\"כ אצל המשפיע שהן אותיות תושב\"כ יש בהם כל הפרטי' דהלכות דתושבע\"פ, כמ\"ש וקשרתם כו' כלול בזה כל הלכות תפילין בפרט באמרו וקשרתם וכן ועשו להם ציצית בסוכות תשבו וכה\"ג כלול בזה כל הלכות ציצית וכל הלכות סוכה כו', רק שהוא בהעלם באותיות הללו ולא נודע רק למשפיע ולא למקבל, וגם מה שיש כח בתושבע\"פ לברר וללבן הלכות בעיון ודיוק כו' ולעשות פירוש וביאור בפרט על כל מה שכתוב בתושב\"כ גם זה נמשך מכח המשפיע דתושב\"כ כידוע דח\"ע הוא דאתמשך בח\"ת כמ\"ש תנו עוז לאלקים<sup data-n=\"774\">245</sup> כו' ואין כח ועוז זה בח\"ת דתושבע\"פ רק כפי שנמשך מן המשפיע באותו המדה והשיעור שהוא לפי שעלה ברצון וחכמה הקדומה דתורה שלמעלה כשהיתה אצלו אמון כו' באופן הצריך לתקן לעה\"ד להעלות לרפ\"ח כו' ולא יותר וכמ\"ש אשר ברא אלקי' לעשות לתקן<sup data-n=\"775\">246</sup> כו' שזהו ענין מה שסוף מעשה בתכלית הבירורים דח\"ת עלה במח\"ת דוקא, וא\"כ איך אפשר לומר שיש כח וחכ' ובינה יתירה בתושבע\"פ יותר מתושב\"כ כנ\"ל.\n[ל] <b>אך</b> הענין הוא כידוע שיש ב' מיני בירורים הא' בבחי' או\"י דח\"ע הקדומה הנ\"ל והב' בירורים שבבחי' או\"ח דח\"ת הנ\"ל. והענין הוא, דודאי כל מה שנמשך באותיות דתושב\"כ מח\"ע הקדומה דאורייתא מח\"ע נפקת<sup data-n=\"776\">247</sup> הכל בא במדה ושיעור בבחי' בירור דחכ' שלמעלה דוקא כמ\"ש מי מדד בשעלו מים",[["769","240","<b>דהעוסק במקרא מדה ואינה מדה</b>: ב\"מ לג, א."],["770","241","<b>דמקרא בעשי'</b>: פע\"ח שער הנהגת הלימוד (שי\"ז). טעמי המצות ושער המצות פ' ואתחנן. תניא פ\"מ (בהגה\"ה אחרונה). אגה\"ק סכ\"ו. ועוד."],["771","242","<b>וכידוע דתושב\"כ נק' פנים מאירות ותושבע\"פ נק' פנים מסבירות</b>: ראה לעיל ח\"א ע' טו. וש\"נ."],["772","243","<b>מה שכל תלמיד ותיק</b>: ראה לעיל ריש אות ז. וש\"נ."],["773","244","<b>ר\"ע שהי' דורש</b>: מנחות כט, ב."],["774","245","<b>תנו עוז לאלקים</b>: תהלים סח, לה. וראה לעיל ח\"א ע' רסד."],["775","246","<b>אשר ברא אלקים לעשות לתקן</b>: ראה לעיל ריש אות י\"ח. וש\"נ."],["776","247","<b>דאורייתא מח\"ע נפקת</b>: זח\"ב סב, א. פה, א. קכא, א. ועוד."]]]]});
